window.GIFT445_COMMUNITY_QUESTIONS = [{"id":"community-mid-burden-of-disease-c78b4fe7","subjectId":"community","lecture":"Burden of Disease","assessment":"Midterm","sourceBatch":"443","sourceLabel":"Community Medicine Gift","stem":"what is the total, cumulative consequences of a defined disease or a range of harmful diseases in a community","options":[{"id":"A","text":"burden of disease"},{"id":"B","text":"mortality"},{"id":"C","text":"morbidity"},{"id":"D","text":"health"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is burden of disease. Burden of disease is the cumulative health loss and wider consequences produced by disease or injury in a population, compared with an ideal of full health.","sourceLocations":[{"assessment":"Midterm","batch":"443","questionNumber":1,"sourceType":"Gift"}],"references":[{"title":"WHO — Global Health Estimates","url":"https://www.who.int/data/global-health-estimates"}],"lectureOrder":7,"referenceOrder":57001},{"id":"community-mid-surveillance-and-screening-d70b9dda","subjectId":"community","lecture":"Surveillance and Screening","assessment":"Midterm","sourceBatch":"443","sourceLabel":"Community Medicine Gift","stem":"Infectious disease screened in premarital screening :","options":[{"id":"A","text":"HPV"},{"id":"B","text":"HCV"},{"id":"C","text":"Chlamydia"},{"id":"D","text":"Gonorrhea"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is HCV. Secondary prevention detects disease early in apparently healthy people so timely treatment can reduce progression or complications.","sourceLocations":[{"assessment":"Midterm","batch":"443","questionNumber":2,"sourceType":"Gift"}],"references":[{"title":"WHO — Screening programmes: a short guide","url":"https://www.who.int/publications/i/item/9789289054782"}],"lectureOrder":5,"referenceOrder":57002},{"id":"community-mid-surveillance-and-screening-897728ac","subjectId":"community","lecture":"Surveillance and Screening","assessment":"Midterm","sourceBatch":"443","sourceLabel":"Community Medicine Gift","stem":"In a diabetic screening taste with a population of 200 and and a diabetes prevalence of 50% Sensitivity 85% and specificity 90% How many will test positive?","options":[{"id":"A","text":"110"},{"id":"B","text":"100"},{"id":"C","text":"85"},{"id":"D","text":"95"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C?","aiAnswer":"D","aiSuggestion":"The calculated number of positive tests is 95: 85 true positives plus 10 false positives. The Gift records C (85).","verification":"conflict","explanation":"With 50% prevalence in 200 people, 100 have diabetes and 100 do not. Sensitivity 85% gives 85 true positives; specificity 90% gives 10 false positives. Total positive tests = 85 + 10 = 95, so the AI answer is D while the Gift records C.","sourceLocations":[{"assessment":"Midterm","batch":"443","questionNumber":3,"sourceType":"Gift"}],"references":[{"title":"WHO — Screening programmes: a short guide","url":"https://www.who.int/publications/i/item/9789289054782"}],"lectureOrder":5,"referenceOrder":57003},{"id":"community-mid-social-and-behavioral-health-da5a8263","subjectId":"community","lecture":"Social and Behavioral Health","assessment":"Midterm","sourceBatch":"443","sourceLabel":"Community Medicine Gift","stem":"Mohammed used to smoke 5 cigarettes each day , and stopped smoking. After 5 years his father died and was sad and returned to smoking again but fewer cigarettes. He showed you that he has no intention to stop smoking , which one of the following describes his stage right now?","options":[{"id":"A","text":"precontemplation"},{"id":"B","text":"contemplation"},{"id":"C","text":"preparation"},{"id":"D","text":"relapse"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is precontemplation. In precontemplation the person is not intending to change soon; counselling focuses on awareness and motivation rather than an immediate action plan.","sourceLocations":[{"assessment":"Midterm","batch":"443","questionNumber":4,"sourceType":"Gift"}],"references":[{"title":"WHO — Health promotion","url":"https://www.who.int/health-topics/health-promotion"}],"lectureOrder":12,"referenceOrder":57004},{"id":"community-mid-social-and-behavioral-health-c75a170c","subjectId":"community","lecture":"Social and Behavioral Health","assessment":"Midterm","sourceBatch":"443","sourceLabel":"Community Medicine Gift","stem":"HPV vaccine was recently introduced to saudi arabia health system, however, the response was unequal For example, a group of the population refuse to receive the vaccine until they review its benefits from literature Based on behavioural change theories which group are these people?","options":[{"id":"A","text":"Early majority"},{"id":"B","text":"Late Majority"},{"id":"C","text":"Laggards"},{"id":"D","text":"Early adopters"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Late Majority. Diffusion-of-innovations categories differ by readiness to adopt: innovators and early adopters move first, the majorities wait for increasing evidence or social proof, and laggards adopt last.","sourceLocations":[{"assessment":"Midterm","batch":"443","questionNumber":5,"sourceType":"Gift"}],"references":[{"title":"WHO — Health promotion","url":"https://www.who.int/health-topics/health-promotion"}],"lectureOrder":12,"referenceOrder":57005},{"id":"community-mid-adolescent-and-child-health-0071f099","subjectId":"community","lecture":"Adolescent and Child Health","assessment":"Midterm","sourceBatch":"443","sourceLabel":"Community Medicine Gift","stem":"You are in charge of school health in the ministry of health and you are tasked with classifying child mortality \"from birth till 7 days after\". What is the indicator?","options":[{"id":"A","text":"Perinatal deaths"},{"id":"B","text":"Neonatal deaths"},{"id":"C","text":"Post-neonatal deaths"},{"id":"D","text":"Early neonatal deaths"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Early neonatal deaths. Deaths during the first seven completed days after birth are early neonatal deaths; neonatal mortality includes the entire first 28 days.","sourceLocations":[{"assessment":"Midterm","batch":"443","questionNumber":6,"sourceType":"Gift"}],"references":[{"title":"WHO — Adolescent health","url":"https://www.who.int/health-topics/adolescent-health"}],"lectureOrder":10,"referenceOrder":57006},{"id":"community-mid-disparities-in-health-6097ee75","subjectId":"community","lecture":"Disparities in Health","assessment":"Midterm","sourceBatch":"443","sourceLabel":"Community Medicine Gift","stem":"150 death per 100,000 occured after road accidents, which specific mortality describes this rate?","options":[{"id":"A","text":"Crude mortality rate"},{"id":"B","text":"cause specific mortality"},{"id":"C","text":"age specific mortality"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is cause specific mortality. A cause-specific mortality rate uses deaths from the named cause in the numerator and the relevant population in the denominator over a stated period.","sourceLocations":[{"assessment":"Midterm","batch":"443","questionNumber":7,"sourceType":"Gift"}],"references":[{"title":"WHO — Health inequities and their causes","url":"https://www.who.int/news-room/facts-in-pictures/detail/health-inequities-and-their-causes"}],"lectureOrder":8,"referenceOrder":57007},{"id":"community-mid-determinants-of-health-7063f3a8","subjectId":"community","lecture":"Determinants of Health","assessment":"Midterm","sourceBatch":"443","sourceLabel":"Community Medicine Gift","stem":"A man feels sick but didn’t see a physician, what is this called :","options":[{"id":"A","text":"Illness"},{"id":"B","text":"Disease"},{"id":"C","text":"Sickness"},{"id":"D","text":"Disorder"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Illness. Illness is the person's subjective experience of feeling unwell; disease is a professionally identified pathology, and sickness is the social role or consequence attached to the condition.","sourceLocations":[{"assessment":"Midterm","batch":"443","questionNumber":8,"sourceType":"Gift"}],"references":[{"title":"WHO — Social determinants of health","url":"https://www.who.int/health-topics/social-determinants-of-health"}],"lectureOrder":4,"referenceOrder":57008},{"id":"community-mid-natural-history-of-disease-and-conce-473b49f4","subjectId":"community","lecture":"Natural History of Disease and Concepts of Prevention and Control","assessment":"Midterm","sourceBatch":"443","sourceLabel":"Community Medicine Gift","stem":"Educating patients in the community about diabetic foot and improving foot hygiene, is what type of prevention?","options":[{"id":"A","text":"Primary Intervention"},{"id":"B","text":"Secondary Intervention"},{"id":"C","text":"Tertiary Intervention"},{"id":"D","text":"Primordial Intervention"}],"images":[],"incompleteSource":false,"sourceAnswer":["C","A"],"sourceAnswerNote":"C? Or A","aiAnswer":"C","aiSuggestion":"Because diabetes is already established, foot-care education is intended to prevent complications and is best classified as tertiary prevention.","verification":"conflict","explanation":"The patient already has diabetes, so foot-hygiene education is intended to prevent ulcers and other established-disease complications. This is tertiary prevention; the Gift itself records uncertainty between primary and tertiary prevention.","sourceLocations":[{"assessment":"Midterm","batch":"443","questionNumber":9,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/index.html"}],"lectureOrder":1,"referenceOrder":57009},{"id":"community-mid-prevention-and-control-of-infectious-397ff0bb","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"443","sourceLabel":"Community Medicine Gift","stem":"It was a long case but it’s a child and you want to give him immunoglobulin to act immediately as a type of immunity ?","options":[{"id":"A","text":"Active natural"},{"id":"B","text":"Active artificial"},{"id":"C","text":"Passive natural"},{"id":"D","text":"Passive natural"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":null,"aiSuggestion":"Immediate protection from injected immunoglobulin is artificial passive immunity, but that option is missing; the source also duplicates passive natural immunity.","verification":"conflict","explanation":"Injected immunoglobulin supplies ready-made antibodies, giving immediate but short-lived artificial passive immunity. That correct category is absent because the options duplicate passive natural immunity, so no listed option should be graded correct.","sourceLocations":[{"assessment":"Midterm","batch":"443","questionNumber":10,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":57010},{"id":"community-mid-substance-use-9ea31f79","subjectId":"community","lecture":"Substance Use","assessment":"Midterm","sourceBatch":"443","sourceLabel":"Community Medicine Gift","stem":"Man uses tramadol, a drug used in bone pain. he use it without prescription but it did not affect his work or social life :","options":[{"id":"A","text":"Substance Use"},{"id":"B","text":"Substance misuse"},{"id":"C","text":"Substance Use disorder"},{"id":"D","text":"Abuse"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Substance Use. Using a prescribed-type medicine without medical direction is misuse; a substance-use disorder additionally requires a clinically significant pattern of impaired control, risk or functional harm.","sourceLocations":[{"assessment":"Midterm","batch":"443","questionNumber":11,"sourceType":"Gift"}],"references":[{"title":"WHO — Alcohol, drugs and addictive behaviours","url":"https://www.who.int/teams/mental-health-and-substance-use/alcohol-drugs-and-addictive-behaviours"}],"lectureOrder":14,"referenceOrder":57011},{"id":"community-mid-maternal-health-e0c4b83f","subjectId":"community","lecture":"Maternal Health","assessment":"Midterm","sourceBatch":"443","sourceLabel":"Community Medicine Gift","stem":"A 24 year old female in university is getting married in 6 months, she came to your clinic asking for a contraception method that will delay contraception for 1 year until she graduates. What method will you recommend?","options":[{"id":"A","text":"Oral contraceptive pills"},{"id":"B","text":"Intrauterine device"},{"id":"C","text":"Sterilization"},{"id":"D","text":"coitus interruptus"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B?","aiAnswer":"B","aiSuggestion":"An intrauterine device is a highly effective reversible option and can be removed when pregnancy is desired, although contraceptive choice should be individualized.","verification":"needs-review","explanation":"The recorded answer is Intrauterine device. An IUD is a highly effective long-acting reversible contraceptive that can be removed when pregnancy is desired.","sourceLocations":[{"assessment":"Midterm","batch":"443","questionNumber":12,"sourceType":"Gift"}],"references":[{"title":"WHO — Maternal health","url":"https://www.who.int/health-topics/maternal-health"}],"lectureOrder":11,"referenceOrder":57012},{"id":"community-mid-burden-of-disease-a446dc65","subjectId":"community","lecture":"Burden of Disease","assessment":"Midterm","sourceBatch":"443","sourceLabel":"Community Medicine Gift","stem":"What are DALYs?","options":[{"id":"A","text":"Time lost due to disease or life lost"},{"id":"B","text":"overall life expectancy"},{"id":"C","text":"duration of life lived with disease"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Time lost due to disease or life lost. A DALY is one lost year of healthy life and equals years of life lost from premature death (YLL) plus years lived with disability (YLD). Lower DALYs are better.","sourceLocations":[{"assessment":"Midterm","batch":"443","questionNumber":13,"sourceType":"Gift"}],"references":[{"title":"WHO — Global Health Estimates","url":"https://www.who.int/data/global-health-estimates"}],"lectureOrder":7,"referenceOrder":57013},{"id":"community-mid-adolescent-and-child-health-0fa18687","subjectId":"community","lecture":"Adolescent and Child Health","assessment":"Midterm","sourceBatch":"442","sourceLabel":"Community Medicine Gift","stem":"A researcher is interested in conducting a research on 15-24 year old age group. What age group is he interested in?","options":[{"id":"A","text":"Youth"},{"id":"B","text":"Young people"},{"id":"C","text":"Adolescent"},{"id":"D","text":"Children"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Youth. WHO population terminology commonly uses youth for ages 15–24; adolescence covers ages 10–19.","sourceLocations":[{"assessment":"Midterm","batch":"442","questionNumber":1,"sourceType":"Gift"}],"references":[{"title":"WHO — Adolescent health","url":"https://www.who.int/health-topics/adolescent-health"}],"lectureOrder":10,"referenceOrder":58001},{"id":"community-mid-mental-health-5df2396b","subjectId":"community","lecture":"Mental Health","assessment":"Midterm","sourceBatch":"442","sourceLabel":"Community Medicine Gift","stem":"What was the most recorded mental illness in a national Saudi survey?","options":[{"id":"A","text":"Social Phobia"},{"id":"B","text":"Anxiety and other mood disorders"},{"id":"C","text":"OCD"},{"id":"D","text":"Bipolar"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Anxiety and other mood disorders. The course question groups anxiety and mood disorders as the leading category in the cited national survey; the answer is therefore a population-prevalence finding, not a clinical diagnosis for one patient.","sourceLocations":[{"assessment":"Midterm","batch":"442","questionNumber":2,"sourceType":"Gift"}],"references":[{"title":"WHO — Mental health","url":"https://www.who.int/news-room/fact-sheets/detail/mental-health-strengthening-our-response"}],"lectureOrder":9,"referenceOrder":58002},{"id":"community-mid-determinants-of-health-59e76ca0","subjectId":"community","lecture":"Determinants of Health","assessment":"Midterm","sourceBatch":"442","sourceLabel":"Community Medicine Gift","stem":"A case about a diabetic who moved to a new place and presenting(registering?) to a primary clinic and he is dealing with many stressors and he has dyslipidemia, high bmi and severe left hip pain?","options":[{"id":"A","text":"Intensive therapeutic lifestyle modification treatment"},{"id":"B","text":"Non-intensive therapeutic lifestyle modification treatment"},{"id":"C","text":"???"},{"id":"D","text":"Alternate therapeutic lifestyle modification treatment"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A? Not sure","aiAnswer":"A","aiSuggestion":"The multiple cardiometabolic risks support intensive lifestyle intervention, but the source stem and one option are incomplete.","verification":"needs-review","explanation":"The recorded answer is Intensive therapeutic lifestyle modification treatment. Multiple concurrent cardiometabolic risks justify a structured, intensive lifestyle intervention rather than a minimal or unspecified programme, although the source stem is incomplete.","sourceLocations":[{"assessment":"Midterm","batch":"442","questionNumber":3,"sourceType":"Gift"}],"references":[{"title":"WHO — Social determinants of health","url":"https://www.who.int/health-topics/social-determinants-of-health"}],"lectureOrder":4,"referenceOrder":58003},{"id":"community-mid-determinants-of-health-f7f82e54","subjectId":"community","lecture":"Determinants of Health","assessment":"Midterm","sourceBatch":"442","sourceLabel":"Community Medicine Gift","stem":"Scenario , then how to measure physical health?","options":[{"id":"A","text":"Life expectancy"}],"images":[],"incompleteSource":true,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Life expectancy. Life expectancy summarizes the average years a person is expected to live under current mortality patterns, making it useful for broad population comparisons.","sourceLocations":[{"assessment":"Midterm","batch":"442","questionNumber":4,"sourceType":"Gift"}],"references":[{"title":"WHO — Social determinants of health","url":"https://www.who.int/health-topics/social-determinants-of-health"}],"lectureOrder":4,"referenceOrder":58004},{"id":"community-mid-natural-history-of-disease-and-conce-26858328","subjectId":"community","lecture":"Natural History of Disease and Concepts of Prevention and Control","assessment":"Midterm","sourceBatch":"442","sourceLabel":"Community Medicine Gift","stem":"A sexually active female came to your clinic to screen for cervix cancer, which type of prevention is applied in this statement ?","options":[{"id":"A","text":"Primary prevention"},{"id":"B","text":"Secondary prevention"},{"id":"C","text":"Tertiary prevention"},{"id":"D","text":"Primordial"}],"images":[],"incompleteSource":true,"sourceAnswer":null,"sourceAnswerNote":null,"aiAnswer":"B","aiSuggestion":"Cervical cancer screening is secondary prevention.","verification":"supported","explanation":"No reference answer was recorded. Screening an asymptomatic person detects preclinical disease and is therefore secondary prevention.","sourceLocations":[{"assessment":"Midterm","batch":"442","questionNumber":5,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/index.html"}],"lectureOrder":1,"referenceOrder":58005},{"id":"community-mid-maternal-health-fd5eee15","subjectId":"community","lecture":"Maternal Health","assessment":"Midterm","sourceBatch":"442","sourceLabel":"Community Medicine Gift","stem":"Unmet need definition:","options":[{"id":"A","text":"Ratio of annual births to women at a given age or age-group to the population of women at the same age or age-group, in the same year, for a given country, territory, or geographic area. (not sure of this choice)"},{"id":"B","text":"Women who are fecund and sexually active but are not using any method of contraception, and report not wanting any more children or wanting to delay the next child."},{"id":"C","text":"Women who are fecund and sexually active but are using any method of contraception, and report not wanting any more children or wanting to delay the next child."},{"id":"D","text":"Women of reproductive age (15-49) who are married or in union and who are currently using any method of contraception / Total number of women of reproductive age (15-49) who are married or in union) x 100. (not sure of this choice)"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Women who are fecund and sexually active but are not using any method of contraception, and report not wanting any more children or wanting to delay the next child.. Unmet need for family planning refers to fecund, sexually active women who want to delay or avoid pregnancy but are not using a contraceptive method.","sourceLocations":[{"assessment":"Midterm","batch":"442","questionNumber":6,"sourceType":"Gift"}],"references":[{"title":"WHO — Maternal health","url":"https://www.who.int/health-topics/maternal-health"}],"lectureOrder":11,"referenceOrder":58006},{"id":"community-mid-maternal-health-6690add5","subjectId":"community","lecture":"Maternal Health","assessment":"Midterm","sourceBatch":"442","sourceLabel":"Community Medicine Gift","stem":"What of the following is a reversible short acting contraceptive","options":[{"id":"A","text":"implants"},{"id":"B","text":"sterilization"},{"id":"C","text":"condom"},{"id":"D","text":"cortuis leptuim."}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is condom. A condom is a short-acting reversible barrier method; implants and IUDs are long-acting reversible methods, while sterilization is permanent.","sourceLocations":[{"assessment":"Midterm","batch":"442","questionNumber":7,"sourceType":"Gift"}],"references":[{"title":"WHO — Maternal health","url":"https://www.who.int/health-topics/maternal-health"}],"lectureOrder":11,"referenceOrder":58007},{"id":"community-mid-natural-history-of-disease-and-conce-58cbdc0e","subjectId":"community","lecture":"Natural History of Disease and Concepts of Prevention and Control","assessment":"Midterm","sourceBatch":"442","sourceLabel":"Community Medicine Gift","stem":"What kind of prevention is used in schools?","options":[{"id":"A","text":"primary prevention"},{"id":"B","text":"secondary prevention"},{"id":"C","text":"primordial prevention"},{"id":"D","text":"tertiary prevention"}],"images":[],"incompleteSource":true,"sourceAnswer":null,"sourceAnswerNote":null,"aiAnswer":"A","aiSuggestion":"General school-health promotion is usually primary prevention, but the stem is too broad to exclude specific secondary or tertiary activities.","verification":"needs-review","explanation":"No reference answer was recorded. Broad school-health promotion and specific protection act before disease develops, so the best general classification is primary prevention; a more specific school activity could fall at another level.","sourceLocations":[{"assessment":"Midterm","batch":"442","questionNumber":8,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/index.html"}],"lectureOrder":1,"referenceOrder":58008},{"id":"community-mid-tobacco-and-vaping-use-6d853775","subjectId":"community","lecture":"Tobacco and Vaping Use","assessment":"Midterm","sourceBatch":"442","sourceLabel":"Community Medicine Gift","stem":"What of the following NRT requires a perception?","options":[{"id":"A","text":"nicotine patch"},{"id":"B","text":"nicotinic gum"},{"id":"C","text":"inhaler"},{"id":"D","text":"bupropion"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is inhaler. Nicotine-replacement products differ in speed of delivery: nasal spray acts faster than gum or a transdermal patch, while patches provide slower sustained delivery.","sourceLocations":[{"assessment":"Midterm","batch":"442","questionNumber":9,"sourceType":"Gift"}],"references":[{"title":"WHO — Tobacco","url":"https://www.who.int/news-room/fact-sheets/detail/tobacco"}],"lectureOrder":13,"referenceOrder":58009},{"id":"community-mid-determinants-of-health-05b43d67","subjectId":"community","lecture":"Determinants of Health","assessment":"Midterm","sourceBatch":"442","sourceLabel":"Community Medicine Gift","stem":"What is the strongest risk factor for a woman aged 54 years, whose mother died from CVD at the age of 56, with a waist circumference of 92 and a BMI of 22, to develop CVD?","options":[{"id":"A","text":"Age"},{"id":"B","text":"Waist Circumference"},{"id":"C","text":"BMI"},{"id":"D","text":"Family History"}],"images":[],"incompleteSource":false,"sourceAnswer":["D","A"],"sourceAnswerNote":"D or A","aiAnswer":"D","aiSuggestion":"A maternal cardiovascular event at age 56 is a premature family history and is the strongest clearly stated risk factor among the listed choices.","verification":"needs-review","explanation":"The recorded answer is Family History or Age. A first-degree relative with premature cardiovascular disease is a strong non-modifiable risk marker; it cannot be inferred from BMI alone.","sourceLocations":[{"assessment":"Midterm","batch":"442","questionNumber":11,"sourceType":"Gift"}],"references":[{"title":"WHO — Social determinants of health","url":"https://www.who.int/health-topics/social-determinants-of-health"}],"lectureOrder":4,"referenceOrder":58011},{"id":"community-mid-global-demography-concepts-and-popul-075812dc","subjectId":"community","lecture":"Global Demography Concepts and Population Pyramid","assessment":"Midterm","sourceBatch":"442","sourceLabel":"Community Medicine Gift","stem":"At which stage of the demographic transition is a country when it has a death rate of 7 per 1000 and a birth rate of 7 per 1000?","options":[{"id":"A","text":"Stage 2"},{"id":"B","text":"Stage 3"},{"id":"C","text":"Stage 4"},{"id":"D","text":"Stage 5"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Stage 4. Stage 4 has low birth and death rates, so population growth is low and the population is relatively stable.","sourceLocations":[{"assessment":"Midterm","batch":"442","questionNumber":12,"sourceType":"Gift"}],"references":[{"title":"United Nations World Population Prospects","url":"https://www.un.org/development/desa/pd/content/world-population-prospects-2024"}],"lectureOrder":2,"referenceOrder":58012},{"id":"community-mid-tobacco-and-vaping-use-38411098","subjectId":"community","lecture":"Tobacco and Vaping Use","assessment":"Midterm","sourceBatch":"442","sourceLabel":"Community Medicine Gift","stem":"Which one of the following smoking cessation methods requires a prescription?","options":[{"id":"A","text":"Nasal spray"},{"id":"B","text":"Nicotine patch"},{"id":"C","text":"Lozenge"},{"id":"D","text":"Gum"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Nasal spray. Nicotine-replacement products differ in speed of delivery: nasal spray acts faster than gum or a transdermal patch, while patches provide slower sustained delivery.","sourceLocations":[{"assessment":"Midterm","batch":"442","questionNumber":13,"sourceType":"Gift"}],"references":[{"title":"WHO — Tobacco","url":"https://www.who.int/news-room/fact-sheets/detail/tobacco"}],"lectureOrder":13,"referenceOrder":58013},{"id":"community-mid-principles-of-epidemiology-e51b80b7","subjectId":"community","lecture":"Principles of Epidemiology","assessment":"Midterm","sourceBatch":"442","sourceLabel":"Community Medicine Gift","stem":"Which of the following options describes a researcher who wants to replicate a study conducted in the UK and determine if the results are the same in Saudi Arabia?","options":[{"id":"A","text":"External validity"},{"id":"B","text":"Internal validity"},{"id":"C","text":"Incidence"},{"id":"D","text":"Descriptive study"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is External validity. External validity is the extent to which a study's findings generalize to another population or setting, such as from the UK to Saudi Arabia.","sourceLocations":[{"assessment":"Midterm","batch":"442","questionNumber":14,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Measures of Risk","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson3/section2.html"}],"lectureOrder":3,"referenceOrder":58014},{"id":"community-mid-surveillance-and-screening-22b8811f","subjectId":"community","lecture":"Surveillance and Screening","assessment":"Midterm","sourceBatch":"442","sourceLabel":"Community Medicine Gift","stem":"Patient is suspected of retinopathy with type two diabetes. What is the ideal screening time?","options":[{"id":"A","text":"5 years after diagnosis"},{"id":"B","text":"10 years after diagnosis"},{"id":"C","text":"no need for screening"},{"id":"D","text":"20 years after diagnosis"}],"images":[],"incompleteSource":false,"sourceAnswer":null,"sourceAnswerNote":"(Answer should be after diagnosis but that was not an option. if the question was type 1 then the answer will be 5 years after diagnosis)","aiAnswer":null,"aiSuggestion":"For type 2 diabetes, retinopathy screening begins at diagnosis; none of the listed options states this.","verification":"conflict","explanation":"Retinopathy screening in type 2 diabetes begins at diagnosis. The listed time intervals do not include that answer; five years after diagnosis applies to type 1 diabetes, not type 2.","sourceLocations":[{"assessment":"Midterm","batch":"442","questionNumber":15,"sourceType":"Gift"}],"references":[{"title":"WHO — Screening programmes: a short guide","url":"https://www.who.int/publications/i/item/9789289054782"}],"lectureOrder":5,"referenceOrder":58015},{"id":"community-mid-social-and-behavioral-health-67f77015","subjectId":"community","lecture":"Social and Behavioral Health","assessment":"Midterm","sourceBatch":"442","sourceLabel":"Community Medicine Gift","stem":"In your clinic a patient want to change his bad habit of smoking and wishes to quit, you decide to to use Bloom’s taxonomy to achieve that and must explain what are the components of that concept to the patient. The three components of that concept are ?","options":[{"id":"A","text":"predisposing factors, Enabling factors , reinforcing factors"},{"id":"B","text":"perceived susceptibility, perceived severity, barriers"},{"id":"C","text":"cognitive, affective,psychomotor"},{"id":"D","text":"predisposing factors, affective , reinforcing factors"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is cognitive, affective,psychomotor. Bloom's three learning domains are cognitive (knowledge), affective (attitudes and values), and psychomotor (skills).","sourceLocations":[{"assessment":"Midterm","batch":"442","questionNumber":16,"sourceType":"Gift"}],"references":[{"title":"WHO — Health promotion","url":"https://www.who.int/health-topics/health-promotion"}],"lectureOrder":12,"referenceOrder":58016},{"id":"community-mid-social-and-behavioral-health-37549476","subjectId":"community","lecture":"Social and Behavioral Health","assessment":"Midterm","sourceBatch":"442","sourceLabel":"Community Medicine Gift","stem":"You are responsible for implementing a new policy of nationwide voluntary school HIV screening and want to appeal to the late majority, what do you do ?","options":[{"id":"A","text":"Give them evidence of the effectiveness of the policy"},{"id":"B","text":"give them numbers of participants thus far"},{"id":"C","text":"Tell them how to participate and they will"},{"id":"D","text":"don’t need convincing they will try as soon is it’s available"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is give them numbers of participants thus far. Diffusion-of-innovations categories differ by readiness to adopt: innovators and early adopters move first, the majorities wait for increasing evidence or social proof, and laggards adopt last.","sourceLocations":[{"assessment":"Midterm","batch":"442","questionNumber":17,"sourceType":"Gift"}],"references":[{"title":"WHO — Health promotion","url":"https://www.who.int/health-topics/health-promotion"}],"lectureOrder":12,"referenceOrder":58017},{"id":"community-mid-social-and-behavioral-health-c9733e31","subjectId":"community","lecture":"Social and Behavioral Health","assessment":"Midterm","sourceBatch":"442","sourceLabel":"Community Medicine Gift","stem":"You want to implement a new policy about COVID vaccine and want to appeal to the innovators. What tactics do you develop?","options":[{"id":"A","text":"can’t convince them you need to apply fear tactics and pressure"},{"id":"B","text":"don’t need much convincing , just tell them that the vaccine exists and they will take it"},{"id":"C","text":"tell them how to take the vaccine and they will take it"},{"id":"D","text":"Give them evidence of the effectiveness of the vaccine"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is don’t need much convincing , just tell them that the vaccine exists and they will take it. Diffusion-of-innovations categories differ by readiness to adopt: innovators and early adopters move first, the majorities wait for increasing evidence or social proof, and laggards adopt last.","sourceLocations":[{"assessment":"Midterm","batch":"442","questionNumber":18,"sourceType":"Gift"}],"references":[{"title":"WHO — Health promotion","url":"https://www.who.int/health-topics/health-promotion"}],"lectureOrder":12,"referenceOrder":58018},{"id":"community-mid-substance-use-bd75c38c","subjectId":"community","lecture":"Substance Use","assessment":"Midterm","sourceBatch":"442","sourceLabel":"Community Medicine Gift","stem":"A 30 year old female who drinks a glass of alcohol a day the drinking did not effect her work nor her social life in any way, she is not a threat to her self or others Her alcohol habits are classified as?","options":[{"id":"A","text":"Alcohol misuse"},{"id":"B","text":"Alcohol use disorder"},{"id":"C","text":"Alcohol use"},{"id":"D","text":"No substance use"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Alcohol use. Use without impaired control, risky behavior, distress or functional impairment does not by itself meet criteria for a substance use disorder.","sourceLocations":[{"assessment":"Midterm","batch":"442","questionNumber":19,"sourceType":"Gift"}],"references":[{"title":"WHO — Alcohol, drugs and addictive behaviours","url":"https://www.who.int/teams/mental-health-and-substance-use/alcohol-drugs-and-addictive-behaviours"}],"lectureOrder":14,"referenceOrder":58019},{"id":"community-mid-surveillance-and-screening-e36cd54e","subjectId":"community","lecture":"Surveillance and Screening","assessment":"Midterm","sourceBatch":"442","sourceLabel":"Community Medicine Gift","stem":"Sentinel surveillance is ( there was a 50 words scenario that a forgotten, but they just wanted the definition ) ?","options":[{"id":"A","text":"monitoring specific high risk groups"},{"id":"B","text":"monitoring vaccinations status"},{"id":"C","text":"collecting data that is routinely provided"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is monitoring specific high risk groups. Sentinel surveillance uses selected reporting sites or groups to track trends efficiently; it is not intended to enumerate every case in the whole population.","sourceLocations":[{"assessment":"Midterm","batch":"442","questionNumber":20,"sourceType":"Gift"}],"references":[{"title":"WHO — Screening programmes: a short guide","url":"https://www.who.int/publications/i/item/9789289054782"}],"lectureOrder":5,"referenceOrder":58020},{"id":"community-mid-principles-of-epidemiology-6a2523d5","subjectId":"community","lecture":"Principles of Epidemiology","assessment":"Midterm","sourceBatch":"442","sourceLabel":"Community Medicine Gift","stem":"A person is doing a research characterizing health events by time, place, and person, what type of research is it?","options":[{"id":"A","text":"A. Analytical epidemiology"},{"id":"B","text":"Descriptive epidemiology"},{"id":"C","text":"Experimental study"},{"id":"D","text":"Observational study"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Descriptive epidemiology. Descriptive epidemiology characterizes health events by person, place and time; analytic epidemiology then examines why and how they occur.","sourceLocations":[{"assessment":"Midterm","batch":"442","questionNumber":21,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Measures of Risk","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson3/section2.html"}],"lectureOrder":3,"referenceOrder":58021},{"id":"community-mid-determinants-of-health-bb02112b","subjectId":"community","lecture":"Determinants of Health","assessment":"Midterm","sourceBatch":"442","sourceLabel":"Community Medicine Gift","stem":"Health and disease lie along a continuum and there is no cut off point, why is that?","options":[{"id":"A","text":"Because theres no definition of health"},{"id":"B","text":"Because health is not measurable"},{"id":"C","text":"Because the health of the individual is not static"},{"id":"D","text":"Because the health of the individual is not dynamic"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Because the health of the individual is not static. An individual's health state is dynamic and can move in either direction along the continuum; there is therefore no single permanent cut-off between health and disease.","sourceLocations":[{"assessment":"Midterm","batch":"442","questionNumber":22,"sourceType":"Gift"}],"references":[{"title":"WHO — Social determinants of health","url":"https://www.who.int/health-topics/social-determinants-of-health"}],"lectureOrder":4,"referenceOrder":58022},{"id":"community-mid-surveillance-and-screening-6a54f4e6","subjectId":"community","lecture":"Surveillance and Screening","assessment":"Midterm","sourceBatch":"442","sourceLabel":"Community Medicine Gift","stem":"The property of a test to identify the proportion of truly having the disease in a population who are identified with illness by a screening test","options":[{"id":"A","text":"Sensitivity"},{"id":"B","text":"Specificity"},{"id":"C","text":"Positive predictive value"},{"id":"D","text":"Negative predictive value"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A! or C!","aiAnswer":"A","aiSuggestion":"The stem defines sensitivity: the proportion of people who truly have the disease who are identified as positive. The Gift records uncertainty between A and C.","verification":"conflict","explanation":"The stem asks for the proportion of truly diseased people correctly identified by the test, which is sensitivity: TP/(TP+FN). Positive predictive value instead starts from everyone who tested positive.","sourceLocations":[{"assessment":"Midterm","batch":"442","questionNumber":23,"sourceType":"Gift"}],"references":[{"title":"WHO — Screening programmes: a short guide","url":"https://www.who.int/publications/i/item/9789289054782"}],"lectureOrder":5,"referenceOrder":58023},{"id":"community-mid-maternal-health-2336a3db","subjectId":"community","lecture":"Maternal Health","assessment":"Midterm","sourceBatch":"442","sourceLabel":"Community Medicine Gift","stem":"Which of the following best describes maternal mortality ratio?","options":[{"id":"A","text":"Number of maternal deaths per 100,000 women of reproductive age."},{"id":"B","text":"Number of maternal deaths per 100,000 live births."},{"id":"C","text":"Number of maternal deaths per all female deaths"},{"id":"D","text":"Number of maternal deaths per woman entering reproductive period."}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"B","aiSuggestion":"Maternal mortality ratio uses live births as the denominator; option B is correct, while the Gift records A.","verification":"conflict","explanation":"Maternal mortality ratio equals maternal deaths divided by live births, multiplied by 100,000. Therefore option B is correct; option A describes a maternal mortality rate and conflicts with the Gift key.","sourceLocations":[{"assessment":"Midterm","batch":"442","questionNumber":24,"sourceType":"Gift"}],"references":[{"title":"WHO — Maternal health","url":"https://www.who.int/health-topics/maternal-health"}],"lectureOrder":11,"referenceOrder":58024},{"id":"community-mid-maternal-health-63fe11e0","subjectId":"community","lecture":"Maternal Health","assessment":"Midterm","sourceBatch":"442","sourceLabel":"Community Medicine Gift","stem":"Which one of the following vaccinations are recommended for pregnant women?","options":[{"id":"A","text":"MMR vaccine."},{"id":"B","text":"Hepatitis A vaccine."},{"id":"C","text":"German measles vaccine."},{"id":"D","text":"Tetanus toxoid vaccine."}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Tetanus toxoid vaccine.. Inactivated vaccines recommended for maternal protection can be given during pregnancy when indicated; live attenuated vaccines are generally contraindicated.","sourceLocations":[{"assessment":"Midterm","batch":"442","questionNumber":25,"sourceType":"Gift"},{"assessment":"Midterm","batch":"434","questionNumber":8,"sourceType":"Gift"}],"references":[{"title":"WHO — Maternal health","url":"https://www.who.int/health-topics/maternal-health"}],"lectureOrder":11,"referenceOrder":58025},{"id":"community-mid-adolescent-and-child-health-5505fc6a","subjectId":"community","lecture":"Adolescent and Child Health","assessment":"Midterm","sourceBatch":"442","sourceLabel":"Community Medicine Gift","stem":"A woman gives birth and her child dies at the 6th day, which of the following describes this death per 1000 total births?","options":[{"id":"A","text":"Neonatal mortality rate."},{"id":"B","text":"Perinatal mortality rate."},{"id":"C","text":"Infant mortality rate."},{"id":"D","text":"Under 5 mortality rate."}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Perinatal mortality rate.. Perinatal mortality spans late fetal deaths and early neonatal deaths; the lecture uses the course definition from 28 weeks of gestation through the first 7 days after birth.","sourceLocations":[{"assessment":"Midterm","batch":"442","questionNumber":26,"sourceType":"Gift"}],"references":[{"title":"WHO — Adolescent health","url":"https://www.who.int/health-topics/adolescent-health"}],"lectureOrder":10,"referenceOrder":58026},{"id":"community-mid-mental-health-d909e2fc","subjectId":"community","lecture":"Mental Health","assessment":"Midterm","sourceBatch":"442","sourceLabel":"Community Medicine Gift","stem":"A program is trying to diagnose mental disorders early on through screening and providing management, follow up and effective community resources for support. Which of the following types of prevention is used in the program?","options":[{"id":"A","text":"Selective."},{"id":"B","text":"Primary."},{"id":"C","text":"Indicated."},{"id":"D","text":"Primordial."}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Selective.. Selective prevention targets subgroups with a higher-than-average risk before a diagnosable disorder is established.","sourceLocations":[{"assessment":"Midterm","batch":"442","questionNumber":27,"sourceType":"Gift"}],"references":[{"title":"WHO — Mental health","url":"https://www.who.int/news-room/fact-sheets/detail/mental-health-strengthening-our-response"}],"lectureOrder":9,"referenceOrder":58027},{"id":"community-mid-disparities-in-health-57609432","subjectId":"community","lecture":"Disparities in Health","assessment":"Midterm","sourceBatch":"442","sourceLabel":"Community Medicine Gift","stem":"In 2001, a total of 15,555 deaths from Road Traffic Injuries occurred among males and 4,753 deaths occurred among females. The estimated 2001 midyear populations for males and females were 139,813,000 and 144,984,000, respectively. Calculate the mortality rate among females.","options":[{"id":"A","text":"11.1 per 100,000 deaths"},{"id":"B","text":"3.3 per 100,000 deaths"},{"id":"C","text":"3.9 per 100,000 deaths"},{"id":"D","text":"1.11 per 100,000 deaths"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is 3.3 per 100,000 deaths. The sex-specific mortality rate uses deaths in that sex divided by its mid-year population, multiplied by the stated base such as 100,000.","sourceLocations":[{"assessment":"Midterm","batch":"442","questionNumber":28,"sourceType":"Gift"}],"references":[{"title":"WHO — Health inequities and their causes","url":"https://www.who.int/news-room/facts-in-pictures/detail/health-inequities-and-their-causes"}],"lectureOrder":8,"referenceOrder":58028},{"id":"community-mid-social-and-behavioral-health-82dbace5","subjectId":"community","lecture":"Social and Behavioral Health","assessment":"Midterm","sourceBatch":"442","sourceLabel":"Community Medicine Gift","stem":"Which of the following would you consider as a first step in a substance abuse campaign?","options":[{"id":"A","text":"Incorporating substance use control in school health programs."},{"id":"B","text":"Monitor substance use in the community through substance use surveillance."},{"id":"C","text":"Improve substance use healthcare services to ensure treatment and rehabilitation, and avoid relapse."},{"id":"D","text":"Promoting healthy living environment and recreation for youth."}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Monitor substance use in the community through substance use surveillance.. Surveillance establishes the size and pattern of a substance-use problem before a campaign selects and evaluates interventions.","sourceLocations":[{"assessment":"Midterm","batch":"442","questionNumber":29,"sourceType":"Gift"}],"references":[{"title":"WHO — Health promotion","url":"https://www.who.int/health-topics/health-promotion"}],"lectureOrder":12,"referenceOrder":58029},{"id":"community-mid-burden-of-disease-158201fc","subjectId":"community","lecture":"Burden of Disease","assessment":"Midterm","sourceBatch":"442","sourceLabel":"Community Medicine Gift","stem":"The term burden of disease is the “gap” between an ideal situation, where everyone lives free of disease and disability, and.. ?","options":[{"id":"A","text":"the cumulated current health status"},{"id":"B","text":"?"},{"id":"C","text":"?"},{"id":"D","text":"?"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is the cumulated current health status. Burden of disease is the cumulative health loss and wider consequences produced by disease or injury in a population, compared with an ideal of full health.","sourceLocations":[{"assessment":"Midterm","batch":"442","questionNumber":30,"sourceType":"Gift"}],"references":[{"title":"WHO — Global Health Estimates","url":"https://www.who.int/data/global-health-estimates"}],"lectureOrder":7,"referenceOrder":58030},{"id":"community-mid-burden-of-disease-866a4a9c","subjectId":"community","lecture":"Burden of Disease","assessment":"Midterm","sourceBatch":"442","sourceLabel":"Community Medicine Gift","stem":"A pregnant woman faces complications while her delivery and dies at the age of 26, the life expectancy for her is supposed to be 86, calculate her DALY?","options":[{"id":"A","text":"60"},{"id":"B","text":"90"},{"id":"C","text":"40"},{"id":"D","text":"20"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is 60. Life expectancy summarizes the average years a person is expected to live under current mortality patterns, making it useful for broad population comparisons.","sourceLocations":[{"assessment":"Midterm","batch":"442","questionNumber":31,"sourceType":"Gift"}],"references":[{"title":"WHO — Global Health Estimates","url":"https://www.who.int/data/global-health-estimates"}],"lectureOrder":7,"referenceOrder":58031},{"id":"community-mid-social-and-behavioral-health-fce007ed","subjectId":"community","lecture":"Social and Behavioral Health","assessment":"Midterm","sourceBatch":"442","sourceLabel":"Community Medicine Gift","stem":"Mohammad is a smoker, although he doesn’t enjoy smoking. However, he is afraid that his friends won't invite him to their gatherings. Additionally, he believes that everyone at his age smokes. Which of the following type of norms describes his fear of not being invited to gatherings?","options":[{"id":"A","text":"Injunctive"},{"id":"B","text":"Descriptive"},{"id":"C","text":"Cultural"},{"id":"D","text":"Gender"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Injunctive. An injunctive norm concerns perceived approval or disapproval, whereas a descriptive norm concerns what other people are perceived to do.","sourceLocations":[{"assessment":"Midterm","batch":"442","questionNumber":32,"sourceType":"Gift"}],"references":[{"title":"WHO — Health promotion","url":"https://www.who.int/health-topics/health-promotion"}],"lectureOrder":12,"referenceOrder":58032},{"id":"community-mid-global-demography-concepts-and-popul-3b9aee89","subjectId":"community","lecture":"Global Demography Concepts and Population Pyramid","assessment":"Midterm","sourceBatch":"441","sourceLabel":"Community Medicine Gift","stem":"General authority of statistics announced the population numbers in 2021 in Saudi Arabia per age group 0-4 2.6m 5-14 5.6m 15-24 4m 25-34 6m 35-44. 6m 45-54. 4m 55-64 2m 65< 1m What is total dependency ratio?","options":[{"id":"A","text":"39%"},{"id":"B","text":"34%"},{"id":"C","text":"4%"},{"id":"D","text":"70"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is 39%. The dependency ratio compares younger and older dependants with the working-age population, usually expressed per 100 working-age people.","sourceLocations":[{"assessment":"Midterm","batch":"441","questionNumber":1,"sourceType":"Gift"}],"references":[{"title":"United Nations World Population Prospects","url":"https://www.un.org/development/desa/pd/content/world-population-prospects-2024"}],"lectureOrder":2,"referenceOrder":59001},{"id":"community-mid-maternal-health-5da164ca","subjectId":"community","lecture":"Maternal Health","assessment":"Midterm","sourceBatch":"441","sourceLabel":"Community Medicine Gift","stem":"A women want to have long contraceptive","options":[{"id":"A","text":"Tubal ligation"},{"id":"B","text":"Implant"},{"id":"C","text":"Oral contraceptives"},{"id":"D","text":"Withdrawal"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Implant. A contraceptive implant is a highly effective long-acting reversible method; fertility returns after removal and it does not require daily adherence.","sourceLocations":[{"assessment":"Midterm","batch":"441","questionNumber":2,"sourceType":"Gift"}],"references":[{"title":"WHO — Maternal health","url":"https://www.who.int/health-topics/maternal-health"}],"lectureOrder":11,"referenceOrder":59002},{"id":"community-mid-substance-use-4df03f44","subjectId":"community","lecture":"Substance Use","assessment":"Midterm","sourceBatch":"441","sourceLabel":"Community Medicine Gift","stem":"First step in approaching substance abuse campaign","options":[{"id":"A","text":"Surveillance"}],"images":[],"incompleteSource":true,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Surveillance. Surveillance establishes the size and pattern of a substance-use problem before a campaign selects and evaluates interventions.","sourceLocations":[{"assessment":"Midterm","batch":"441","questionNumber":3,"sourceType":"Gift"}],"references":[{"title":"WHO — Alcohol, drugs and addictive behaviours","url":"https://www.who.int/teams/mental-health-and-substance-use/alcohol-drugs-and-addictive-behaviours"}],"lectureOrder":14,"referenceOrder":59003},{"id":"community-mid-tobacco-and-vaping-use-83c8e36d","subjectId":"community","lecture":"Tobacco and Vaping Use","assessment":"Midterm","sourceBatch":"441","sourceLabel":"Community Medicine Gift","stem":"according to WHO which one absorb more rapidly","options":[{"id":"A","text":"patch"},{"id":"B","text":"Nasal spray"},{"id":"C","text":"Gum"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Nasal spray. Nicotine-replacement products differ in speed of delivery: nasal spray acts faster than gum or a transdermal patch, while patches provide slower sustained delivery.","sourceLocations":[{"assessment":"Midterm","batch":"441","questionNumber":4,"sourceType":"Gift"}],"references":[{"title":"WHO — Tobacco","url":"https://www.who.int/news-room/fact-sheets/detail/tobacco"}],"lectureOrder":13,"referenceOrder":59004},{"id":"community-mid-maternal-health-6e6f7584","subjectId":"community","lecture":"Maternal Health","assessment":"Midterm","sourceBatch":"441","sourceLabel":"Community Medicine Gift","stem":"Definition of unmet need in family planning","options":[{"id":"A","text":"Women with unmet need are those who are fecund and sexually active but are not using any method of contraception,and report not wanting any more children or wanting to delay the next child."}],"images":[],"incompleteSource":true,"sourceAnswer":null,"sourceAnswerNote":null,"aiAnswer":"A","aiSuggestion":"The only recorded statement is the standard definition of unmet need; the source did not provide a conventional set of choices.","verification":"needs-review","explanation":"No reference answer was recorded. Unmet need for family planning refers to fecund, sexually active women who want to delay or avoid pregnancy but are not using a contraceptive method.","sourceLocations":[{"assessment":"Midterm","batch":"441","questionNumber":5,"sourceType":"Gift"},{"assessment":"Midterm","batch":"441","questionNumber":19,"sourceType":"Gift"}],"references":[{"title":"WHO — Maternal health","url":"https://www.who.int/health-topics/maternal-health"}],"lectureOrder":11,"referenceOrder":59005},{"id":"community-mid-determinants-of-health-3884b7ac","subjectId":"community","lecture":"Determinants of Health","assessment":"Midterm","sourceBatch":"441","sourceLabel":"Community Medicine Gift","stem":"What is the highest point in the Health Scale?","options":[{"id":"A","text":"Positive health"},{"id":"B","text":"Death"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Positive health. Positive health is the upper end of the health–disease spectrum; death is the lower end.","sourceLocations":[{"assessment":"Midterm","batch":"441","questionNumber":8,"sourceType":"Gift"}],"references":[{"title":"WHO — Social determinants of health","url":"https://www.who.int/health-topics/social-determinants-of-health"}],"lectureOrder":4,"referenceOrder":59008},{"id":"community-mid-adolescent-and-child-health-54bbcfa0","subjectId":"community","lecture":"Adolescent and Child Health","assessment":"Midterm","sourceBatch":"441","sourceLabel":"Community Medicine Gift","stem":"The most common mental illness between a adolescence","options":[{"id":"A","text":"Anxiety and depression"},{"id":"B","text":"schizophrenia"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Anxiety and depression. Anxiety and depressive disorders are among the leading mental-health causes of illness and disability during adolescence.","sourceLocations":[{"assessment":"Midterm","batch":"441","questionNumber":10,"sourceType":"Gift"}],"references":[{"title":"WHO — Adolescent health","url":"https://www.who.int/health-topics/adolescent-health"}],"lectureOrder":10,"referenceOrder":59010},{"id":"community-mid-burden-of-disease-47777989","subjectId":"community","lecture":"Burden of Disease","assessment":"Midterm","sourceBatch":"441","sourceLabel":"Community Medicine Gift","stem":"The YLL years life lost and YLD","options":[{"id":"A","text":"Daly Definition"},{"id":"B","text":"Burden of disease"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Daly Definition. A DALY is one lost year of healthy life and equals years of life lost from premature death (YLL) plus years lived with disability (YLD). Lower DALYs are better.","sourceLocations":[{"assessment":"Midterm","batch":"441","questionNumber":11,"sourceType":"Gift"}],"references":[{"title":"WHO — Global Health Estimates","url":"https://www.who.int/data/global-health-estimates"}],"lectureOrder":7,"referenceOrder":59011},{"id":"community-mid-tobacco-and-vaping-use-ae600ffe","subjectId":"community","lecture":"Tobacco and Vaping Use","assessment":"Midterm","sourceBatch":"441","sourceLabel":"Community Medicine Gift","stem":"Do you have a patient 60 year old with high cholesterol and heavy smoker he’s a risk for cardiovascular disease what is the best modifiable factors to control","options":[{"id":"A","text":"Smoking cessation"},{"id":"B","text":"Lowering cholesterol"},{"id":"C","text":"controlling blood pressure"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Smoking cessation. All tobacco products can cause harm, nicotine drives dependence, and vaping is not harmless. Cessation combines behavioral support with evidence-based pharmacotherapy when appropriate.","sourceLocations":[{"assessment":"Midterm","batch":"441","questionNumber":12,"sourceType":"Gift"}],"references":[{"title":"WHO — Tobacco","url":"https://www.who.int/news-room/fact-sheets/detail/tobacco"}],"lectureOrder":13,"referenceOrder":59012},{"id":"community-mid-surveillance-and-screening-2452b2eb","subjectId":"community","lecture":"Surveillance and Screening","assessment":"Midterm","sourceBatch":"441","sourceLabel":"Community Medicine Gift","stem":"Patient with average risk to colorectal carcinoma what is the initial investigation?","options":[{"id":"A","text":"Colonoscopy 5 years"}],"images":[],"incompleteSource":true,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Colonoscopy 5 years. This asks for a screening strategy in an asymptomatic average-risk person. The recorded interval is retained from the Gift, but screening age and interval depend on the current guideline and test used.","sourceLocations":[{"assessment":"Midterm","batch":"441","questionNumber":14,"sourceType":"Gift"}],"references":[{"title":"WHO — Screening programmes: a short guide","url":"https://www.who.int/publications/i/item/9789289054782"}],"lectureOrder":5,"referenceOrder":59014},{"id":"community-mid-burden-of-disease-c3f2b908","subjectId":"community","lecture":"Burden of Disease","assessment":"Midterm","sourceBatch":"441","sourceLabel":"Community Medicine Gift","stem":"The sum of yll (years of life lost) and yld( years lived with disability) is the definition of which of the following?","options":[{"id":"A","text":"Dalys (disability adjusted life years)"}],"images":[],"incompleteSource":true,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Dalys (disability adjusted life years). A DALY is one lost year of healthy life and equals years of life lost from premature death (YLL) plus years lived with disability (YLD). Lower DALYs are better.","sourceLocations":[{"assessment":"Midterm","batch":"441","questionNumber":15,"sourceType":"Gift"}],"references":[{"title":"WHO — Global Health Estimates","url":"https://www.who.int/data/global-health-estimates"}],"lectureOrder":7,"referenceOrder":59015},{"id":"community-mid-surveillance-and-screening-84d73eaa","subjectId":"community","lecture":"Surveillance and Screening","assessment":"Midterm","sourceBatch":"441","sourceLabel":"Community Medicine Gift","stem":"33 years old female with mother risk to breast cancer what's the investigation?","options":[{"id":"A","text":"After 40 years monogram"},{"id":"B","text":"Immediate monogram"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Immediate monogram. A first-degree family history changes breast-cancer risk assessment and may justify earlier individualized imaging; the recorded Gift answer is shown separately from current clinical guidance.","sourceLocations":[{"assessment":"Midterm","batch":"441","questionNumber":16,"sourceType":"Gift"}],"references":[{"title":"WHO — Screening programmes: a short guide","url":"https://www.who.int/publications/i/item/9789289054782"}],"lectureOrder":5,"referenceOrder":59016},{"id":"community-mid-adolescent-and-child-health-da5a6117","subjectId":"community","lecture":"Adolescent and Child Health","assessment":"Midterm","sourceBatch":"441","sourceLabel":"Community Medicine Gift","stem":"If you calculate mortality within first 7 days of life this fall under which of the following?","options":[{"id":"A","text":"Perinatal mortality"},{"id":"B","text":"Neonatal mortality"},{"id":"C","text":"infant mortality"},{"id":"D","text":"postneonatal mortality"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Perinatal mortality. Deaths during the first seven completed days after birth are early neonatal deaths; neonatal mortality includes the entire first 28 days.","sourceLocations":[{"assessment":"Midterm","batch":"441","questionNumber":17,"sourceType":"Gift"}],"references":[{"title":"WHO — Adolescent health","url":"https://www.who.int/health-topics/adolescent-health"}],"lectureOrder":10,"referenceOrder":59017},{"id":"community-mid-surveillance-and-screening-7e8cbd12","subjectId":"community","lecture":"Surveillance and Screening","assessment":"Midterm","sourceBatch":"441","sourceLabel":"Community Medicine Gift","stem":"Type of surveillance Dynamic seek?","options":[{"id":"A","text":"Passive"},{"id":"B","text":"Active"},{"id":"C","text":"Routine"},{"id":"D","text":"Maybe routine"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Routine. Actively seeking reports or cases is active surveillance, unlike passive surveillance in which routine reporters submit data without prompting.","sourceLocations":[{"assessment":"Midterm","batch":"441","questionNumber":18,"sourceType":"Gift"}],"references":[{"title":"WHO — Screening programmes: a short guide","url":"https://www.who.int/publications/i/item/9789289054782"}],"lectureOrder":5,"referenceOrder":59018},{"id":"community-mid-maternal-health-be1dc658","subjectId":"community","lecture":"Maternal Health","assessment":"Midterm","sourceBatch":"441","sourceLabel":"Community Medicine Gift","stem":"Sara, a 27 year old primigravida present complaining of sore nipple. She is worried that she is not feeding her baby properly.","options":[{"id":"A","text":"strong baby's suckle."},{"id":"B","text":"poor latching."},{"id":"C","text":"inverted nipple."},{"id":"D","text":"prolonged breast feeding"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is poor latching.. Poor latch causes nipple trauma because the infant grasps the nipple rather than taking a large portion of the areola into the mouth.","sourceLocations":[{"assessment":"Midterm","batch":"441","questionNumber":20,"sourceType":"Gift"}],"references":[{"title":"WHO — Maternal health","url":"https://www.who.int/health-topics/maternal-health"}],"lectureOrder":11,"referenceOrder":59020},{"id":"community-mid-principles-of-epidemiology-8b9f95b7","subjectId":"community","lecture":"Principles of Epidemiology","assessment":"Midterm","sourceBatch":"441","sourceLabel":"Community Medicine Gift","stem":"How would you calculate the prevalence of diabetes mellitus in saudi arabia ?","options":[{"id":"A","text":"Cross sectional"},{"id":"B","text":"Cohart"},{"id":"C","text":"case study"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Cross sectional. Prevalence includes all existing cases at a point or during a period. It is influenced by both incidence and disease duration.","sourceLocations":[{"assessment":"Midterm","batch":"441","questionNumber":21,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Measures of Risk","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson3/section2.html"}],"lectureOrder":3,"referenceOrder":59021},{"id":"community-mid-social-and-behavioral-health-a5642f16","subjectId":"community","lecture":"Social and Behavioral Health","assessment":"Midterm","sourceBatch":"441","sourceLabel":"Community Medicine Gift","stem":"Scenario regarding a smoking teenager who smokes and continues smoking because he fears rejection and ridicule from peers, what type of norm?","options":[{"id":"A","text":"Injunctive"},{"id":"B","text":"Social,"},{"id":"C","text":"descriptive,"},{"id":"D","text":"Environmental"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Injunctive. An injunctive norm concerns perceived approval or disapproval, whereas a descriptive norm concerns what other people are perceived to do.","sourceLocations":[{"assessment":"Midterm","batch":"441","questionNumber":22,"sourceType":"Gift"}],"references":[{"title":"WHO — Health promotion","url":"https://www.who.int/health-topics/health-promotion"}],"lectureOrder":12,"referenceOrder":59022},{"id":"community-mid-burden-of-disease-ea621164","subjectId":"community","lecture":"Burden of Disease","assessment":"Midterm","sourceBatch":"441","sourceLabel":"Community Medicine Gift","stem":"Which one of the following measures overall disease burden expressed as cumulative numbers years lost due to disability (YLD) or early death (YLL)?","options":[{"id":"A","text":"DALYs"},{"id":"B","text":"QALYs"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is DALYs. A DALY is one lost year of healthy life and equals years of life lost from premature death (YLL) plus years lived with disability (YLD). Lower DALYs are better.","sourceLocations":[{"assessment":"Midterm","batch":"441","questionNumber":23,"sourceType":"Gift"}],"references":[{"title":"WHO — Global Health Estimates","url":"https://www.who.int/data/global-health-estimates"}],"lectureOrder":7,"referenceOrder":59023},{"id":"community-mid-maternal-health-4ff41a9a","subjectId":"community","lecture":"Maternal Health","assessment":"Midterm","sourceBatch":"441","sourceLabel":"Community Medicine Gift","stem":"Meaning of rooming in","options":[{"id":"A","text":"Mother and baby together"},{"id":"B","text":"Exclusive BF"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Mother and baby together. Rooming-in keeps the mother and newborn together around the clock, supporting responsive feeding, bonding and breastfeeding establishment.","sourceLocations":[{"assessment":"Midterm","batch":"441","questionNumber":25,"sourceType":"Gift"}],"references":[{"title":"WHO — Maternal health","url":"https://www.who.int/health-topics/maternal-health"}],"lectureOrder":11,"referenceOrder":59025},{"id":"community-mid-maternal-health-cd05167e","subjectId":"community","lecture":"Maternal Health","assessment":"Midterm","sourceBatch":"439","sourceLabel":"Community Medicine Gift","stem":"A 22 years old pregnant female currently in her 2nd trimester and doesn’t recall to have received any tetanus toxoid vaccination visits your clinic. What will be your plan for her?","options":[{"id":"A","text":"1 Dose"},{"id":"B","text":"2 Doses"},{"id":"C","text":"3 Doses"},{"id":"D","text":"5 Doses"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is 5 Doses. Tetanus-containing vaccination in pregnancy is based on documented prior doses; an incomplete or unknown history requires an appropriate series with sufficient time before delivery.","sourceLocations":[{"assessment":"Midterm","batch":"439","questionNumber":1,"sourceType":"Gift"}],"references":[{"title":"WHO — Maternal health","url":"https://www.who.int/health-topics/maternal-health"}],"lectureOrder":11,"referenceOrder":61001},{"id":"community-mid-disparities-in-health-125deac5","subjectId":"community","lecture":"Disparities in Health","assessment":"Midterm","sourceBatch":"439","sourceLabel":"Community Medicine Gift","stem":"In 2011. 15,555 deaths from road traffic injuries occurred among males and 4753 deaths occurred among females. The estimated 2011-midyear population for males and females were 139,813,000 and 144,984,000 respectively. What is the male-specific mortality rate from road traffic injuries?","options":[{"id":"A","text":"5.2 RTI deaths per 100,000 population"},{"id":"B","text":"11.1 RTI deaths per 100,000 population"},{"id":"C","text":"3.3 RTI deaths per 100,000 population"},{"id":"D","text":"20.4 RTI deaths per 100,000 population"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is 11.1 RTI deaths per 100,000 population. The sex-specific mortality rate uses deaths in that sex divided by its mid-year population, multiplied by the stated base such as 100,000.","sourceLocations":[{"assessment":"Midterm","batch":"439","questionNumber":2,"sourceType":"Gift"},{"assessment":"Midterm","batch":"438","questionNumber":34,"sourceType":"Gift"}],"references":[{"title":"WHO — Health inequities and their causes","url":"https://www.who.int/news-room/facts-in-pictures/detail/health-inequities-and-their-causes"}],"lectureOrder":8,"referenceOrder":61002},{"id":"community-mid-global-demography-concepts-and-popul-96ab88f7","subjectId":"community","lecture":"Global Demography Concepts and Population Pyramid","assessment":"Midterm","sourceBatch":"439","sourceLabel":"Community Medicine Gift","stem":"in 2017 the death rate in Japan was approximately 9.8 deaths per 1000 population, while the birth rate was 7.7 births per 1000 population. Based on these estimates. which demographic transitional stage is Japan in?","options":[{"id":"A","text":"Stage 1"},{"id":"B","text":"Stage 3"},{"id":"C","text":"Stage 4"},{"id":"D","text":"Stage 5"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Stage 5. In demographic transition stage 5, the birth rate falls below the death rate, leading to population ageing and possible natural decrease.","sourceLocations":[{"assessment":"Midterm","batch":"439","questionNumber":3,"sourceType":"Gift"}],"references":[{"title":"United Nations World Population Prospects","url":"https://www.un.org/development/desa/pd/content/world-population-prospects-2024"}],"lectureOrder":2,"referenceOrder":61003},{"id":"community-mid-social-and-behavioral-health-99c182bb","subjectId":"community","lecture":"Social and Behavioral Health","assessment":"Midterm","sourceBatch":"439","sourceLabel":"Community Medicine Gift","stem":"You have conducted a diabetes prevention survey and found out that many participants check the item \"It takes too much time to monitor my blood sugar every morning\" under what construct of the health belief model would you plot such a statement?","options":[{"id":"A","text":"Perceived susceptibility"},{"id":"B","text":"Perceived severity"},{"id":"C","text":"Perceived benefits"},{"id":"D","text":"Perceived barriers"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Perceived barriers. Perceived barriers are the person's assessment of obstacles or costs that make the recommended behavior difficult, such as time, inconvenience or side effects.","sourceLocations":[{"assessment":"Midterm","batch":"439","questionNumber":4,"sourceType":"Gift"},{"assessment":"Midterm","batch":"438","questionNumber":31,"sourceType":"Gift"}],"references":[{"title":"WHO — Health promotion","url":"https://www.who.int/health-topics/health-promotion"}],"lectureOrder":12,"referenceOrder":61004},{"id":"community-mid-determinants-of-health-822dfb04","subjectId":"community","lecture":"Determinants of Health","assessment":"Midterm","sourceBatch":"439","sourceLabel":"Community Medicine Gift","stem":"The attainment by all citizens of the world by the year 2000 of a level of health that will permit them to lead a socially and economically productive life is the definition of?","options":[{"id":"A","text":"Global Health"},{"id":"B","text":"Health for all"},{"id":"C","text":"Right to health"},{"id":"D","text":"Determinants of health"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Health for all. Health for All expresses the goal that everyone can attain a level of health that permits a socially and economically productive life, with primary health care as a central strategy.","sourceLocations":[{"assessment":"Midterm","batch":"439","questionNumber":5,"sourceType":"Gift"},{"assessment":"Midterm","batch":"437","questionNumber":32,"sourceType":"Gift"}],"references":[{"title":"WHO — Social determinants of health","url":"https://www.who.int/health-topics/social-determinants-of-health"}],"lectureOrder":4,"referenceOrder":61005},{"id":"community-mid-adolescent-and-child-health-6bca547c","subjectId":"community","lecture":"Adolescent and Child Health","assessment":"Midterm","sourceBatch":"439","sourceLabel":"Community Medicine Gift","stem":"The vision realization office 2030 is working with MOH to improve school health. Which one is the most common health condition that they need to focus on in schools?","options":[{"id":"A","text":"Tuberculosis"},{"id":"B","text":"Pneumonia"},{"id":"C","text":"Obesity"},{"id":"D","text":"Asthma"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Obesity. The keyed condition reflects the course's school-health epidemiology; common conditions are prioritized by prevalence, preventability and effect on learning.","sourceLocations":[{"assessment":"Midterm","batch":"439","questionNumber":6,"sourceType":"Gift"},{"assessment":"Midterm","batch":"438","questionNumber":46,"sourceType":"Gift"}],"references":[{"title":"WHO — Adolescent health","url":"https://www.who.int/health-topics/adolescent-health"}],"lectureOrder":10,"referenceOrder":61006},{"id":"community-mid-social-and-behavioral-health-d03671d6","subjectId":"community","lecture":"Social and Behavioral Health","assessment":"Midterm","sourceBatch":"439","sourceLabel":"Community Medicine Gift","stem":"Which of the following is best describing self-efficacy in behavioural changes?","options":[{"id":"A","text":"Acceptance of or confidentiality in an alleged fact or body of facts or right without positive knowledge or proof, perceived truth"},{"id":"B","text":"Ascribing meanings"},{"id":"C","text":"The internal condition of experiencing competence to perform desired task, which will influence the eventual outcome"},{"id":"D","text":"An intellectual acquaintance with facts, truth, or principles gained by sight, experience, or report."}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is The internal condition of experiencing competence to perform desired task, which will influence the eventual outcome. Self-efficacy is confidence in one's ability to perform the target behavior successfully; it strongly influences initiation and persistence.","sourceLocations":[{"assessment":"Midterm","batch":"439","questionNumber":7,"sourceType":"Gift"}],"references":[{"title":"WHO — Health promotion","url":"https://www.who.int/health-topics/health-promotion"}],"lectureOrder":12,"referenceOrder":61007},{"id":"community-mid-determinants-of-health-10ae1b06","subjectId":"community","lecture":"Determinants of Health","assessment":"Midterm","sourceBatch":"439","sourceLabel":"Community Medicine Gift","stem":"What is the lowest point on the health-disease spectrum?","options":[{"id":"A","text":"Severe sickness"},{"id":"B","text":"Disability"},{"id":"C","text":"Death"},{"id":"D","text":"Positive health"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Death. Health is a continuum rather than a binary state because people can move through degrees of wellbeing, illness, disability and recovery; death is its lowest endpoint.","sourceLocations":[{"assessment":"Midterm","batch":"439","questionNumber":8,"sourceType":"Gift"},{"assessment":"Midterm","batch":"438","questionNumber":43,"sourceType":"Gift"}],"references":[{"title":"WHO — Social determinants of health","url":"https://www.who.int/health-topics/social-determinants-of-health"}],"lectureOrder":4,"referenceOrder":61008},{"id":"community-mid-prevention-and-control-of-infectious-ca9a6506","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"439","sourceLabel":"Community Medicine Gift","stem":"Hookworm infections are caused by parasites which are common in Ethiopia. The parasites live in the human intestine and lay eggs which are expelled from the body with the feces into the soil. The eggs grow into worms in the soil, which penetrate the skin of people walking barefooted. What is the mode of transmission in this scenario?","options":[{"id":"A","text":"Indirectly through skin"},{"id":"B","text":"Indirectly through feces"},{"id":"C","text":"Indirectly through contaminated soil"},{"id":"D","text":"Directly through contaminated soil"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Directly through contaminated soil. Soil can act as an environmental reservoir or direct-contact source when infective larvae penetrate exposed skin.","sourceLocations":[{"assessment":"Midterm","batch":"439","questionNumber":10,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":61010},{"id":"community-mid-prevention-and-control-of-infectious-d9282fac","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"439","sourceLabel":"Community Medicine Gift","stem":"Hookworm infections are caused by parasites which are common in Ethiopia. The parasites live in the human intestine and lay eggs which are expelled from the body with the feces into the soil, which penetrate the skin of people walking barefooted. Which of the following is a reservoir in this scenario?","options":[{"id":"A","text":"Feces"},{"id":"B","text":"Hookworm"},{"id":"C","text":"Contaminated soil"},{"id":"D","text":"Human"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Contaminated soil. Soil can act as an environmental reservoir or direct-contact source when infective larvae penetrate exposed skin.","sourceLocations":[{"assessment":"Midterm","batch":"439","questionNumber":11,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":61011},{"id":"community-mid-adolescent-and-child-health-1a4fcb3e","subjectId":"community","lecture":"Adolescent and Child Health","assessment":"Midterm","sourceBatch":"439","sourceLabel":"Community Medicine Gift","stem":"A child born with an immunodeficiency, which of the following vaccine is contraindicated?","options":[{"id":"A","text":"Pertussis"},{"id":"B","text":"Measles"},{"id":"C","text":"HBV"},{"id":"D","text":"Hib"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Measles. Live attenuated measles-containing vaccine is contraindicated in severe immunodeficiency, whereas the listed inactivated or non-live vaccines do not carry the same replication risk.","sourceLocations":[{"assessment":"Midterm","batch":"439","questionNumber":12,"sourceType":"Gift"}],"references":[{"title":"WHO — Adolescent health","url":"https://www.who.int/health-topics/adolescent-health"}],"lectureOrder":10,"referenceOrder":61012},{"id":"community-mid-prevention-and-control-of-infectious-47b47418","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"439","sourceLabel":"Community Medicine Gift","stem":"Which one of the following is the transmission route of COVID-19?","options":[{"id":"A","text":"Direct contact with infected body fluids"},{"id":"B","text":"Ingestion of raw fish"},{"id":"C","text":"Drinking contaminated water"},{"id":"D","text":"Vector borne by mosquito bites"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Direct contact with infected body fluids. Direct transmission occurs through immediate physical contact with an infected person, body fluid, soil or another source without an intervening vehicle or vector.","sourceLocations":[{"assessment":"Midterm","batch":"439","questionNumber":14,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":61014},{"id":"community-mid-adolescent-and-child-health-7ed7027d","subjectId":"community","lecture":"Adolescent and Child Health","assessment":"Midterm","sourceBatch":"439","sourceLabel":"Community Medicine Gift","stem":"What are the recommended vaccines on the national immunization schedule at the age of 9 months?","options":[{"id":"A","text":"PCV, OPV, MCV4, MMR"},{"id":"B","text":"IPV, HepB, DTaP, RV, Hib"},{"id":"C","text":"DTap, OPV, Varicella, MMR"},{"id":"D","text":"Measles, MCV4"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Measles, MCV4. The answer follows the Saudi national immunization schedule presented in the lecture for the nine-month visit; schedule timing should be checked against the current MOH version.","sourceLocations":[{"assessment":"Midterm","batch":"439","questionNumber":15,"sourceType":"Gift"},{"assessment":"Midterm","batch":"438","questionNumber":39,"sourceType":"Gift"}],"references":[{"title":"WHO — Adolescent health","url":"https://www.who.int/health-topics/adolescent-health"}],"lectureOrder":10,"referenceOrder":61015},{"id":"community-mid-prevention-and-control-of-infectious-6acdfa2f","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"439","sourceLabel":"Community Medicine Gift","stem":"A 46 years old woman immigrant of southeast asia, known case of rheumatoid arthritis on medication containing prednisolone. She complained of 4 weeks history of productive cough and fever, which used to come mainly at night and sometimes accompanied by night sweats. Which of the following is the appropriate next step in management?","options":[{"id":"A","text":"No need for intervention as they are asymptomatic"},{"id":"B","text":"Request a quantiferon & do chest x ray"},{"id":"C","text":"Give all family members Isoniazid for 6 months"},{"id":"D","text":"Complete Anti-TB medications for all family members"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Request a quantiferon & do chest x ray. Prolonged cough, fever and night sweats in an immunosuppressed person require evaluation for active pulmonary tuberculosis with chest imaging and microbiologic sputum testing; latent-infection tests alone cannot confirm active disease.","sourceLocations":[{"assessment":"Midterm","batch":"439","questionNumber":17,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":61017},{"id":"community-mid-determinants-of-health-4e6ed3dd","subjectId":"community","lecture":"Determinants of Health","assessment":"Midterm","sourceBatch":"439","sourceLabel":"Community Medicine Gift","stem":"There was a neighbourhood with no sidewalk pavement and the health ministry asked to add a sidewalk to ensure safety. Which one of the health determinants is applied here?","options":[{"id":"A","text":"Biological determinants"},{"id":"B","text":"Socioeconomic determinants"},{"id":"C","text":"Environmental determinants"},{"id":"D","text":"Behavioural determinants"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Environmental determinants. Features of the built and physical environment—such as housing, walkability, crowding, water and pollution—are environmental determinants of health.","sourceLocations":[{"assessment":"Midterm","batch":"439","questionNumber":18,"sourceType":"Gift"}],"references":[{"title":"WHO — Social determinants of health","url":"https://www.who.int/health-topics/social-determinants-of-health"}],"lectureOrder":4,"referenceOrder":61018},{"id":"community-mid-introduction-to-health-policy-9078bb92","subjectId":"community","lecture":"Introduction to Health Policy","assessment":"Midterm","sourceBatch":"439","sourceLabel":"Community Medicine Gift","stem":"Hospital administrative policy and procedures, Department/internal policy and procedures, Clinical practice guidelines. Which one of the following health policies is this policy?","options":[{"id":"A","text":"Global health"},{"id":"B","text":"Health policy"},{"id":"C","text":"Macro health policies"},{"id":"D","text":"Micro health policies"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Micro health policies. Micro policies operate within organizations or services, such as hospital procedures and clinical practice guidelines.","sourceLocations":[{"assessment":"Midterm","batch":"439","questionNumber":20,"sourceType":"Gift"}],"references":[{"title":"WHO — Health policy and systems research","url":"https://www.who.int/teams/alliance-for-health-policy-systems-research"}],"lectureOrder":15,"referenceOrder":61020},{"id":"community-mid-social-and-behavioral-health-0f90f937","subjectId":"community","lecture":"Social and Behavioral Health","assessment":"Midterm","sourceBatch":"439","sourceLabel":"Community Medicine Gift","stem":"A newly diagnosed diabetic patient came to a primary care office and asked about the correct technique to measure blood sugar. The attending doctor provided a real life demonstration to teach him how to use the glucometer. What learning domain did the doctor address?","options":[{"id":"A","text":"Affective domain, attitudes"},{"id":"B","text":"Psychomotor domain, Skills"},{"id":"C","text":"Cognitive domain, knowledge"},{"id":"D","text":"Affective domain, belief"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Psychomotor domain, Skills. The psychomotor domain concerns performing a physical skill; a hands-on demonstration and practice of glucose testing targets this domain.","sourceLocations":[{"assessment":"Midterm","batch":"439","questionNumber":21,"sourceType":"Gift"},{"assessment":"Midterm","batch":"438","questionNumber":50,"sourceType":"Gift"}],"references":[{"title":"WHO — Health promotion","url":"https://www.who.int/health-topics/health-promotion"}],"lectureOrder":12,"referenceOrder":61021},{"id":"community-mid-disparities-in-health-fff4a02f","subjectId":"community","lecture":"Disparities in Health","assessment":"Midterm","sourceBatch":"439","sourceLabel":"Community Medicine Gift","stem":"In H5N1 6 of 18 infected died. With a case fatality rate CFR of 33%. What may cause case fatality to be this high?","options":[{"id":"A","text":"Wrongly diagnosed cases of H1N5"},{"id":"B","text":"Underreport of less severe cases"},{"id":"C","text":"Underreport of death cases"},{"id":"D","text":"Overreport of less severe cases"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Underreport of less severe cases. Case fatality is deaths among diagnosed cases divided by all cases of that disease; it describes severity rather than population risk.","sourceLocations":[{"assessment":"Midterm","batch":"439","questionNumber":22,"sourceType":"Gift"}],"references":[{"title":"WHO — Health inequities and their causes","url":"https://www.who.int/news-room/facts-in-pictures/detail/health-inequities-and-their-causes"}],"lectureOrder":8,"referenceOrder":61022},{"id":"community-mid-principles-of-epidemiology-4e4394a6","subjectId":"community","lecture":"Principles of Epidemiology","assessment":"Midterm","sourceBatch":"439","sourceLabel":"Community Medicine Gift","stem":"You have been called to assist in estimating the burden of diabetes in your region. The team asks you for the best indicator to use to report the burden of diabetes in your region to the ministry of health. What indicator will you use for estimating the burden of such disease in your region?","options":[{"id":"A","text":"Proportion"},{"id":"B","text":"Prevalence"},{"id":"C","text":"Incidence"},{"id":"D","text":"Case-fatality"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Prevalence. Prevalence includes all existing cases at a point or during a period. It is influenced by both incidence and disease duration.","sourceLocations":[{"assessment":"Midterm","batch":"439","questionNumber":23,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Measures of Risk","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson3/section2.html"}],"lectureOrder":3,"referenceOrder":61023},{"id":"community-mid-prevention-and-control-of-infectious-3b334450","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"439","sourceLabel":"Community Medicine Gift","stem":"A 46 years old woman immigrant of southeast asia, known case of rheumatoid arthritis on medication containing prednisolone. She complained of a 4-week history of productive cough and fever, which used to come mainly at night and sometimes accompanied by night sweats. Which of the following is the appropriate next step in management?","options":[{"id":"A","text":"Tuberculin skin test and blood culture"},{"id":"B","text":"Complete blood count and blood cultures"},{"id":"C","text":"Chest x-ray and 3 sputum smear examination"},{"id":"D","text":"Chest x-ray and tuberculin skin test"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Chest x-ray and 3 sputum smear examination. Prolonged cough, fever and night sweats in an immunosuppressed person require evaluation for active pulmonary tuberculosis with chest imaging and microbiologic sputum testing; latent-infection tests alone cannot confirm active disease.","sourceLocations":[{"assessment":"Midterm","batch":"439","questionNumber":24,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":61024},{"id":"community-mid-principles-of-epidemiology-d2440230","subjectId":"community","lecture":"Principles of Epidemiology","assessment":"Midterm","sourceBatch":"439","sourceLabel":"Community Medicine Gift","stem":"In a survey of 1,150 medical students in Riyadh in 2018, a total of 460 reported symptoms of seasonal allergy during the first week of september. What is the prevalence of seasonal allergy in this group?","options":[{"id":"A","text":"25%"},{"id":"B","text":"70%"},{"id":"C","text":"40%"},{"id":"D","text":"10%"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is 40%. Prevalence includes all existing cases at a point or during a period. It is influenced by both incidence and disease duration.","sourceLocations":[{"assessment":"Midterm","batch":"439","questionNumber":25,"sourceType":"Gift"},{"assessment":"Midterm","batch":"438","questionNumber":56,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Measures of Risk","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson3/section2.html"}],"lectureOrder":3,"referenceOrder":61025},{"id":"community-mid-introduction-to-health-policy-e3d0dc53","subjectId":"community","lecture":"Introduction to Health Policy","assessment":"Midterm","sourceBatch":"439","sourceLabel":"Community Medicine Gift","stem":"National health transformation is aiming towards the “triple aims”: which includes improve healthcare outcomes, improve quality of care, and reduce costs. Which of the following actions meet the goals above and is considered the hallmark of this transformation?","options":[{"id":"A","text":"The saudi National Health is building more hospitals and increase caretakers"},{"id":"B","text":"The saudi National Health is improving primary health and early preventions"},{"id":"C","text":"The saudi National Health is putting one body for providers, regulators and provision"},{"id":"D","text":"The saudi National Health is make the referral pathway easier"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is The saudi National Health is improving primary health and early preventions. The Triple Aim links better population health and care experience with lower per-capita cost; workforce wellbeing is often described separately as part of the Quadruple Aim.","sourceLocations":[{"assessment":"Midterm","batch":"439","questionNumber":28,"sourceType":"Gift"}],"references":[{"title":"WHO — Health policy and systems research","url":"https://www.who.int/teams/alliance-for-health-policy-systems-research"}],"lectureOrder":15,"referenceOrder":61028},{"id":"community-mid-surveillance-and-screening-75fb15e4","subjectId":"community","lecture":"Surveillance and Screening","assessment":"Midterm","sourceBatch":"439","sourceLabel":"Community Medicine Gift","stem":"Calculate the positive predictive value Table: | Diseased | Not diseased / Positive | 9 | 351 / Negative | 1 | 4449","options":[{"id":"A","text":"9 / 9 + 351= 2.5%"},{"id":"B","text":"9 / 9 + 1 = 9%"},{"id":"C","text":"351 / 351+ 4449 = 73%"},{"id":"D","text":"1 / 1 + 4449 = 0.02%"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is 9 / 9 + 351= 2.5%. Positive predictive value is TP/(TP+FP) and rises as disease prevalence rises, assuming the test characteristics stay the same.","sourceLocations":[{"assessment":"Midterm","batch":"439","questionNumber":29,"sourceType":"Gift"}],"references":[{"title":"WHO — Screening programmes: a short guide","url":"https://www.who.int/publications/i/item/9789289054782"}],"lectureOrder":5,"referenceOrder":61029},{"id":"community-mid-natural-history-of-disease-and-conce-8b9c2601","subjectId":"community","lecture":"Natural History of Disease and Concepts of Prevention and Control","assessment":"Midterm","sourceBatch":"439","sourceLabel":"Community Medicine Gift","stem":"Khaled is a 50 year old man. He has had diabetes mellitus for the last 20 years. He has been on insulin for the last 15 years. He is on regular follow-up with his primary care physician. His physician gave him his pneumococcal vaccine on this visit. Which type of prevention is being applied in his case?","options":[{"id":"A","text":"Primordial prevention"},{"id":"B","text":"Primary prevention"},{"id":"C","text":"Secondary prevention"},{"id":"D","text":"Tertiary prevention"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Primary prevention. Primary prevention acts before disease begins through health promotion or specific protection. Screening is not primary prevention; it is secondary prevention.","sourceLocations":[{"assessment":"Midterm","batch":"439","questionNumber":30,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/index.html"}],"lectureOrder":1,"referenceOrder":61030},{"id":"community-mid-introduction-to-health-policy-1b233c31","subjectId":"community","lecture":"Introduction to Health Policy","assessment":"Midterm","sourceBatch":"439","sourceLabel":"Community Medicine Gift","stem":"The country’s vision priorities, budgetary decisions, course of action to sustain health. Which one of the following health policies is this policy?","options":[{"id":"A","text":"Global health"},{"id":"B","text":"Health policy"},{"id":"C","text":"Macro health policies"},{"id":"D","text":"Micro health policies"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Macro health policies. Macro policies are national or system-level decisions on priorities, financing and organization of health services.","sourceLocations":[{"assessment":"Midterm","batch":"439","questionNumber":31,"sourceType":"Gift"}],"references":[{"title":"WHO — Health policy and systems research","url":"https://www.who.int/teams/alliance-for-health-policy-systems-research"}],"lectureOrder":15,"referenceOrder":61031},{"id":"community-mid-burden-of-disease-da063369","subjectId":"community","lecture":"Burden of Disease","assessment":"Midterm","sourceBatch":"439","sourceLabel":"Community Medicine Gift","stem":"Interaction between physical ill-health social problems, psychological problems and functional limitations contribute to years lived with disability, disability adjusted life years and death among elderly 70+ years in KSA.Which of the following is the leading burden of disease among elderly in KSA?","options":[{"id":"A","text":"Cardiovascular disease"},{"id":"B","text":"Cancer"},{"id":"C","text":"Respiratory disease"},{"id":"D","text":"Urogenital disease"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Cardiovascular disease. Burden of disease is the cumulative health loss and wider consequences produced by disease or injury in a population, compared with an ideal of full health.","sourceLocations":[{"assessment":"Midterm","batch":"439","questionNumber":33,"sourceType":"Gift"}],"references":[{"title":"WHO — Global Health Estimates","url":"https://www.who.int/data/global-health-estimates"}],"lectureOrder":7,"referenceOrder":61033},{"id":"community-mid-determinants-of-health-6c9f968b","subjectId":"community","lecture":"Determinants of Health","assessment":"Midterm","sourceBatch":"439","sourceLabel":"Community Medicine Gift","stem":"Health and disease lie along a continuum, and there is no single cut-off point , So What is the lowest point on the health-disease spectrum?","options":[{"id":"A","text":"Severe sickness"},{"id":"B","text":"Disability"},{"id":"C","text":"Death"},{"id":"D","text":"Positive health"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Death. Health is a continuum rather than a binary state because people can move through degrees of wellbeing, illness, disability and recovery; death is its lowest endpoint.","sourceLocations":[{"assessment":"Midterm","batch":"439","questionNumber":35,"sourceType":"Gift"}],"references":[{"title":"WHO — Social determinants of health","url":"https://www.who.int/health-topics/social-determinants-of-health"}],"lectureOrder":4,"referenceOrder":61035},{"id":"community-mid-natural-history-of-disease-and-conce-10a4d1cf","subjectId":"community","lecture":"Natural History of Disease and Concepts of Prevention and Control","assessment":"Midterm","sourceBatch":"439","sourceLabel":"Community Medicine Gift","stem":"Patient has diabetes for 20 years and is on insulin for 15 years came to your clinic. Type of prevention?","options":[{"id":"A","text":"Primary"},{"id":"B","text":"Secondary"},{"id":"C","text":"Primordial"},{"id":"D","text":"Tertiary"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Tertiary. Because disease is already established, care aimed at limiting complications and disability is tertiary prevention.","sourceLocations":[{"assessment":"Midterm","batch":"439","questionNumber":36,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/index.html"}],"lectureOrder":1,"referenceOrder":61036},{"id":"community-mid-global-demography-concepts-and-popul-511adee6","subjectId":"community","lecture":"Global Demography Concepts and Population Pyramid","assessment":"Midterm","sourceBatch":"439","sourceLabel":"Community Medicine Gift","stem":"Population ageing is one of the four global demographic megatrends. What is the cause of population ageing?","options":[{"id":"A","text":"Declining fertility and increased longevity"},{"id":"B","text":"Increased fertility"},{"id":"C","text":"Urbanization"},{"id":"D","text":"International migration"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Declining fertility and increased longevity. Population ageing results mainly from fewer births and longer survival, which increases the share of older people.","sourceLocations":[{"assessment":"Midterm","batch":"439","questionNumber":37,"sourceType":"Gift"}],"references":[{"title":"United Nations World Population Prospects","url":"https://www.un.org/development/desa/pd/content/world-population-prospects-2024"}],"lectureOrder":2,"referenceOrder":61037},{"id":"community-mid-prevention-and-control-of-infectious-d36c588a","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"439","sourceLabel":"Community Medicine Gift","stem":"A 40 years old patient tested positive for COVID-19 was admitted to ICU and needs endotracheal intubation. Which of the following is the appropriate precaution?","options":[{"id":"A","text":"Airborne precaution"},{"id":"B","text":"Droplet precaution"},{"id":"C","text":"Bloodborne precaution"},{"id":"D","text":"Contact precaution"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A (Intubation is an aerosol-generating procedure)","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Airborne precaution. Airborne transmission involves small droplet nuclei or particles that remain suspended and can travel beyond close-range droplet spread.","sourceLocations":[{"assessment":"Midterm","batch":"439","questionNumber":38,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":61038},{"id":"community-mid-adolescent-and-child-health-b24442fc","subjectId":"community","lecture":"Adolescent and Child Health","assessment":"Midterm","sourceBatch":"439","sourceLabel":"Community Medicine Gift","stem":"You are preparing an annual report for the CEO of the hospital on causes of child deaths in the hospital, and are required to classify the deaths Of a baby from “birth to 28 days of life” What category will these deaths be classified under?","options":[{"id":"A","text":"Perinatal death"},{"id":"B","text":"Early neonatal death"},{"id":"C","text":"Late neonatal death"},{"id":"D","text":"Neonatal death"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Neonatal death. Neonatal mortality covers deaths during the first 28 completed days of life and is expressed per 1,000 live births.","sourceLocations":[{"assessment":"Midterm","batch":"439","questionNumber":40,"sourceType":"Gift"}],"references":[{"title":"WHO — Adolescent health","url":"https://www.who.int/health-topics/adolescent-health"}],"lectureOrder":10,"referenceOrder":61040},{"id":"community-mid-adolescent-and-child-health-86895106","subjectId":"community","lecture":"Adolescent and Child Health","assessment":"Midterm","sourceBatch":"439","sourceLabel":"Community Medicine Gift","stem":"mother came with her 6 months old baby and she's worried that he is not developing well. He was able to sit on the examination table. History and physical exam were unremarkable. What will you say?","options":[{"id":"A","text":"The baby is developing well because he is able to sit"},{"id":"B","text":"The baby is developing well because he can recognize you"},{"id":"C","text":"The baby is not developing well because he is only able to sit"},{"id":"D","text":"The baby is not developing well because he is not able to walk"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is The baby is developing well because he is able to sit. Developmental milestones are assessed by age and by domains such as gross motor, fine motor, language and social skills; sitting with support at six months is generally age-appropriate.","sourceLocations":[{"assessment":"Midterm","batch":"439","questionNumber":41,"sourceType":"Gift"}],"references":[{"title":"WHO — Adolescent health","url":"https://www.who.int/health-topics/adolescent-health"}],"lectureOrder":10,"referenceOrder":61041},{"id":"community-mid-adolescent-and-child-health-87107140","subjectId":"community","lecture":"Adolescent and Child Health","assessment":"Midterm","sourceBatch":"439","sourceLabel":"Community Medicine Gift","stem":"There is a mental health program. What age should the program focus on?","options":[{"id":"A","text":"15-24"},{"id":"B","text":"25-34"},{"id":"C","text":"35-44"},{"id":"D","text":"45-54"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is 15-24. WHO population terminology commonly uses youth for ages 15–24; adolescence covers ages 10–19.","sourceLocations":[{"assessment":"Midterm","batch":"439","questionNumber":42,"sourceType":"Gift"}],"references":[{"title":"WHO — Adolescent health","url":"https://www.who.int/health-topics/adolescent-health"}],"lectureOrder":10,"referenceOrder":61042},{"id":"community-mid-social-and-behavioral-health-a09fb40e","subjectId":"community","lecture":"Social and Behavioral Health","assessment":"Midterm","sourceBatch":"439","sourceLabel":"Community Medicine Gift","stem":"Which of the following is best describing self-efficacy in behavioural changes?","options":[{"id":"A","text":"Acceptance of or confidentiality in an alleged fact or body of facts or right without positive knowledge or proof, perceived truth"},{"id":"B","text":"Ascribing meanings"},{"id":"C","text":"The internal condition of experiencing competence to perform desired tasks. Which will influence the eventual outcome"},{"id":"D","text":"An intellectual acquaintance with facts, truth, or principle gained by sight, experience, or report"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is The internal condition of experiencing competence to perform desired tasks. Which will influence the eventual outcome. Self-efficacy is confidence in one's ability to perform the target behavior successfully; it strongly influences initiation and persistence.","sourceLocations":[{"assessment":"Midterm","batch":"439","questionNumber":43,"sourceType":"Gift"}],"references":[{"title":"WHO — Health promotion","url":"https://www.who.int/health-topics/health-promotion"}],"lectureOrder":12,"referenceOrder":61043},{"id":"community-mid-prevention-and-control-of-infectious-bc0a8c99","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"439","sourceLabel":"Community Medicine Gift","stem":"You are in charge of COVID-19 ward in which 20 patients were admitted. Which of the following would increase the risk of COVID-19?","options":[{"id":"A","text":"Caucasian ancestors"},{"id":"B","text":"Cardiovascular disease"},{"id":"C","text":"Male gender"},{"id":"D","text":"Younger groups"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Cardiovascular disease. COVID-19 transmission risk rises with close, prolonged indoor exposure, poor ventilation and inadequate respiratory protection.","sourceLocations":[{"assessment":"Midterm","batch":"439","questionNumber":44,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":61044},{"id":"community-mid-maternal-health-e438073e","subjectId":"community","lecture":"Maternal Health","assessment":"Midterm","sourceBatch":"439","sourceLabel":"Community Medicine Gift","stem":"A pregnant woman with HIV/AIDS went to a healthcare professional expressing her worries of transmitting HIV to her baby and asked about the highest risk of the baby getting HIV. Which of the following better reflect the healthcare professional’s response?","options":[{"id":"A","text":"During birthing process"},{"id":"B","text":"Through breastfeeding"},{"id":"C","text":"In utero"},{"id":"D","text":"Equal risk at all stages"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is During birthing process. Vertical transmission can occur during pregnancy, labour and delivery, or breastfeeding; effective maternal treatment and perinatal care markedly reduce risk.","sourceLocations":[{"assessment":"Midterm","batch":"439","questionNumber":45,"sourceType":"Gift"}],"references":[{"title":"WHO — Maternal health","url":"https://www.who.int/health-topics/maternal-health"}],"lectureOrder":11,"referenceOrder":61045},{"id":"community-mid-prevention-and-control-of-infectious-60bf5662","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"439","sourceLabel":"Community Medicine Gift","stem":"A man is HIV positive and his wife is HIV negative, of which of the following will you advise them as to protect the wife from HIV?","options":[{"id":"A","text":"The wife should take the same ART medication her husband is taking"},{"id":"B","text":"Wear condom during sexual activity"},{"id":"C","text":"Take HIV Vaccine"},{"id":"D","text":"The wife should take contraceptive pills"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Wear condom during sexual activity. A condom is a short-acting reversible barrier method; implants and IUDs are long-acting reversible methods, while sterilization is permanent.","sourceLocations":[{"assessment":"Midterm","batch":"439","questionNumber":46,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":61046},{"id":"community-mid-prevention-and-control-of-infectious-8bb849a5","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"439","sourceLabel":"Community Medicine Gift","stem":"A medical student spends time inside with devices, he develops issues for what reason?","options":[{"id":"A","text":"self-isolation"},{"id":"B","text":"perfectionism"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is self-isolation. Isolation separates infectious cases during the period of communicability to reduce exposure of susceptible contacts.","sourceLocations":[{"assessment":"Midterm","batch":"439","questionNumber":48,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":61048},{"id":"community-mid-natural-history-of-disease-and-conce-e5dc1445","subjectId":"community","lecture":"Natural History of Disease and Concepts of Prevention and Control","assessment":"Midterm","sourceBatch":"439","sourceLabel":"Community Medicine Gift","stem":"Understanding health behaviour underlying the ailments and means of behaviour changes to prevent further deterioration of health or restoration of health represents which of the following?","options":[{"id":"A","text":"Primordial prevention"},{"id":"B","text":"Primary prevention"},{"id":"C","text":"Secondary prevention"},{"id":"D","text":"Tertiary prevention"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Secondary prevention. Secondary prevention detects disease early in apparently healthy people so timely treatment can reduce progression or complications.","sourceLocations":[{"assessment":"Midterm","batch":"439","questionNumber":49,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/index.html"}],"lectureOrder":1,"referenceOrder":61049},{"id":"community-mid-mental-health-9e2eaeb1","subjectId":"community","lecture":"Mental Health","assessment":"Midterm","sourceBatch":"439","sourceLabel":"Community Medicine Gift","stem":"A person with schizophrenia is ashamed of his son to know he has it, which of the following better describes him?","options":[{"id":"A","text":"Self-Stigma"},{"id":"B","text":"Social Stigma"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Self-Stigma. Concealing a mental disorder because of shame reflects internalized stigma: the person has absorbed negative social beliefs and applies them to himself.","sourceLocations":[{"assessment":"Midterm","batch":"439","questionNumber":50,"sourceType":"Gift"}],"references":[{"title":"WHO — Mental health","url":"https://www.who.int/news-room/fact-sheets/detail/mental-health-strengthening-our-response"}],"lectureOrder":9,"referenceOrder":61050},{"id":"community-mid-surveillance-and-screening-41118197","subjectId":"community","lecture":"Surveillance and Screening","assessment":"Midterm","sourceBatch":"439","sourceLabel":"Community Medicine Gift","stem":"Healthy female with no previous medical condition, her mother recently died of breast cancer, you suggest she does a mammogram screening because she is in the high risk group. In her case what type of prevention is that?","options":[{"id":"A","text":"Primary prevention"},{"id":"B","text":"Secondary prevention"},{"id":"C","text":"Quaternary prevention"},{"id":"D","text":"Tertiary prevention"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Secondary prevention. A first-degree family history changes breast-cancer risk assessment and may justify earlier individualized imaging; the recorded Gift answer is shown separately from current clinical guidance.","sourceLocations":[{"assessment":"Midterm","batch":"439","questionNumber":51,"sourceType":"Gift"}],"references":[{"title":"WHO — Screening programmes: a short guide","url":"https://www.who.int/publications/i/item/9789289054782"}],"lectureOrder":5,"referenceOrder":61051},{"id":"community-mid-determinants-of-health-be73a4ca","subjectId":"community","lecture":"Determinants of Health","assessment":"Midterm","sourceBatch":"439","sourceLabel":"Community Medicine Gift","stem":"Is a state of complete physical, mental and social well-being and not merely an absence of disease or infirmity” this defines:","options":[{"id":"A","text":"Quality of life"},{"id":"B","text":"Well-being"},{"id":"C","text":"Global Health"},{"id":"D","text":"Health"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Health. This is the WHO constitutional definition of health: wellbeing has physical, mental and social dimensions and is more than the absence of diagnosed disease.","sourceLocations":[{"assessment":"Midterm","batch":"439","questionNumber":52,"sourceType":"Gift"}],"references":[{"title":"WHO — Social determinants of health","url":"https://www.who.int/health-topics/social-determinants-of-health"}],"lectureOrder":4,"referenceOrder":61052},{"id":"community-mid-introduction-to-health-policy-4549e816","subjectId":"community","lecture":"Introduction to Health Policy","assessment":"Midterm","sourceBatch":"439","sourceLabel":"Community Medicine Gift","stem":"Decisions, plans and actions that are undertaken to achieve specific health care goals this defines:","options":[{"id":"A","text":"health policy"},{"id":"B","text":"global health"},{"id":"C","text":"global health governance"},{"id":"D","text":"IHR"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is health policy. Health policy comprises decisions, plans and actions intended to achieve stated health goals and shape services, financing or population health.","sourceLocations":[{"assessment":"Midterm","batch":"439","questionNumber":53,"sourceType":"Gift"}],"references":[{"title":"WHO — Health policy and systems research","url":"https://www.who.int/teams/alliance-for-health-policy-systems-research"}],"lectureOrder":15,"referenceOrder":61053},{"id":"community-mid-adolescent-and-child-health-fd2ec49f","subjectId":"community","lecture":"Adolescent and Child Health","assessment":"Midterm","sourceBatch":"439","sourceLabel":"Community Medicine Gift","stem":"Which of the following is primary school prevention?","options":[{"id":"A","text":"Pre-school medical check up"},{"id":"B","text":"School immunization"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is School immunization. School immunization is specific protection delivered before disease occurs, so it is primary prevention.","sourceLocations":[{"assessment":"Midterm","batch":"439","questionNumber":54,"sourceType":"Gift"}],"references":[{"title":"WHO — Adolescent health","url":"https://www.who.int/health-topics/adolescent-health"}],"lectureOrder":10,"referenceOrder":61054},{"id":"community-mid-prevention-and-control-of-infectious-060fe40a","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"439","sourceLabel":"Community Medicine Gift","stem":"A mother who got chicken pox when she was a child has a 2 week old baby with a 5 year old sibling. Her 5 years old child got chicken pox and she is worried that her would infect her 2 weeks baby. You reassure her that she doesn’t need to worry, what would be your explanation?","options":[{"id":"A","text":"Natural passive immunity"},{"id":"B","text":"Artificial passive immunity"},{"id":"C","text":"Natural active immunity"},{"id":"D","text":"Artificial active immunity"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Natural passive immunity. Passive surveillance relies on routine reports sent by healthcare providers or laboratories; it is inexpensive but vulnerable to under-reporting.","sourceLocations":[{"assessment":"Midterm","batch":"439","questionNumber":55,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":61055},{"id":"community-mid-global-demography-concepts-and-popul-bb7e8386","subjectId":"community","lecture":"Global Demography Concepts and Population Pyramid","assessment":"Midterm","sourceBatch":"439","sourceLabel":"Community Medicine Gift","stem":"Which of the following describes the number of births in a year in a specific locality over the mid-year population size in that same year and locality?","options":[{"id":"A","text":"General fertility rate"},{"id":"B","text":"Crude birth rate"},{"id":"C","text":"Total fertility rate"},{"id":"D","text":"General marital fertility rate"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Crude birth rate. Crude birth rate is live births during the year divided by the mid-year population, conventionally expressed per 1,000 population.","sourceLocations":[{"assessment":"Midterm","batch":"439","questionNumber":56,"sourceType":"Gift"}],"references":[{"title":"United Nations World Population Prospects","url":"https://www.un.org/development/desa/pd/content/world-population-prospects-2024"}],"lectureOrder":2,"referenceOrder":61056},{"id":"community-mid-introduction-to-health-policy-3a955c51","subjectId":"community","lecture":"Introduction to Health Policy","assessment":"Midterm","sourceBatch":"439","sourceLabel":"Community Medicine Gift","stem":"Why does MOH need to change its model?","options":[{"id":"B","text":"less fertility and increase life expectancy"}],"images":[],"incompleteSource":true,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is less fertility and increase life expectancy. Life expectancy summarizes the average years a person is expected to live under current mortality patterns, making it useful for broad population comparisons.","sourceLocations":[{"assessment":"Midterm","batch":"439","questionNumber":57,"sourceType":"Gift"}],"references":[{"title":"WHO — Health policy and systems research","url":"https://www.who.int/teams/alliance-for-health-policy-systems-research"}],"lectureOrder":15,"referenceOrder":61057},{"id":"community-mid-introduction-to-health-policy-9e4a78f1","subjectId":"community","lecture":"Introduction to Health Policy","assessment":"Midterm","sourceBatch":"439","sourceLabel":"Community Medicine Gift","stem":"A doctor working in a primary health clinic noticed that a large number of the patients are referring to other doctors in different health institutions and they aren’t satisfied with the level of care provided at your clinic. What would be the solution to prevent this from recurring and increase the level of satisfaction?","options":[{"id":"A","text":"Increase the time of each patient in a clinic"},{"id":"B","text":"Engage with community and assess their needs"},{"id":"C","text":"Make referrals pathway from the clinic easier"},{"id":"D","text":"increase the number of physicians and staff working in the clinic"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Engage with community and assess their needs. A rule governing referrals or resource use inside a service is an organizational or micro-level policy rather than a national macro policy.","sourceLocations":[{"assessment":"Midterm","batch":"439","questionNumber":58,"sourceType":"Gift"}],"references":[{"title":"WHO — Health policy and systems research","url":"https://www.who.int/teams/alliance-for-health-policy-systems-research"}],"lectureOrder":15,"referenceOrder":61058},{"id":"community-mid-surveillance-and-screening-d65dbe87","subjectId":"community","lecture":"Surveillance and Screening","assessment":"Midterm","sourceBatch":"439","sourceLabel":"Community Medicine Gift","stem":"A new screening test for coronavirus infection (MERSCoV) is tested against PCR analysis. The new screening test was able to detect 22 cases among 45 subjects who were confirmed positive by PCR analysis. Among 64 who were identified as free of MERSCoV by PCR, the new test reported 4 cases affected with MERSCoV. Which one is the sensitivity of the new test? Table: New test | PCR | PCR / | +ve | -ve / Positive | 22 | 4 / Negative | | / Total | 45 | 64","options":[{"id":"A","text":"49%"},{"id":"B","text":"51%"},{"id":"C","text":"85%"},{"id":"D","text":"72%"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is 49%. Sensitivity is the proportion of people with the condition who test positive: TP/(TP+FN). A highly sensitive test therefore minimizes false negatives.","sourceLocations":[{"assessment":"Midterm","batch":"439","questionNumber":59,"sourceType":"Gift"}],"references":[{"title":"WHO — Screening programmes: a short guide","url":"https://www.who.int/publications/i/item/9789289054782"}],"lectureOrder":5,"referenceOrder":61059},{"id":"community-mid-adolescent-and-child-health-1a640f5a","subjectId":"community","lecture":"Adolescent and Child Health","assessment":"Midterm","sourceBatch":"439","sourceLabel":"Community Medicine Gift","stem":"scenario…. Table: Age group | Deaths | population size / 0-4 | 5,529 | 2,844,501 / 5-14 | 2,644 | 5,545,462 / 15-24 | 5,086 | 2,359,981 / 25-34 | 3,757 | 6,580,086 / 35-44 | 5,017 | 7,023,738 / 45-54 | 8,734 | 4,175,198 / 55-64 | 12,595 | 1,962,358 / +65 | 36,884 | 1,098,951 based on the measures above, what is the age specific mortality rate for 15-44 years?","options":[{"id":"A","text":"0.63 Deaths per 1000"},{"id":"B","text":"0.87 Deaths per 1000"},{"id":"C","text":"1.12 Deaths per 1000"},{"id":"D","text":"0.24 Deaths per 1000"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is 0.87 Deaths per 1000. WHO population terminology commonly uses youth for ages 15–24; adolescence covers ages 10–19.","sourceLocations":[{"assessment":"Midterm","batch":"439","questionNumber":60,"sourceType":"Gift"}],"references":[{"title":"WHO — Adolescent health","url":"https://www.who.int/health-topics/adolescent-health"}],"lectureOrder":10,"referenceOrder":61060},{"id":"community-mid-surveillance-and-screening-537e8e1d","subjectId":"community","lecture":"Surveillance and Screening","assessment":"Midterm","sourceBatch":"439","sourceLabel":"Community Medicine Gift","stem":"The following diagram presents result of a new diabetes screening test in comparison to GGT: calculate the specificity of this test Table: | Diseased | Not diseased / Positive | 282 | 20 / Negative | 18 | 230","options":[{"id":"A","text":"230 / 230 + 20 = 92%"},{"id":"B","text":"20 / 20 + 230 = 8%"},{"id":"C","text":"282 / 282 + 20 = 93%"},{"id":"D","text":"18 / 18 + 230 = 7%"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is 230 / 230 + 20 = 92%. Specificity is the proportion of people without the condition who test negative: TN/(TN+FP). A highly specific test therefore minimizes false positives.","sourceLocations":[{"assessment":"Midterm","batch":"439","questionNumber":61,"sourceType":"Gift"}],"references":[{"title":"WHO — Screening programmes: a short guide","url":"https://www.who.int/publications/i/item/9789289054782"}],"lectureOrder":5,"referenceOrder":61061},{"id":"community-mid-maternal-health-4234964b","subjectId":"community","lecture":"Maternal Health","assessment":"Midterm","sourceBatch":"438","sourceLabel":"Community Medicine Gift","stem":"You are observing a mother starting her first breastfeeding to her first baby after delivery, Which of the following indicates that she is appropriately positioning her baby?","options":[{"id":"A","text":"Baby is close to mother’s body"},{"id":"B","text":"Baby’s nose is at the level of the nipple"},{"id":"C","text":"Mother is supporting whole baby’s body"},{"id":"D","text":"Neck is bent backward"}],"images":[],"incompleteSource":false,"sourceAnswer":["A","B","C"],"sourceAnswerNote":"A,B,C. This is exactly how the question came in the exam.","aiAnswer":["A","B","C"],"aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Baby is close to mother’s body or Baby’s nose is at the level of the nipple or Mother is supporting whole baby’s body. Good positioning keeps the infant close, aligned and fully supported, with the nose opposite the nipple before attachment; several listed features may therefore be correct.","sourceLocations":[{"assessment":"Midterm","batch":"438","questionNumber":1,"sourceType":"Gift"}],"references":[{"title":"WHO — Maternal health","url":"https://www.who.int/health-topics/maternal-health"}],"lectureOrder":11,"referenceOrder":62001},{"id":"community-mid-adolescent-and-child-health-8a71134c","subjectId":"community","lecture":"Adolescent and Child Health","assessment":"Midterm","sourceBatch":"438","sourceLabel":"Community Medicine Gift","stem":"A 14 year old child who is up to date with his vaccine schedule stepped on a rusted nail a year ago and was given a vaccination, there is no written record of what was given, although the parents believe that it was a tetanus vaccine. The child has now presented for a school leaving booster. Which of the following is the most appropriate approach to follow?","options":[{"id":"A","text":"No need for booster dose"},{"id":"B","text":"To be tested for polio antibodies before any further doses of polio vaccine"},{"id":"C","text":"To be tested for polio antibodies before any further doses of tetanus vaccine"},{"id":"D","text":"The vaccination given at the time of injury should be disregarded and Td-IPV given now"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A (Not sure)","aiAnswer":"D","aiSuggestion":"When prior vaccination cannot be documented, the uncertain dose should not replace the scheduled age-appropriate booster; Td-IPV should be given.","verification":"conflict","explanation":"The recorded answer is No need for booster dose. Tetanus wound prophylaxis depends on the wound and documented vaccine history; a complete recent series usually does not require another immediate dose.","sourceLocations":[{"assessment":"Midterm","batch":"438","questionNumber":2,"sourceType":"Gift"}],"references":[{"title":"WHO — Adolescent health","url":"https://www.who.int/health-topics/adolescent-health"}],"lectureOrder":10,"referenceOrder":62002},{"id":"community-mid-prevention-and-control-of-infectious-e84d27ee","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"438","sourceLabel":"Community Medicine Gift","stem":"What epidemiologic pattern is used to describe \"the aggregation of cases in a given area over a particular period of time regardless of whether the number of cases is more than expected\"?","options":[{"id":"A","text":"Outbreak"},{"id":"B","text":"Endemic"},{"id":"C","text":"Cluster"},{"id":"D","text":"Epidemic"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Cluster. A cluster is an aggregation of cases in a particular place and period that appears greater than expected, even when the precise expected number is not yet known.","sourceLocations":[{"assessment":"Midterm","batch":"438","questionNumber":3,"sourceType":"Gift"},{"assessment":"Midterm","batch":"434","questionNumber":3,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":62003},{"id":"community-mid-maternal-health-47be01b6","subjectId":"community","lecture":"Maternal Health","assessment":"Midterm","sourceBatch":"438","sourceLabel":"Community Medicine Gift","stem":"A 22 years old pregnant female currently in her 2nd trimester and doesn’t recall to have received any tetanus toxoid vaccination visits your clinic. What will be your advice for her?","options":[{"id":"A","text":"1 Dose"},{"id":"B","text":"2 Doses"},{"id":"C","text":"3 Doses"},{"id":"D","text":"5 Doses"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D (Not sure)","aiAnswer":"B","aiSuggestion":"With unknown prior tetanus vaccination, at least two tetanus-toxoid-containing doses are given during pregnancy, four weeks apart, with the second at least two weeks before birth.","verification":"conflict","explanation":"A pregnant woman with unknown or unreliable tetanus vaccination history should receive at least two tetanus-toxoid-containing doses four weeks apart, with dose two at least two weeks before birth. This supports B rather than the tentative Gift answer D.","sourceLocations":[{"assessment":"Midterm","batch":"438","questionNumber":4,"sourceType":"Gift"}],"references":[{"title":"WHO — Protecting all against tetanus","url":"https://www.who.int/docs/default-source/tetanus/9789241515610-eng.pdf"}],"lectureOrder":11,"referenceOrder":62004},{"id":"community-mid-disparities-in-health-b4487c13","subjectId":"community","lecture":"Disparities in Health","assessment":"Midterm","sourceBatch":"438","sourceLabel":"Community Medicine Gift","stem":"Total population: 10007334 | Mid-year population: 9982709 | Total deaths: 90000 Based on these measures, what is the estimated total crude death rate?","options":[{"id":"A","text":"9.02 deaths per 1000"},{"id":"B","text":"8.99 deaths per 1000"},{"id":"C","text":"4.09 deaths per 1000"},{"id":"D","text":"1.68 deaths per 1000"}],"images":[],"incompleteSource":false,"sourceAnswer":["A","B"],"sourceAnswerNote":"Both Answers (A&B) are correct. The denominator of Crude death rate in the slides is Mid-year population and in PRB's population handbook provided by the doctor the denominator is Total population","aiAnswer":"A","aiSuggestion":"Using the standard mid-year population denominator gives 9.02 deaths per 1,000 (A). The Gift note also accepts B after using total population instead.","verification":"conflict","explanation":"The standard crude death rate uses the mid-year population: 90,000/9,982,709 × 1,000 = 9.02, so the AI answer is A. The Gift note also accepts B only when the total population is substituted as denominator.","sourceLocations":[{"assessment":"Midterm","batch":"438","questionNumber":6,"sourceType":"Gift"}],"references":[{"title":"WHO — Health inequities and their causes","url":"https://www.who.int/news-room/facts-in-pictures/detail/health-inequities-and-their-causes"}],"lectureOrder":8,"referenceOrder":62006},{"id":"community-mid-prevention-and-control-of-infectious-9cc48107","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"438","sourceLabel":"Community Medicine Gift","stem":"What other type of viral hepatitis is commonly associated with Hepatitis D infection? (Seminar)","options":[{"id":"A","text":"Hepatitis E"},{"id":"B","text":"Hepatitis A"},{"id":"C","text":"Hepatitis G"},{"id":"D","text":"Hepatitis B"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Hepatitis B. Hepatitis D requires hepatitis B surface antigen for replication, so it occurs only as coinfection or superinfection with hepatitis B.","sourceLocations":[{"assessment":"Midterm","batch":"438","questionNumber":8,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":62008},{"id":"community-mid-maternal-health-ec319a6f","subjectId":"community","lecture":"Maternal Health","assessment":"Midterm","sourceBatch":"438","sourceLabel":"Community Medicine Gift","stem":"You are discussing feeding options with parents of healthy full term infants in your clinic Which one of the following do you usually recommend for the first month of life?","options":[{"id":"A","text":"Exclusive breastfeeding"},{"id":"B","text":"Support whatever mother’s choice"},{"id":"C","text":"Exclusive formula"},{"id":"D","text":"Breastfeeding with supplementation"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Exclusive breastfeeding. Exclusive breastfeeding means the infant receives breast milk only, apart from permitted medicines or oral rehydration solution, for the recommended first six months.","sourceLocations":[{"assessment":"Midterm","batch":"438","questionNumber":9,"sourceType":"Gift"}],"references":[{"title":"WHO — Maternal health","url":"https://www.who.int/health-topics/maternal-health"}],"lectureOrder":11,"referenceOrder":62009},{"id":"community-mid-prevention-and-control-of-infectious-52a11ad1","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"438","sourceLabel":"Community Medicine Gift","stem":"Between 2000 and 2010 the average number of cases of Measles detected in the Netherlands ranged between 1.500 000 to 2.000.000 cases. The number of cases in 2006 was 1.800.000 Which of the following states best describes measles in Netherland during 2006?","options":[{"id":"A","text":"Outbreak"},{"id":"B","text":"Endemic"},{"id":"C","text":"Epizootic"},{"id":"D","text":"Epidemic"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Endemic. Because the observed number remains within the usual expected range for that population and period, the disease is endemic rather than an epidemic or outbreak.","sourceLocations":[{"assessment":"Midterm","batch":"438","questionNumber":10,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":62010},{"id":"community-mid-adolescent-and-child-health-f76c2ad0","subjectId":"community","lecture":"Adolescent and Child Health","assessment":"Midterm","sourceBatch":"438","sourceLabel":"Community Medicine Gift","stem":"In the updated saudi national immunization schedule, when is the BCG vaccine given?","options":[{"id":"A","text":"At birth"},{"id":"B","text":"2 months"},{"id":"C","text":"4 months"},{"id":"D","text":"6 months"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is 6 months. BCG timing is taken from the Saudi national immunization schedule used in the course; schedules can change, so the current MOH table should be checked for clinical use.","sourceLocations":[{"assessment":"Midterm","batch":"438","questionNumber":11,"sourceType":"Gift"}],"references":[{"title":"WHO — Adolescent health","url":"https://www.who.int/health-topics/adolescent-health"}],"lectureOrder":10,"referenceOrder":62011},{"id":"community-mid-prevention-and-control-of-infectious-a38e91b4","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"438","sourceLabel":"Community Medicine Gift","stem":"What is the main reason for the resurgence of tuberculosis in developing countries?","options":[{"id":"A","text":"The deterioration of living conditions"},{"id":"B","text":"Inadequate activities for detection and treatment of cases"},{"id":"C","text":"The emergence of resistant strains of M. tuberculosis"},{"id":"D","text":"Failure of achieve universal BCG vaccination"}],"images":[],"incompleteSource":true,"sourceAnswer":null,"sourceAnswerNote":null,"aiAnswer":"B","aiSuggestion":"Failure to detect infectious cases promptly and complete effective treatment sustains transmission and is the best general programmatic explanation among the options.","verification":"needs-review","explanation":"No reference answer was recorded. Developmental milestones are assessed by age and by domains such as gross motor, fine motor, language and social skills; sitting with support at six months is generally age-appropriate.","sourceLocations":[{"assessment":"Midterm","batch":"438","questionNumber":13,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":62013},{"id":"community-mid-maternal-health-75daa7f9","subjectId":"community","lecture":"Maternal Health","assessment":"Midterm","sourceBatch":"438","sourceLabel":"Community Medicine Gift","stem":"According to the UNICEF BFHI (breastfeeding hospital initiative) which of the following is outside its domain?","options":[{"id":"A","text":"Rooming in"},{"id":"B","text":"Counselling during antenatal visits"},{"id":"C","text":"Counselling during home visits"},{"id":"D","text":"Ban of advertising pacifiers and supplemental feed"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D (not sure)","aiAnswer":"C","aiSuggestion":"BFHI standards concern maternity and newborn services; routine counselling during home visits is outside the facility initiative. The Gift tentatively records D.","verification":"conflict","explanation":"The Baby-friendly Hospital Initiative applies to maternity and newborn services, including antenatal information, rooming-in and protection from commercial promotion. Routine counselling during home visits is outside the hospital initiative, so the AI answer is C rather than the tentative Gift answer D.","sourceLocations":[{"assessment":"Midterm","batch":"438","questionNumber":14,"sourceType":"Gift"}],"references":[{"title":"WHO — Maternal health","url":"https://www.who.int/health-topics/maternal-health"}],"lectureOrder":11,"referenceOrder":62014},{"id":"community-mid-prevention-and-control-of-infectious-0326a78b","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"438","sourceLabel":"Community Medicine Gift","stem":"During last week. Mona had measles She was provided with a sock leave from school. For how long should Mona be kept away from the school?","options":[{"id":"A","text":"The period of communicability"},{"id":"B","text":"The longest incubation period"},{"id":"C","text":"The extrinsic incubation period"},{"id":"D","text":"Until the time she fully recovers"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is The period of communicability. The period of communicability is the interval during which an infected person can transmit the agent, which determines the necessary exclusion or isolation period.","sourceLocations":[{"assessment":"Midterm","batch":"438","questionNumber":15,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":62015},{"id":"community-mid-social-and-behavioral-health-f71f18a0","subjectId":"community","lecture":"Social and Behavioral Health","assessment":"Midterm","sourceBatch":"438","sourceLabel":"Community Medicine Gift","stem":"Which of the following is best describing self-efficacy in behavioral changes?","options":[{"id":"A","text":"acceptance of or confidentiality in an alleged fact or body of facts or right without positive knowledge or proof, perceived truth"},{"id":"B","text":"Ascribing meanings"},{"id":"C","text":"The internal condition of experiencing competence to perform desired task, which will influence the eventual outcome"},{"id":"D","text":"An intellectual acquaintance with facts, truth, or principles gained by sight, experience, or report."}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is The internal condition of experiencing competence to perform desired task, which will influence the eventual outcome. Self-efficacy is confidence in one's ability to perform the target behavior successfully; it strongly influences initiation and persistence.","sourceLocations":[{"assessment":"Midterm","batch":"438","questionNumber":16,"sourceType":"Gift"}],"references":[{"title":"WHO — Health promotion","url":"https://www.who.int/health-topics/health-promotion"}],"lectureOrder":12,"referenceOrder":62016},{"id":"community-mid-prevention-and-control-of-infectious-730061f6","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"438","sourceLabel":"Community Medicine Gift","stem":"The tuberculin skin test (TST) results tot a 41-year-old man who has been diagnosed with human immunodeficiency virus (HIV) is negative after 72 hours of injecting 5 tuberculin units intradermally. How should the healthcare provider interpret this test result'?","options":[{"id":"A","text":"The patient has not been exposed to the tuberculous bacteria."},{"id":"B","text":"Poor technique was used when administering the TST"},{"id":"C","text":"The examiner failed to palpate the patient's arm thoroughly"},{"id":"D","text":"The patient is unable to get an immune response to TB"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is The patient is unable to get an immune response to TB. Tuberculin skin-test interpretation depends on induration size and risk group; immunosuppressed contacts use a lower positive threshold and require clinical assessment.","sourceLocations":[{"assessment":"Midterm","batch":"438","questionNumber":17,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":62017},{"id":"community-mid-adolescent-and-child-health-1fc4f25b","subjectId":"community","lecture":"Adolescent and Child Health","assessment":"Midterm","sourceBatch":"438","sourceLabel":"Community Medicine Gift","stem":"According to WHO data 2014, what is the number one cause of illness and disability among adolescents (globally)?","options":[{"id":"A","text":"Anemia"},{"id":"B","text":"Depression"},{"id":"C","text":"Injury"},{"id":"D","text":"HIV/AIDS"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Depression. Anxiety and depressive disorders are among the leading mental-health causes of illness and disability during adolescence.","sourceLocations":[{"assessment":"Midterm","batch":"438","questionNumber":18,"sourceType":"Gift"}],"references":[{"title":"WHO — Adolescent health","url":"https://www.who.int/health-topics/adolescent-health"}],"lectureOrder":10,"referenceOrder":62018},{"id":"community-mid-disparities-in-health-eef1c4b9","subjectId":"community","lecture":"Disparities in Health","assessment":"Midterm","sourceBatch":"438","sourceLabel":"Community Medicine Gift","stem":"In 2003. 128,294 deaths occurred among 24-44 years old. 16,283 deaths were due to road traffic guiles and 7,367 were due to cancer. What is the proportionate mortality for cancer among 24-44 years?","options":[{"id":"A","text":"10%"},{"id":"B","text":"20%"},{"id":"C","text":"5.7%"},{"id":"D","text":"12.6%"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is 5.7%. Proportionate mortality is deaths from a specified cause divided by all deaths in the same population and period, expressed as a percentage.","sourceLocations":[{"assessment":"Midterm","batch":"438","questionNumber":19,"sourceType":"Gift"}],"references":[{"title":"WHO — Health inequities and their causes","url":"https://www.who.int/news-room/facts-in-pictures/detail/health-inequities-and-their-causes"}],"lectureOrder":8,"referenceOrder":62019},{"id":"community-mid-surveillance-and-screening-96673188","subjectId":"community","lecture":"Surveillance and Screening","assessment":"Midterm","sourceBatch":"438","sourceLabel":"Community Medicine Gift","stem":"This is A cross tabulation of the results of a screening test and confirmatory test for prostate biopsy. What is the predictive negative value? Table: Clinical diagnosis | Biopsy results | Biopsy results | Total / Positive | 100 | 150 | 250 / Negative | 75 | 175 | 250 / Total | 175 | 325 | 500","options":[{"id":"A","text":"175/250"},{"id":"B","text":"150/175"},{"id":"C","text":"175/325"},{"id":"D","text":"100/175"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is 175/250. Secondary prevention detects disease early in apparently healthy people so timely treatment can reduce progression or complications.","sourceLocations":[{"assessment":"Midterm","batch":"438","questionNumber":20,"sourceType":"Gift"}],"references":[{"title":"WHO — Screening programmes: a short guide","url":"https://www.who.int/publications/i/item/9789289054782"}],"lectureOrder":5,"referenceOrder":62020},{"id":"community-mid-mental-health-3b0746ba","subjectId":"community","lecture":"Mental Health","assessment":"Midterm","sourceBatch":"438","sourceLabel":"Community Medicine Gift","stem":"you are designing a mental health prevention and promotion program based on the prevalence of mental health conditions in KSA across lifetime. Which of the following conditions will be a priority for you to choose'? (Seminars)","options":[{"id":"A","text":"Major depressive disorder"},{"id":"B","text":"Post traumatic disorder"},{"id":"C","text":"Obsessive compulsive disorder"},{"id":"D","text":"Separation anxiety disorder"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D (Not sure)","aiAnswer":"D","aiSuggestion":"The Saudi National Mental Health Survey reported separation anxiety disorder as the most common individual lifetime disorder among these options.","verification":"supported","explanation":"The Saudi National Mental Health Survey found separation anxiety disorder to be the most common individual lifetime disorder among the listed choices, supporting D.","sourceLocations":[{"assessment":"Midterm","batch":"438","questionNumber":21,"sourceType":"Gift"}],"references":[{"title":"Saudi National Mental Health Survey — Lifetime prevalence","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7507419/"}],"lectureOrder":9,"referenceOrder":62021},{"id":"community-mid-maternal-health-fe049431","subjectId":"community","lecture":"Maternal Health","assessment":"Midterm","sourceBatch":"438","sourceLabel":"Community Medicine Gift","stem":"Which of the following represent a good latching during breastfeeding?","options":[{"id":"A","text":"The lower lip is turned in"},{"id":"B","text":"The baby’s mouth is wide open"},{"id":"C","text":"The chin is away form the breast"},{"id":"D","text":"More areola is visible below the baby’s mouth"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is The baby’s mouth is wide open. A wide-open mouth with the chin touching the breast is a sign of effective attachment and helps milk transfer while reducing nipple pain.","sourceLocations":[{"assessment":"Midterm","batch":"438","questionNumber":22,"sourceType":"Gift"}],"references":[{"title":"WHO — Maternal health","url":"https://www.who.int/health-topics/maternal-health"}],"lectureOrder":11,"referenceOrder":62022},{"id":"community-mid-prevention-and-control-of-infectious-ac609171","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"438","sourceLabel":"Community Medicine Gift","stem":"Ali is a 30 years old man. He is attending the preventive medicine clinic for getting advice regarding his travel to India. He is going to travel to India for 7 months. He leaves in 3 weeks He has never received either hepatitis A or B vaccines. What is the most important educational information to provide him regarding avoiding hepatitis A infection?","options":[{"id":"A","text":"Encourage to take precautions while having sexual contact"},{"id":"B","text":"Avoid sharing needles or use non sterile needles"},{"id":"C","text":"Practice good hand washing, food and water precautions"},{"id":"D","text":"Take immunoglobulins after he arrives in india"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Practice good hand washing, food and water precautions. Hygiene, safe water and sanitation interrupt fecal–oral transmission and are central environmental controls for enteric infections.","sourceLocations":[{"assessment":"Midterm","batch":"438","questionNumber":24,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":62024},{"id":"community-mid-natural-history-of-disease-and-conce-d86c3247","subjectId":"community","lecture":"Natural History of Disease and Concepts of Prevention and Control","assessment":"Midterm","sourceBatch":"438","sourceLabel":"Community Medicine Gift","stem":"Khaled is a 50 year old man. He has had diabetes mellitus for the last 20 years. He is on insulin for the last 15 years. He is on regular follow-up with his primary care physician. His physician gave him his pneumococcal vaccine on this visit. Which type of prevention is being applied in his case?","options":[{"id":"A","text":"Primordial prevention"},{"id":"B","text":"Primary prevention"},{"id":"C","text":"Secondary prevention"},{"id":"D","text":"Tertiary prevention"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Primary prevention. Primary prevention acts before disease begins through health promotion or specific protection. Screening is not primary prevention; it is secondary prevention.","sourceLocations":[{"assessment":"Midterm","batch":"438","questionNumber":25,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/index.html"}],"lectureOrder":1,"referenceOrder":62025},{"id":"community-mid-mental-health-8d752940","subjectId":"community","lecture":"Mental Health","assessment":"Midterm","sourceBatch":"438","sourceLabel":"Community Medicine Gift","stem":"You are treating a patient with schizophrenia and would like to refer him to rehabilitation service to help him live with his mental health problems and stay healthy. WHich service in saudi Arabia would you refer him to?","options":[{"id":"A","text":"Ashanak"},{"id":"B","text":"Seha"},{"id":"C","text":"Qareebon"},{"id":"D","text":"Ajwad"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Ajwad. Tertiary prevention limits disability and restores function after disease is established, including rehabilitation and complication prevention.","sourceLocations":[{"assessment":"Midterm","batch":"438","questionNumber":26,"sourceType":"Gift"}],"references":[{"title":"WHO — Mental health","url":"https://www.who.int/news-room/fact-sheets/detail/mental-health-strengthening-our-response"}],"lectureOrder":9,"referenceOrder":62026},{"id":"community-mid-adolescent-and-child-health-4c891ac3","subjectId":"community","lecture":"Adolescent and Child Health","assessment":"Midterm","sourceBatch":"438","sourceLabel":"Community Medicine Gift","stem":"A child aged 2 years and 3 months has just joined your practice. Vaccination was begun abroad, but the parents are vague about what was given and there is no documentation. Which of the following would you give to the child?","options":[{"id":"A","text":"Two doses of (Pneumococcal conjugate vaccine) PCV13/Hib/IVP"},{"id":"B","text":"Two Doses of Meningococcal B/DTaP"},{"id":"C","text":"Three doses of DTaP/IPV/Hib/Hep B"},{"id":"D","text":"One dose of MMR/Hep B"}],"images":[],"incompleteSource":true,"sourceAnswer":null,"sourceAnswerNote":null,"aiAnswer":null,"aiSuggestion":"The record is incomplete and catch-up vaccination depends on the current national schedule and documented previous doses; no single listed regimen is graded.","verification":"needs-review","explanation":"No reference answer was recorded. Catch-up vaccination uses valid documented previous doses and the child's current age; an uncertain history should be assessed against the current national schedule rather than restarting blindly.","sourceLocations":[{"assessment":"Midterm","batch":"438","questionNumber":27,"sourceType":"Gift"}],"references":[{"title":"WHO — Adolescent health","url":"https://www.who.int/health-topics/adolescent-health"}],"lectureOrder":10,"referenceOrder":62027},{"id":"community-mid-natural-history-of-disease-and-conce-982d58ce","subjectId":"community","lecture":"Natural History of Disease and Concepts of Prevention and Control","assessment":"Midterm","sourceBatch":"438","sourceLabel":"Community Medicine Gift","stem":"Primary preventive measure can be applied at which stage of the natural history of disease?","options":[{"id":"A","text":"Asymptomatic"},{"id":"B","text":"Stage of positive health"},{"id":"C","text":"Classic disease"},{"id":"D","text":"Early obvious disease"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Asymptomatic. Primary prevention acts during susceptibility, before pathologic changes or symptoms occur, through health promotion and specific protection.","sourceLocations":[{"assessment":"Midterm","batch":"438","questionNumber":28,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/index.html"}],"lectureOrder":1,"referenceOrder":62028},{"id":"community-mid-surveillance-and-screening-58d9317c","subjectId":"community","lecture":"Surveillance and Screening","assessment":"Midterm","sourceBatch":"438","sourceLabel":"Community Medicine Gift","stem":"The following diagram points to the natural history of diseases from the stage of susceptibility to recovery/disability/death. At what stage in the natural history of disease, is the public health concept of screening applied?","options":[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"3"},{"id":"D","text":"4"}],"images":["question-media/community/community-438-q29.png"],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is 2. Secondary prevention detects disease early in apparently healthy people so timely treatment can reduce progression or complications.","sourceLocations":[{"assessment":"Midterm","batch":"438","questionNumber":29,"sourceType":"Gift"}],"references":[{"title":"WHO — Screening programmes: a short guide","url":"https://www.who.int/publications/i/item/9789289054782"}],"lectureOrder":5,"referenceOrder":62029},{"id":"community-mid-prevention-and-control-of-infectious-bb879f33","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"438","sourceLabel":"Community Medicine Gift","stem":"A school teacher called you to inquire regarding the Saudi National Immunization Schedule for Hepatitis B vaccine. Which of the following is the correct schedule?","options":[{"id":"A","text":"At birth, 2 months, 4 months, 6 months"},{"id":"B","text":"At birth, 2 months, 4 months, 12 months"},{"id":"C","text":"At birth, 2 months, 4 months, 8 months"},{"id":"D","text":"2 months, 4 months, 6 months"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is At birth, 2 months, 4 months, 6 months. The keyed series follows the Saudi national immunization schedule used in the lecture, beginning at birth and continuing through the infant primary series.","sourceLocations":[{"assessment":"Midterm","batch":"438","questionNumber":30,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":62030},{"id":"community-mid-prevention-and-control-of-infectious-2c1629db","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"438","sourceLabel":"Community Medicine Gift","stem":"Hookworm infection is caused by parasites which are common in Ethiopia. The parasites live in the human intestine and lay eggs which are expelled from the body with the faeces into the soil. The eggs grow into worms in the soil, which penetrate the skin of people walking barefooted. What is the mode of transmission in this scenario?","options":[{"id":"A","text":"Indirectly through skin"},{"id":"B","text":"Indirectly through faces"},{"id":"C","text":"Indirectly through contaminated soil"},{"id":"D","text":"Directly through contaminated soil"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Indirectly through contaminated soil. Soil can act as an environmental reservoir or direct-contact source when infective larvae penetrate exposed skin.","sourceLocations":[{"assessment":"Midterm","batch":"438","questionNumber":33,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":62033},{"id":"community-mid-natural-history-of-disease-and-conce-d03c0155","subjectId":"community","lecture":"Natural History of Disease and Concepts of Prevention and Control","assessment":"Midterm","sourceBatch":"438","sourceLabel":"Community Medicine Gift","stem":"Which one of the following is a secondary level prevention for HIV infection?","options":[{"id":"A","text":"Screening for HIV infection"},{"id":"B","text":"Psychological rehabilitation"},{"id":"C","text":"Isolation of patients from work"},{"id":"D","text":"Treatment of AIDS related complications"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Screening for HIV infection. Secondary prevention detects disease early in apparently healthy people so timely treatment can reduce progression or complications.","sourceLocations":[{"assessment":"Midterm","batch":"438","questionNumber":35,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/index.html"}],"lectureOrder":1,"referenceOrder":62035},{"id":"community-mid-surveillance-and-screening-aea13088","subjectId":"community","lecture":"Surveillance and Screening","assessment":"Midterm","sourceBatch":"438","sourceLabel":"Community Medicine Gift","stem":"A new screening test for MERS CoV infection is tested against PCR analysis. The new screening test was able to detect 22 cases among 45 subjects who were confirmed positive by PCR analysis. Among 64 who were identified as free of MERS CoV by PCR, the new test reported 4 cases affected with MERS CoV. What is the sensitivity of the new test?","options":[{"id":"A","text":"85%"},{"id":"B","text":"49%"},{"id":"C","text":"72%"},{"id":"D","text":"51%"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is 49%. A suspected MERS case with camel exposure requires prompt notification through the designated national surveillance system and appropriate infection-control precautions.","sourceLocations":[{"assessment":"Midterm","batch":"438","questionNumber":36,"sourceType":"Gift"}],"references":[{"title":"WHO — Screening programmes: a short guide","url":"https://www.who.int/publications/i/item/9789289054782"}],"lectureOrder":5,"referenceOrder":62036},{"id":"community-mid-global-demography-concepts-and-popul-0dacfd96","subjectId":"community","lecture":"Global Demography Concepts and Population Pyramid","assessment":"Midterm","sourceBatch":"438","sourceLabel":"Community Medicine Gift","stem":"The following graph displays the population pyramid for Montenegro in 2005. What type of population pyramid is this?","options":[{"id":"A","text":"Stationary"},{"id":"B","text":"Expanding"},{"id":"C","text":"Declining"}],"images":["question-media/community/community-438-q37.png"],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Expanding. The shape is classified from its age structure: a broad base indicates expansion, similar-sized age bands suggest stationarity, and a narrow base with larger older groups suggests decline or constriction.","sourceLocations":[{"assessment":"Midterm","batch":"438","questionNumber":37,"sourceType":"Gift"}],"references":[{"title":"United Nations World Population Prospects","url":"https://www.un.org/development/desa/pd/content/world-population-prospects-2024"}],"lectureOrder":2,"referenceOrder":62037},{"id":"community-mid-prevention-and-control-of-infectious-214aa2e8","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"438","sourceLabel":"Community Medicine Gift","stem":"A 25-year-old student is travelling to see her parents in Makkah, She is suffering from seasonal flu and visits you to inquire what she should do to prevent transmission to her family. What will your advice be?","options":[{"id":"A","text":"Sterilize all clothing"},{"id":"B","text":"Take a flu vaccine"},{"id":"C","text":"Start Tamiflu"},{"id":"D","text":"Frequent hand washing"}],"images":[],"incompleteSource":true,"sourceAnswer":null,"sourceAnswerNote":null,"aiAnswer":"D","aiSuggestion":"Frequent hand hygiene is the appropriate listed measure to reduce household influenza transmission; vaccination does not treat the current infection.","verification":"supported","explanation":"Frequent handwashing is the appropriate listed action to reduce influenza spread to household contacts. Vaccination is preventive for future exposure and does not immediately make an actively infected person noninfectious.","sourceLocations":[{"assessment":"Midterm","batch":"438","questionNumber":38,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":62038},{"id":"community-mid-natural-history-of-disease-and-conce-39bbf742","subjectId":"community","lecture":"Natural History of Disease and Concepts of Prevention and Control","assessment":"Midterm","sourceBatch":"438","sourceLabel":"Community Medicine Gift","stem":"which level of prevention applies for the settings of policies and legislations to address behavior of the population and environment?","options":[{"id":"A","text":"Primordial prevention"},{"id":"B","text":"Primary prevention"},{"id":"C","text":"Secondary prevention"},{"id":"D","text":"Tertiary prevention"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Primordial prevention. Primordial prevention changes upstream social and environmental conditions so risk factors do not become established in the population.","sourceLocations":[{"assessment":"Midterm","batch":"438","questionNumber":40,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/index.html"}],"lectureOrder":1,"referenceOrder":62040},{"id":"community-mid-global-demography-concepts-and-popul-9d04396b","subjectId":"community","lecture":"Global Demography Concepts and Population Pyramid","assessment":"Midterm","sourceBatch":"438","sourceLabel":"Community Medicine Gift","stem":"in 2017 the death rate in Japan was approximately 9.8 deaths per 1000 population, while the birth rate was 7.7 births per 1000 population. Based on these estimates which demographic transitional stage is Japan in?","options":[{"id":"A","text":"Stage2"},{"id":"B","text":"Stage3"},{"id":"C","text":"Stage4"},{"id":"D","text":"Stage5"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Stage5. In demographic transition stage 5, the birth rate falls below the death rate, leading to population ageing and possible natural decrease.","sourceLocations":[{"assessment":"Midterm","batch":"438","questionNumber":41,"sourceType":"Gift"}],"references":[{"title":"United Nations World Population Prospects","url":"https://www.un.org/development/desa/pd/content/world-population-prospects-2024"}],"lectureOrder":2,"referenceOrder":62041},{"id":"community-mid-mental-health-523c8f2e","subjectId":"community","lecture":"Mental Health","assessment":"Midterm","sourceBatch":"438","sourceLabel":"Community Medicine Gift","stem":"A preventive medicine program aims to provide targeted help and support groups for those at high risk for mental health problems, such as people who experienced psychological trauma or abuse, WHich level of prevention is going to be used?","options":[{"id":"A","text":"Primordial"},{"id":"B","text":"Primary"},{"id":"C","text":"Secondey"},{"id":"D","text":"Tertiary"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Primary. Selective prevention targets subgroups with a higher-than-average risk before a diagnosable disorder is established.","sourceLocations":[{"assessment":"Midterm","batch":"438","questionNumber":42,"sourceType":"Gift"}],"references":[{"title":"WHO — Mental health","url":"https://www.who.int/news-room/fact-sheets/detail/mental-health-strengthening-our-response"}],"lectureOrder":9,"referenceOrder":62042},{"id":"community-mid-principles-of-epidemiology-f533ab4e","subjectId":"community","lecture":"Principles of Epidemiology","assessment":"Midterm","sourceBatch":"438","sourceLabel":"Community Medicine Gift","stem":"you have been called to assist in estimating the burden of diabetes in your region The team asks you for the best indicator to use to report the burden of diabetes in your region to the Ministry of Health. What indicator will you use for estimating the burden of such disease in your region?","options":[{"id":"A","text":"Prevalence"},{"id":"B","text":"Proportionate mortality"},{"id":"C","text":"Case-fatality"},{"id":"D","text":"Incidence"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Prevalence. Prevalence includes all existing cases at a point or during a period. It is influenced by both incidence and disease duration.","sourceLocations":[{"assessment":"Midterm","batch":"438","questionNumber":44,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Measures of Risk","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson3/section2.html"}],"lectureOrder":3,"referenceOrder":62044},{"id":"community-mid-burden-of-disease-afe0584d","subjectId":"community","lecture":"Burden of Disease","assessment":"Midterm","sourceBatch":"438","sourceLabel":"Community Medicine Gift","stem":"according to the Institute for Health metrics and Evaluation. Mitch of the following options is the most common cause of DALYs among the 70+ years Saudi population? (Seminars)","options":[{"id":"A","text":"Anxiety disorder"},{"id":"B","text":"Road traffic accident"},{"id":"C","text":"Cardiovascular diseases"},{"id":"D","text":"Iron deficiency anemia"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Cardiovascular diseases. A DALY is one lost year of healthy life and equals years of life lost from premature death (YLL) plus years lived with disability (YLD). Lower DALYs are better.","sourceLocations":[{"assessment":"Midterm","batch":"438","questionNumber":45,"sourceType":"Gift"}],"references":[{"title":"WHO — Global Health Estimates","url":"https://www.who.int/data/global-health-estimates"}],"lectureOrder":7,"referenceOrder":62045},{"id":"community-mid-social-and-behavioral-health-9f46ebd8","subjectId":"community","lecture":"Social and Behavioral Health","assessment":"Midterm","sourceBatch":"438","sourceLabel":"Community Medicine Gift","stem":"Which of the following addresses all the learning domains in a single activity?","options":[{"id":"A","text":"Lectures and group discussion"},{"id":"B","text":"Lectures and community organizations"},{"id":"C","text":"Counseling and role play"},{"id":"D","text":"Mass media and exhibition"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Counseling and role play. Counselling combined with role play can address knowledge, attitudes and practical performance together, covering cognitive, affective and psychomotor learning domains.","sourceLocations":[{"assessment":"Midterm","batch":"438","questionNumber":47,"sourceType":"Gift"}],"references":[{"title":"WHO — Health promotion","url":"https://www.who.int/health-topics/health-promotion"}],"lectureOrder":12,"referenceOrder":62047},{"id":"community-mid-surveillance-and-screening-562071e5","subjectId":"community","lecture":"Surveillance and Screening","assessment":"Midterm","sourceBatch":"438","sourceLabel":"Community Medicine Gift","stem":"The diagnostic power of a test to correctly diagnose the disease is reflected by which of the following?","options":[{"id":"A","text":"Sensitivity"},{"id":"B","text":"Specialty"},{"id":"C","text":"Positive predictivity"},{"id":"D","text":"Negative predictivity"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Positive predictivity. A test's diagnostic performance is described by sensitivity and specificity; predictive values additionally depend on disease prevalence in the tested population.","sourceLocations":[{"assessment":"Midterm","batch":"438","questionNumber":49,"sourceType":"Gift"}],"references":[{"title":"WHO — Screening programmes: a short guide","url":"https://www.who.int/publications/i/item/9789289054782"}],"lectureOrder":5,"referenceOrder":62049},{"id":"community-mid-prevention-and-control-of-infectious-d0858083","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"438","sourceLabel":"Community Medicine Gift","stem":"After a full dose of Hepatitis B vaccine, detection of which of the following in the blood test indicates successful uptake of the vaccine?","options":[{"id":"A","text":"HBsAg"},{"id":"B","text":"IgG anti-HBc"},{"id":"C","text":"IgM anti-HBc"},{"id":"D","text":"Anti-HBsAg"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Anti-HBsAg. Anti-HBs after hepatitis B vaccination indicates a protective antibody response; HBsAg would indicate current infection rather than vaccine uptake.","sourceLocations":[{"assessment":"Midterm","batch":"438","questionNumber":51,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":62051},{"id":"community-mid-maternal-health-b8bb4409","subjectId":"community","lecture":"Maternal Health","assessment":"Midterm","sourceBatch":"438","sourceLabel":"Community Medicine Gift","stem":"At a vaccination session at a Clinic. a mother told the doctor that her baby is a little unwell today and asked if it's ok to vaccinate the baby. What is the most appropriate contraindication to vaccination?","options":[{"id":"A","text":"High grade fever"},{"id":"B","text":"Premature birth"},{"id":"C","text":"Breastfeeding"},{"id":"D","text":"Antibiotic therapy"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is High grade fever. A mild illness without significant fever is generally not a contraindication to routine vaccination; unnecessary delay leaves the child susceptible.","sourceLocations":[{"assessment":"Midterm","batch":"438","questionNumber":52,"sourceType":"Gift"}],"references":[{"title":"WHO — Maternal health","url":"https://www.who.int/health-topics/maternal-health"}],"lectureOrder":11,"referenceOrder":62052},{"id":"community-mid-maternal-health-44106081","subjectId":"community","lecture":"Maternal Health","assessment":"Midterm","sourceBatch":"438","sourceLabel":"Community Medicine Gift","stem":"What is the most common cause of poor weight gain among breastfed infants during the first 4 weeks after birth?","options":[{"id":"A","text":"Low fat content of breastmilk"},{"id":"B","text":"Maternal iodine deficiency"},{"id":"C","text":"Infrequent feedings"},{"id":"D","text":"Maternal endocrine problems"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Infrequent feedings. Early poor weight gain in a breastfed infant most often reflects ineffective attachment or milk transfer, so feeding observation is essential before assuming low milk production.","sourceLocations":[{"assessment":"Midterm","batch":"438","questionNumber":53,"sourceType":"Gift"}],"references":[{"title":"WHO — Maternal health","url":"https://www.who.int/health-topics/maternal-health"}],"lectureOrder":11,"referenceOrder":62053},{"id":"community-mid-prevention-and-control-of-infectious-e0869c80","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"438","sourceLabel":"Community Medicine Gift","stem":"Hookworm infection is caused by parasites which are common in Ethiopia. The parasites live in the human intestine and lay eggs which are expelled from the body with the faeces into the soil. The eggs grow into worms in the soil, which penetrate the skin of people walking barefooted. Which of the following is a reservoir in this scenario?","options":[{"id":"A","text":"Feces"},{"id":"B","text":"Hookworm"},{"id":"C","text":"Contaminated soil"},{"id":"D","text":"Human"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Contaminated soil. Soil can act as an environmental reservoir or direct-contact source when infective larvae penetrate exposed skin.","sourceLocations":[{"assessment":"Midterm","batch":"438","questionNumber":54,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":62054},{"id":"community-mid-adolescent-and-child-health-86536694","subjectId":"community","lecture":"Adolescent and Child Health","assessment":"Midterm","sourceBatch":"438","sourceLabel":"Community Medicine Gift","stem":"Which of the following vaccines is contraindicated in patients with leukemia?","options":[{"id":"A","text":"Pertussis"},{"id":"B","text":"Measles"},{"id":"C","text":"HBV"},{"id":"D","text":"Hib"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Measles. Live attenuated measles-containing vaccine is contraindicated in severe immunodeficiency, whereas the listed inactivated or non-live vaccines do not carry the same replication risk.","sourceLocations":[{"assessment":"Midterm","batch":"438","questionNumber":55,"sourceType":"Gift"}],"references":[{"title":"WHO — Adolescent health","url":"https://www.who.int/health-topics/adolescent-health"}],"lectureOrder":10,"referenceOrder":62055},{"id":"community-mid-adolescent-and-child-health-6c212174","subjectId":"community","lecture":"Adolescent and Child Health","assessment":"Midterm","sourceBatch":"438","sourceLabel":"Community Medicine Gift","stem":"You are preparing an annual report for the CEO of the hospital on causes of child deaths in the hospital, and are required to classify the deaths Of a baby from “birth to 28 days of life” What category will these deaths be classified under?","options":[{"id":"A","text":"Perinatal death"},{"id":"B","text":"Post natal death"},{"id":"C","text":"Early neonatal death"},{"id":"D","text":"Neonatal death"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Neonatal death. Neonatal mortality covers deaths during the first 28 completed days of life and is expressed per 1,000 live births.","sourceLocations":[{"assessment":"Midterm","batch":"438","questionNumber":57,"sourceType":"Gift"}],"references":[{"title":"WHO — Adolescent health","url":"https://www.who.int/health-topics/adolescent-health"}],"lectureOrder":10,"referenceOrder":62057},{"id":"community-mid-determinants-of-health-90df52f0","subjectId":"community","lecture":"Determinants of Health","assessment":"Midterm","sourceBatch":"438","sourceLabel":"Community Medicine Gift","stem":"In 1977 the 30th World Health Assembly decided that the main social target of governments and WHO in the renting decades should be 'the attainment by all citizens of the world by the year 2000 of a level of health that will permit them to lead a Socially and economically productive life.” What is the concept that WHO is calling for?","options":[{"id":"A","text":"Disease prevention"},{"id":"B","text":"Sustainable development"},{"id":"C","text":"Right to health"},{"id":"D","text":"Health for all"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Health for all. Health for All expresses the goal that everyone can attain a level of health that permits a socially and economically productive life, with primary health care as a central strategy.","sourceLocations":[{"assessment":"Midterm","batch":"438","questionNumber":58,"sourceType":"Gift"}],"references":[{"title":"WHO — Social determinants of health","url":"https://www.who.int/health-topics/social-determinants-of-health"}],"lectureOrder":4,"referenceOrder":62058},{"id":"community-mid-introduction-to-health-policy-356399d8","subjectId":"community","lecture":"Introduction to Health Policy","assessment":"Midterm","sourceBatch":"438","sourceLabel":"Community Medicine Gift","stem":"In the New Models of Caro Program, it is the level of enabling individuals and their families to maintain their health through sell-care services, and health education. What level of care as described in the above statement?","options":[{"id":"A","text":"Activated person"},{"id":"B","text":"Healthy communities"},{"id":"C","text":"Primary healthcare"},{"id":"D","text":"Tertiary healthcare"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Activated person. In the course's Model of Care, the activated-person level equips individuals and families with health education and self-care support to maintain health.","sourceLocations":[{"assessment":"Midterm","batch":"438","questionNumber":59,"sourceType":"Gift"}],"references":[{"title":"WHO — Health policy and systems research","url":"https://www.who.int/teams/alliance-for-health-policy-systems-research"}],"lectureOrder":15,"referenceOrder":62059},{"id":"community-mid-maternal-health-28146da7","subjectId":"community","lecture":"Maternal Health","assessment":"Midterm","sourceBatch":"437","sourceLabel":"Community Medicine Gift","stem":"A 36 years old prim gravida came to you for counseling, she wants to know what is the benefit of kangaroo technique?","options":[{"id":"A","text":"Bonding"},{"id":"B","text":"Prevent nipple soreness"},{"id":"C","text":"Helps in the development of the baby"},{"id":"D","text":"no benefit"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Bonding. Kangaroo mother care promotes skin-to-skin contact, bonding, thermal stability and breastfeeding, especially for small or preterm infants.","sourceLocations":[{"assessment":"Midterm","batch":"437","questionNumber":1,"sourceType":"Gift"}],"references":[{"title":"WHO — Maternal health","url":"https://www.who.int/health-topics/maternal-health"}],"lectureOrder":11,"referenceOrder":63001},{"id":"community-mid-prevention-and-control-of-infectious-9e620819","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"437","sourceLabel":"Community Medicine Gift","stem":"A 29 years old female asking about tetanus toxoid (TT) vaccine and inquiring about latest updates, what will you advise her?","options":[{"id":"A","text":"1 Dose of TT"},{"id":"B","text":"2 Dose of TT"},{"id":"C","text":"3 Dose of TT"},{"id":"D","text":"5 Dose of TT"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D (not sure)","aiAnswer":"D","aiSuggestion":"For a woman with no documented tetanus vaccination, the full lifetime series comprises five properly spaced tetanus-toxoid-containing doses.","verification":"supported","explanation":"The recorded answer is 5 Dose of TT. Tetanus-containing vaccination in pregnancy is based on documented prior doses; an incomplete or unknown history requires an appropriate series with sufficient time before delivery.","sourceLocations":[{"assessment":"Midterm","batch":"437","questionNumber":2,"sourceType":"Gift"}],"references":[{"title":"WHO — Maternal and neonatal tetanus elimination strategies","url":"https://www.who.int/initiatives/maternal-and-neonatal-tetanus-elimination-%28mnte%29/the-strategies"}],"lectureOrder":6,"referenceOrder":63002},{"id":"community-mid-prevention-and-control-of-infectious-89fba0be","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"437","sourceLabel":"Community Medicine Gift","stem":"What is the route of transmission of scabies?","options":[{"id":"A","text":"Direct skin to skin contact and through clothing & bedding"},{"id":"B","text":"Sexually transmitted"},{"id":"C","text":"Blood transfusion"},{"id":"D","text":"Airborne"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Direct skin to skin contact and through clothing & bedding. Scabies spreads mainly through prolonged direct skin-to-skin contact; fomites play a smaller role except with crusted scabies.","sourceLocations":[{"assessment":"Midterm","batch":"437","questionNumber":4,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":63004},{"id":"community-mid-prevention-and-control-of-infectious-eddfec69","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"437","sourceLabel":"Community Medicine Gift","stem":"What is the chance of a patient with acute hepatitis C developing a chronic infection?","options":[{"id":"A","text":"40%"},{"id":"B","text":"60%"},{"id":"C","text":"20%"},{"id":"D","text":"80%"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is 80%. Age and immune status strongly affect chronic viral-hepatitis risk; hepatitis B becomes chronic far more often after perinatal infection than after adult infection.","sourceLocations":[{"assessment":"Midterm","batch":"437","questionNumber":5,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":63005},{"id":"community-mid-adolescent-and-child-health-15de1bc8","subjectId":"community","lecture":"Adolescent and Child Health","assessment":"Midterm","sourceBatch":"437","sourceLabel":"Community Medicine Gift","stem":"A mother came with her 6 months old baby and she's worried that he is not developing well. He was able to sit on the examination table. History and physical exam were unremarkable. What will you say?","options":[{"id":"A","text":"The baby is developing well because he is able to sit (correct)"},{"id":"B","text":"The baby is developing well because he is beginning to walk"},{"id":"C","text":"The baby is not developing well because he is only able to sit"},{"id":"D","text":"The baby is not developing well because he is not able to walk"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is The baby is developing well because he is able to sit (correct). Developmental milestones are assessed by age and by domains such as gross motor, fine motor, language and social skills; sitting with support at six months is generally age-appropriate.","sourceLocations":[{"assessment":"Midterm","batch":"437","questionNumber":6,"sourceType":"Gift"}],"references":[{"title":"WHO — Adolescent health","url":"https://www.who.int/health-topics/adolescent-health"}],"lectureOrder":10,"referenceOrder":63006},{"id":"community-mid-surveillance-and-screening-5d139e5f","subjectId":"community","lecture":"Surveillance and Screening","assessment":"Midterm","sourceBatch":"437","sourceLabel":"Community Medicine Gift","stem":"The diagnostic power of a test is reflected by which of the following?","options":[{"id":"A","text":"Sensitivity"},{"id":"B","text":"Specificity"},{"id":"C","text":"Positive diagnostic value"},{"id":"D","text":"Predictive Accuracy"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Predictive Accuracy. A test's diagnostic performance is described by sensitivity and specificity; predictive values additionally depend on disease prevalence in the tested population.","sourceLocations":[{"assessment":"Midterm","batch":"437","questionNumber":7,"sourceType":"Gift"}],"references":[{"title":"WHO — Screening programmes: a short guide","url":"https://www.who.int/publications/i/item/9789289054782"}],"lectureOrder":5,"referenceOrder":63007},{"id":"community-mid-principles-of-epidemiology-bd59b683","subjectId":"community","lecture":"Principles of Epidemiology","assessment":"Midterm","sourceBatch":"437","sourceLabel":"Community Medicine Gift","stem":"A study was conducted on pregnant women who suffer from HIV infection to identify the route of transmission and the percentage for transmitting the infection to the children, what’s the type of study ?","options":[{"id":"A","text":"Case report"},{"id":"B","text":"Ecological"},{"id":"C","text":"Cohort"},{"id":"D","text":"Case series"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Cohort. Following an exposed group forward to observe transmission outcomes is a cohort design, because exposure status is identified before the outcome is assessed.","sourceLocations":[{"assessment":"Midterm","batch":"437","questionNumber":8,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Measures of Risk","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson3/section2.html"}],"lectureOrder":3,"referenceOrder":63008},{"id":"community-mid-maternal-health-51a94eee","subjectId":"community","lecture":"Maternal Health","assessment":"Midterm","sourceBatch":"437","sourceLabel":"Community Medicine Gift","stem":"Which of the following is the correct position of the baby during breastfeeding?","options":[{"id":"A","text":"The whole nipple inside the mouth"},{"id":"B","text":"Chin touch the breast"},{"id":"C","text":"Bottom lip inverted"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Chin touch the breast. A wide-open mouth with the chin touching the breast is a sign of effective attachment and helps milk transfer while reducing nipple pain.","sourceLocations":[{"assessment":"Midterm","batch":"437","questionNumber":9,"sourceType":"Gift"}],"references":[{"title":"WHO — Maternal health","url":"https://www.who.int/health-topics/maternal-health"}],"lectureOrder":11,"referenceOrder":63009},{"id":"community-mid-tobacco-and-vaping-use-b40c9ebb","subjectId":"community","lecture":"Tobacco and Vaping Use","assessment":"Midterm","sourceBatch":"437","sourceLabel":"Community Medicine Gift","stem":"A smoker is started on nicotine replacement therapy. He changes his patches daily. How many days should he wait before applying a patch to the same site?","options":[{"id":"A","text":"1 day"},{"id":"B","text":"3 days"},{"id":"C","text":"One week"},{"id":"D","text":"Two weeks"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is One week. Nicotine-replacement products differ in speed of delivery: nasal spray acts faster than gum or a transdermal patch, while patches provide slower sustained delivery.","sourceLocations":[{"assessment":"Midterm","batch":"437","questionNumber":10,"sourceType":"Gift"}],"references":[{"title":"WHO — Tobacco","url":"https://www.who.int/news-room/fact-sheets/detail/tobacco"}],"lectureOrder":13,"referenceOrder":63010},{"id":"community-mid-adolescent-and-child-health-03e3cc6f","subjectId":"community","lecture":"Adolescent and Child Health","assessment":"Midterm","sourceBatch":"437","sourceLabel":"Community Medicine Gift","stem":"Which of the following is the leading cause of death in adolescence?","options":[{"id":"A","text":"Injury, HIV, Self harm"},{"id":"B","text":"Injury, HIV, Depression"},{"id":"C","text":"Injury, Epilepsy, Drowning"},{"id":"D","text":"Epilepsy, HIV, STD"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Injury, HIV, Self harm. Anxiety and depressive disorders are among the leading mental-health causes of illness and disability during adolescence.","sourceLocations":[{"assessment":"Midterm","batch":"437","questionNumber":12,"sourceType":"Gift"}],"references":[{"title":"WHO — Adolescent health","url":"https://www.who.int/health-topics/adolescent-health"}],"lectureOrder":10,"referenceOrder":63012},{"id":"community-mid-prevention-and-control-of-infectious-69cda3c3","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"437","sourceLabel":"Community Medicine Gift","stem":"The prevalence of Malaria in India from 2005 to 2010 was between 1,500,000 - 2,000,000. And in 2006 it was 1,800,000, which of the following best describes the increase in number?","options":[{"id":"A","text":"Pandemic"},{"id":"B","text":"Epidemic"},{"id":"C","text":"Sporadic"},{"id":"D","text":"Endemic"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Epidemic. Prevalence includes all existing cases at a point or during a period. It is influenced by both incidence and disease duration.","sourceLocations":[{"assessment":"Midterm","batch":"437","questionNumber":13,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":63013},{"id":"community-mid-mental-health-fb7649df","subjectId":"community","lecture":"Mental Health","assessment":"Midterm","sourceBatch":"437","sourceLabel":"Community Medicine Gift","stem":"A darked skinned child was bullied in school for a long period of time, he became more quiet and his grades in school declined, what is the cause of his problem?","options":[{"id":"A","text":"Social pathology"},{"id":"B","text":"Psychosocial pathology"},{"id":"C","text":"Environment"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Social pathology. Persistent bullying followed by withdrawal and declining school performance is a warning pattern requiring early psychosocial assessment and support.","sourceLocations":[{"assessment":"Midterm","batch":"437","questionNumber":14,"sourceType":"Gift"}],"references":[{"title":"WHO — Mental health","url":"https://www.who.int/news-room/fact-sheets/detail/mental-health-strengthening-our-response"}],"lectureOrder":9,"referenceOrder":63014},{"id":"community-mid-global-demography-concepts-and-popul-8a332e2b","subjectId":"community","lecture":"Global Demography Concepts and Population Pyramid","assessment":"Midterm","sourceBatch":"437","sourceLabel":"Community Medicine Gift","stem":"What will happen to the distribution of old people in Saudi Arabia?","options":[{"id":"A","text":"Rapidly decrease"},{"id":"B","text":"No change"},{"id":"C","text":"Rapidly increase"},{"id":"D","text":"Unpredictable"}],"images":["question-media/community/community-437-q15.png"],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Rapidly increase. Falling fertility and improving survival increase the proportion of older adults, so population ageing is expected to increase the older share.","sourceLocations":[{"assessment":"Midterm","batch":"437","questionNumber":15,"sourceType":"Gift"}],"references":[{"title":"United Nations World Population Prospects","url":"https://www.un.org/development/desa/pd/content/world-population-prospects-2024"}],"lectureOrder":2,"referenceOrder":63015},{"id":"community-mid-global-demography-concepts-and-popul-00dd9968","subjectId":"community","lecture":"Global Demography Concepts and Population Pyramid","assessment":"Midterm","sourceBatch":"437","sourceLabel":"Community Medicine Gift","stem":"What type of population pyramid is this?","options":[{"id":"A","text":"Expanding"},{"id":"B","text":"Stationary"},{"id":"C","text":"Declining"},{"id":"D","text":"Positional"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Stationary. The shape is classified from its age structure: a broad base indicates expansion, similar-sized age bands suggest stationarity, and a narrow base with larger older groups suggests decline or constriction.","sourceLocations":[{"assessment":"Midterm","batch":"437","questionNumber":16,"sourceType":"Gift"},{"assessment":"Midterm","batch":"436","questionNumber":2,"sourceType":"Gift"}],"references":[{"title":"United Nations World Population Prospects","url":"https://www.un.org/development/desa/pd/content/world-population-prospects-2024"}],"lectureOrder":2,"referenceOrder":63016},{"id":"community-mid-natural-history-of-disease-and-conce-6f4090e5","subjectId":"community","lecture":"Natural History of Disease and Concepts of Prevention and Control","assessment":"Midterm","sourceBatch":"437","sourceLabel":"Community Medicine Gift","stem":"Primary preventive measures can be applied at which stage of the natural history of disease?","options":[{"id":"A","text":"server symptomatic"},{"id":"B","text":"Symptomatic"},{"id":"C","text":"Stage of positive health"},{"id":"D","text":"Classical disease"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Stage of positive health. Positive health is the upper end of the health–disease spectrum; death is the lower end.","sourceLocations":[{"assessment":"Midterm","batch":"437","questionNumber":17,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/index.html"}],"lectureOrder":1,"referenceOrder":63017},{"id":"community-mid-maternal-health-77783cf2","subjectId":"community","lecture":"Maternal Health","assessment":"Midterm","sourceBatch":"437","sourceLabel":"Community Medicine Gift","stem":"Which of the following vaccines is contraindicated in pregnancy?","options":[{"id":"A","text":"MMR"},{"id":"B","text":"DTP"},{"id":"C","text":"Hep A"},{"id":"D","text":"Pneumococcal"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is MMR. Measles-containing vaccines such as MMR are live attenuated vaccines; the schedule and contraindications must follow the current national programme.","sourceLocations":[{"assessment":"Midterm","batch":"437","questionNumber":18,"sourceType":"Gift"}],"references":[{"title":"WHO — Maternal health","url":"https://www.who.int/health-topics/maternal-health"}],"lectureOrder":11,"referenceOrder":63018},{"id":"community-mid-prevention-and-control-of-infectious-84c1bff7","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"437","sourceLabel":"Community Medicine Gift","stem":"Which of the following is considered as vertical transmission in HIV/AIDS?","options":[{"id":"A","text":"Blood transfusion"},{"id":"B","text":"Breastfeeding"},{"id":"C","text":"Sexual Transmission"},{"id":"D","text":"Needles"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Breastfeeding. Vertical transmission can occur during pregnancy, labour and delivery, or breastfeeding; effective maternal treatment and perinatal care markedly reduce risk.","sourceLocations":[{"assessment":"Midterm","batch":"437","questionNumber":19,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":63019},{"id":"community-mid-prevention-and-control-of-infectious-9351c84a","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"437","sourceLabel":"Community Medicine Gift","stem":"In order to strengthen malaria control in epidemic areas the prevention team started pesticides in the form of fog and mist, what does this strategy called?","options":[{"id":"A","text":"Residual spraying"},{"id":"B","text":"Source control"},{"id":"D","text":""}],"images":[],"incompleteSource":true,"sourceAnswer":null,"sourceAnswerNote":null,"aiAnswer":null,"aiSuggestion":"Fog or mist application is space spraying. That term is missing from the incomplete options, so no listed option is graded correct.","verification":"conflict","explanation":"No reference answer was recorded. Applying insecticide as fog or mist is space spraying, a rapid adult-mosquito control measure; residual spraying treats indoor surfaces instead.","sourceLocations":[{"assessment":"Midterm","batch":"437","questionNumber":20,"sourceType":"Gift"}],"references":[{"title":"WHO — Malaria entomology and vector control","url":"https://www.afro.who.int/sites/default/files/2017-06/9789241505819_eng.pdf"}],"lectureOrder":6,"referenceOrder":63020},{"id":"community-mid-adolescent-and-child-health-54d6f0b7","subjectId":"community","lecture":"Adolescent and Child Health","assessment":"Midterm","sourceBatch":"437","sourceLabel":"Community Medicine Gift","stem":"A 4 year old child with a 3 days history of sore throat, mild fever, and a bluish-white mucosal membrane, What vaccines has he missed?","options":[{"id":"A","text":"MMR"},{"id":"B","text":"DPT"},{"id":"C","text":"BCG"},{"id":"D","text":"IPV"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is DPT. A pharyngeal pseudomembrane suggests diphtheria; the preventive vaccine component is diphtheria toxoid in DPT-containing vaccines.","sourceLocations":[{"assessment":"Midterm","batch":"437","questionNumber":21,"sourceType":"Gift"}],"references":[{"title":"WHO — Adolescent health","url":"https://www.who.int/health-topics/adolescent-health"}],"lectureOrder":10,"referenceOrder":63021},{"id":"community-mid-adolescent-and-child-health-7bd9c9d8","subjectId":"community","lecture":"Adolescent and Child Health","assessment":"Midterm","sourceBatch":"437","sourceLabel":"Community Medicine Gift","stem":"Baby girl died on the 12th day of life, At which stage she died?","options":[{"id":"A","text":"Late neonatal death"},{"id":"B","text":"Early neonatal death"},{"id":"C","text":"Perinatal death"},{"id":"D","text":"Postnatal death"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Late neonatal death. Neonatal mortality covers deaths during the first 28 completed days of life and is expressed per 1,000 live births.","sourceLocations":[{"assessment":"Midterm","batch":"437","questionNumber":23,"sourceType":"Gift"}],"references":[{"title":"WHO — Adolescent health","url":"https://www.who.int/health-topics/adolescent-health"}],"lectureOrder":10,"referenceOrder":63023},{"id":"community-mid-global-demography-concepts-and-popul-d6233972","subjectId":"community","lecture":"Global Demography Concepts and Population Pyramid","assessment":"Midterm","sourceBatch":"437","sourceLabel":"Community Medicine Gift","stem":"A country has 7 per 1000 deaths and 7 per 1000 births, at which stage of the demographic transition is it?","options":[{"id":"A","text":"Stage 2"},{"id":"B","text":"Stage 3"},{"id":"C","text":"Stage 4"},{"id":"D","text":"Stage 5"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Stage 4. Stage 4 has low birth and death rates, so population growth is low and the population is relatively stable.","sourceLocations":[{"assessment":"Midterm","batch":"437","questionNumber":24,"sourceType":"Gift"}],"references":[{"title":"United Nations World Population Prospects","url":"https://www.un.org/development/desa/pd/content/world-population-prospects-2024"}],"lectureOrder":2,"referenceOrder":63024},{"id":"community-mid-prevention-and-control-of-infectious-b0184d8d","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"437","sourceLabel":"Community Medicine Gift","stem":"Reservoir of hookworm?","options":[{"id":"A","text":"Contaminated soil"},{"id":"B","text":"Human"},{"id":"C","text":"Mosquito"},{"id":"D","text":"Water"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Contaminated soil. Soil can act as an environmental reservoir or direct-contact source when infective larvae penetrate exposed skin.","sourceLocations":[{"assessment":"Midterm","batch":"437","questionNumber":25,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":63025},{"id":"community-mid-maternal-health-5244d13d","subjectId":"community","lecture":"Maternal Health","assessment":"Midterm","sourceBatch":"437","sourceLabel":"Community Medicine Gift","stem":"The number of baby friendly hospital in Saudi Arabia is:","options":[{"id":"A","text":"46"},{"id":"B","text":"50"},{"id":"C","text":"64"},{"id":"D","text":"105"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is 64. The Baby-friendly Hospital Initiative applies evidence-based maternity and newborn-care practices that protect, promote and support breastfeeding.","sourceLocations":[{"assessment":"Midterm","batch":"437","questionNumber":26,"sourceType":"Gift"}],"references":[{"title":"WHO — Maternal health","url":"https://www.who.int/health-topics/maternal-health"}],"lectureOrder":11,"referenceOrder":63026},{"id":"community-mid-introduction-to-health-policy-31c224e5","subjectId":"community","lecture":"Introduction to Health Policy","assessment":"Midterm","sourceBatch":"437","sourceLabel":"Community Medicine Gift","stem":"The new model of care program has been designed to answer Six key questions. Which of the following answers this question “How will the system help to keep me well”?","options":[{"id":"A","text":"Urgent care"},{"id":"B","text":"Chronic care"},{"id":"C","text":"Planned care"},{"id":"D","text":"Preventive care"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Preventive care. The Model of Care organizes services around people's needs and levels of intervention; the keyed phrase reflects the course framework rather than a clinical diagnosis.","sourceLocations":[{"assessment":"Midterm","batch":"437","questionNumber":27,"sourceType":"Gift"}],"references":[{"title":"WHO — Health policy and systems research","url":"https://www.who.int/teams/alliance-for-health-policy-systems-research"}],"lectureOrder":15,"referenceOrder":63027},{"id":"community-mid-introduction-to-health-policy-c1263528","subjectId":"community","lecture":"Introduction to Health Policy","assessment":"Midterm","sourceBatch":"437","sourceLabel":"Community Medicine Gift","stem":"Which of the following pillars are Health under Vision 2030?","options":[{"id":"A","text":"Strengthen islamic values"},{"id":"B","text":"Vibrant society"},{"id":"C","text":"Offering a fulfilling and healthy life"},{"id":"D","text":"Promote a healthy lifestyle"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Vibrant society. The keyed pillar is retained from the course's Vision 2030 framework; it should be read as a policy-structure question, not as a clinical recommendation.","sourceLocations":[{"assessment":"Midterm","batch":"437","questionNumber":28,"sourceType":"Gift"}],"references":[{"title":"WHO — Health policy and systems research","url":"https://www.who.int/teams/alliance-for-health-policy-systems-research"}],"lectureOrder":15,"referenceOrder":63028},{"id":"community-mid-introduction-to-health-policy-f1a6a848","subjectId":"community","lecture":"Introduction to Health Policy","assessment":"Midterm","sourceBatch":"437","sourceLabel":"Community Medicine Gift","stem":"Which of the following Levels of Care that active individuals are at the heart of the model by enabling them and their families to maintain their health, through self-care services, and health education?","options":[{"id":"A","text":"Healthy community"},{"id":"B","text":"Virtual care"},{"id":"C","text":"Primary care"},{"id":"D","text":"Activated Person"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Activated Person. The Model of Care organizes services around people's needs and levels of intervention; the keyed phrase reflects the course framework rather than a clinical diagnosis.","sourceLocations":[{"assessment":"Midterm","batch":"437","questionNumber":29,"sourceType":"Gift"}],"references":[{"title":"WHO — Health policy and systems research","url":"https://www.who.int/teams/alliance-for-health-policy-systems-research"}],"lectureOrder":15,"referenceOrder":63029},{"id":"community-mid-adolescent-and-child-health-0194c841","subjectId":"community","lecture":"Adolescent and Child Health","assessment":"Midterm","sourceBatch":"437","sourceLabel":"Community Medicine Gift","stem":"Which of the following vaccines is given to 9 months old girl?","options":[{"id":"A","text":"Measles and meningococcal"},{"id":"B","text":"MMR"},{"id":"C","text":"DpTH -Hep B - HIB"},{"id":"D","text":"BCG"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Measles and meningococcal. The answer follows the Saudi national immunization schedule presented in the lecture for the nine-month visit; schedule timing should be checked against the current MOH version.","sourceLocations":[{"assessment":"Midterm","batch":"437","questionNumber":31,"sourceType":"Gift"}],"references":[{"title":"WHO — Adolescent health","url":"https://www.who.int/health-topics/adolescent-health"}],"lectureOrder":10,"referenceOrder":63031},{"id":"community-mid-determinants-of-health-46065e84","subjectId":"community","lecture":"Determinants of Health","assessment":"Midterm","sourceBatch":"436","sourceLabel":"Community Medicine Gift","stem":"How many factors are in the \"BEINGS\" model?","options":[{"id":"A","text":"6"},{"id":"B","text":"8"},{"id":"C","text":"9"},{"id":"D","text":"10"}],"images":["question-media/community/community-436-q01.png"],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is 9. BEINGS is a course framework for grouping determinants of health; the keyed number should be interpreted according to the factors shown in the current lecture diagram.","sourceLocations":[{"assessment":"Midterm","batch":"436","questionNumber":1,"sourceType":"Gift"}],"references":[{"title":"WHO — Social determinants of health","url":"https://www.who.int/health-topics/social-determinants-of-health"}],"lectureOrder":4,"referenceOrder":64001},{"id":"community-mid-prevention-and-control-of-infectious-14e458af","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"436","sourceLabel":"Community Medicine Gift","stem":"What is the infective material for hepatitis A?","options":[{"id":"A","text":"Blood"},{"id":"B","text":"Urine"},{"id":"C","text":"Semen"},{"id":"D","text":"Feces"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Feces. Hepatitis A is shed in feces and spreads mainly by the fecal–oral route, especially through contaminated food, water or hands.","sourceLocations":[{"assessment":"Midterm","batch":"436","questionNumber":3,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":64003},{"id":"community-mid-prevention-and-control-of-infectious-b8bad4bd","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"436","sourceLabel":"Community Medicine Gift","stem":"A mother wants to give her baby the hepatitis A vaccine. When is the first dose given for infants?","options":[{"id":"A","text":"8 months"},{"id":"B","text":"12 months"},{"id":"C","text":"18 months"},{"id":"D","text":"24 months"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is 18 months. The answer follows the age in the Saudi schedule presented in the course; the schedule should be checked against the latest MOH version before clinical use.","sourceLocations":[{"assessment":"Midterm","batch":"436","questionNumber":4,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":64004},{"id":"community-mid-prevention-and-control-of-infectious-2ca84d68","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"436","sourceLabel":"Community Medicine Gift","stem":"What is the method of preventing hepatitis A?","options":[{"id":"A","text":"Community hygiene"},{"id":"B","text":"Blood screening"},{"id":"C","text":"Drinking Milk"},{"id":"D","text":"Clean blood transfusion"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A (not sure)","aiAnswer":"A","aiSuggestion":"Hepatitis A is transmitted fecal-orally, so safe water, sanitation and community hygiene are the appropriate listed preventive measures.","verification":"supported","explanation":"Hepatitis A spreads by the fecal–oral route. Safe water, sanitation, food hygiene and hand hygiene are therefore the appropriate listed community-level preventive measures.","sourceLocations":[{"assessment":"Midterm","batch":"436","questionNumber":5,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":64005},{"id":"community-mid-prevention-and-control-of-infectious-5efc982b","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"436","sourceLabel":"Community Medicine Gift","stem":"According to the national guide, when do we give hepatitis B vaccine?","options":[{"id":"A","text":"At birth, 2, 4, 8 months"},{"id":"B","text":"At birth, 2, 4, 6 months"},{"id":"C","text":"At birth, 2, 4,6, 8 months"},{"id":"D","text":"At birth, 2, 4, 12months"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is At birth, 2, 4, 6 months. The first hepatitis B dose is scheduled at birth to reduce perinatal and early-childhood transmission; subsequent doses complete the primary series.","sourceLocations":[{"assessment":"Midterm","batch":"436","questionNumber":6,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":64006},{"id":"community-mid-global-demography-concepts-and-popul-7b09896a","subjectId":"community","lecture":"Global Demography Concepts and Population Pyramid","assessment":"Midterm","sourceBatch":"436","sourceLabel":"Community Medicine Gift","stem":"In Japan the crude death rate was 9.7 and birth rate was 7.8 which stage for demographic transition is this?","options":[{"id":"A","text":"Stage one"},{"id":"B","text":"Stage two"},{"id":"C","text":"Stage three"},{"id":"D","text":"Stage five"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Stage five. The crude death rate is all deaths during the period divided by the mid-year population, usually expressed per 1,000 population.","sourceLocations":[{"assessment":"Midterm","batch":"436","questionNumber":7,"sourceType":"Gift"}],"references":[{"title":"United Nations World Population Prospects","url":"https://www.un.org/development/desa/pd/content/world-population-prospects-2024"}],"lectureOrder":2,"referenceOrder":64007},{"id":"community-mid-prevention-and-control-of-infectious-99342e53","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"436","sourceLabel":"Community Medicine Gift","stem":"A 40 year old male hospital worker came to you because he wants the hepatitis B vaccine? What is the appropriate management?","options":[{"id":"A","text":"Start him on hepatitis vaccine"},{"id":"B","text":"Give him hepatitis immunoglobulin"},{"id":"C","text":"Give both passive and active immunization"},{"id":"D","text":"Screen for hepatitis antigen"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Screen for hepatitis antigen. A healthcare worker should first have hepatitis B status and prior vaccination documented; vaccination or post-exposure immunoprophylaxis then depends on those results and any exposure history.","sourceLocations":[{"assessment":"Midterm","batch":"436","questionNumber":8,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":64008},{"id":"community-mid-prevention-and-control-of-infectious-73e63879","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"436","sourceLabel":"Community Medicine Gift","stem":"Who has more chance of developing chronic infection?","options":[{"id":"A","text":"Infant"},{"id":"B","text":"Pregnant"},{"id":"C","text":"Elderly"},{"id":"D","text":"Young adult"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Infant. Age and immune status strongly affect chronic viral-hepatitis risk; hepatitis B becomes chronic far more often after perinatal infection than after adult infection.","sourceLocations":[{"assessment":"Midterm","batch":"436","questionNumber":9,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":64009},{"id":"community-mid-prevention-and-control-of-infectious-d84ceb99","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"436","sourceLabel":"Community Medicine Gift","stem":"Appearance of which of the following will indicate successful vaccination?","options":[{"id":"A","text":"Anti- HBsAg"},{"id":"B","text":"Anti - HBe"},{"id":"C","text":"HBsAg"},{"id":"D","text":"Hb core antigen"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Anti- HBsAg. A protective anti-HBs response after hepatitis B vaccination demonstrates successful active immunization; HBsAg would instead indicate current infection.","sourceLocations":[{"assessment":"Midterm","batch":"436","questionNumber":10,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":64010},{"id":"community-mid-prevention-and-control-of-infectious-ec94bf92","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"436","sourceLabel":"Community Medicine Gift","stem":"Mona has measles and got sick leave from school when will she able to go back to school?","options":[{"id":"A","text":"After the end of communicable stage"},{"id":"B","text":"Until she fully recovered"},{"id":"C","text":"The longest incubation period"},{"id":"D","text":"The extrinsic incubation period"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is After the end of communicable stage. School exclusion for measles covers the infectious period; the return date is counted from rash onset according to public-health guidance.","sourceLocations":[{"assessment":"Midterm","batch":"436","questionNumber":11,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":64011},{"id":"community-mid-principles-of-epidemiology-d9a57891","subjectId":"community","lecture":"Principles of Epidemiology","assessment":"Midterm","sourceBatch":"436","sourceLabel":"Community Medicine Gift","stem":"Which of the following measures is used frequently as the numerator to calculate incidence?","options":[{"id":"A","text":"Person-years of observation"},{"id":"B","text":"Number of symptomatic cases"},{"id":"C","text":"Number of new cases"},{"id":"D","text":"Number of cases"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Number of new cases. Incidence counts new cases arising in an at-risk population during a stated period, so it measures risk or the rate of developing disease.","sourceLocations":[{"assessment":"Midterm","batch":"436","questionNumber":12,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Measures of Risk","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson3/section2.html"}],"lectureOrder":3,"referenceOrder":64012},{"id":"community-mid-prevention-and-control-of-infectious-022be3da","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"436","sourceLabel":"Community Medicine Gift","stem":"Whats is the recommendation of WHO for TB patients?","options":[{"id":"A","text":"Treatment with DOTS strategy"},{"id":"B","text":"BCG vaccination"},{"id":"C","text":"Isolation of patients"},{"id":"D","text":"Occupational and social rehabilitation"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Treatment with DOTS strategy. Directly observed therapy supports completion of an effective multidrug tuberculosis regimen and reduces treatment failure, relapse and acquired resistance.","sourceLocations":[{"assessment":"Midterm","batch":"436","questionNumber":13,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":64013},{"id":"community-mid-prevention-and-control-of-infectious-6dc2bac1","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"436","sourceLabel":"Community Medicine Gift","stem":"Which of the following is the leading cause of death in HIV infected people?","options":[{"id":"A","text":"TB"},{"id":"B","text":"Brucellosis"},{"id":"C","text":"Toxoplasma"},{"id":"D","text":"Mers coA"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is TB. Tuberculosis is a major cause of death among people living with HIV because immunosuppression greatly increases progression and severe disease risk.","sourceLocations":[{"assessment":"Midterm","batch":"436","questionNumber":14,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":64014},{"id":"community-mid-prevention-and-control-of-infectious-7595a48d","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"436","sourceLabel":"Community Medicine Gift","stem":"Which of the following zoonotic diseases can be transmitted from human to human?","options":[{"id":"A","text":"Brucellosis"},{"id":"B","text":"Mers coA"},{"id":"C","text":"Toxoplasmosis"},{"id":"D","text":"Yellow fever"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Mers coA. A zoonosis is naturally transmitted between vertebrate animals and humans; whether onward human-to-human spread occurs depends on the specific agent.","sourceLocations":[{"assessment":"Midterm","batch":"436","questionNumber":15,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":64015},{"id":"community-mid-natural-history-of-disease-and-conce-c47ed759","subjectId":"community","lecture":"Natural History of Disease and Concepts of Prevention and Control","assessment":"Midterm","sourceBatch":"436","sourceLabel":"Community Medicine Gift","stem":"When to apply health promotion at which level of health spectrum?","options":[{"id":"A","text":"Susceptible person"},{"id":"B","text":"Asymptomatic"},{"id":"C","text":"Discernible disease"},{"id":"D","text":"Positive health"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Positive health. Positive health is the upper end of the health–disease spectrum; death is the lower end.","sourceLocations":[{"assessment":"Midterm","batch":"436","questionNumber":17,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/index.html"}],"lectureOrder":1,"referenceOrder":64017},{"id":"community-mid-prevention-and-control-of-infectious-16de16da","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"436","sourceLabel":"Community Medicine Gift","stem":"Which of the following represent “The lodgment, development and reproduction of arthropods on the surface of the body or in the clothing”?","options":[{"id":"A","text":"Contamination"},{"id":"B","text":"Infestation"},{"id":"C","text":"Eradication"},{"id":"D","text":"Elimination"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Infestation. Reliability is reproducibility: the indicator gives consistent results when measurement is repeated under comparable conditions.","sourceLocations":[{"assessment":"Midterm","batch":"436","questionNumber":18,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":64018},{"id":"community-mid-prevention-and-control-of-infectious-2f970290","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"436","sourceLabel":"Community Medicine Gift","stem":"Which of the following is the best term for cases that are haphazard, irregular, and infrequent and are separated widely in space and time?","options":[{"id":"A","text":"Epidemic"},{"id":"B","text":"Endemic"},{"id":"C","text":"Outbreak"},{"id":"D","text":"Sporadic"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Sporadic. Sporadic disease occurs irregularly and infrequently, with cases separated in place or time and no sustained pattern.","sourceLocations":[{"assessment":"Midterm","batch":"436","questionNumber":19,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":64019},{"id":"community-mid-disparities-in-health-262063b5","subjectId":"community","lecture":"Disparities in Health","assessment":"Midterm","sourceBatch":"436","sourceLabel":"Community Medicine Gift","stem":"What to use for global comparison?","options":[{"id":"A","text":"Infant mortality"},{"id":"B","text":"Maternal mortality"},{"id":"C","text":"Life expectancy at birth"},{"id":"D","text":"Crude death rate"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Life expectancy at birth. Life expectancy summarizes the average years a person is expected to live under current mortality patterns, making it useful for broad population comparisons.","sourceLocations":[{"assessment":"Midterm","batch":"436","questionNumber":20,"sourceType":"Gift"}],"references":[{"title":"WHO — Health inequities and their causes","url":"https://www.who.int/news-room/facts-in-pictures/detail/health-inequities-and-their-causes"}],"lectureOrder":8,"referenceOrder":64020},{"id":"community-mid-prevention-and-control-of-infectious-157fbebc","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"436","sourceLabel":"Community Medicine Gift","stem":"40 years old Saudi man planning to go to West Africa. Which one of the following preventive measures he should follow?","options":[{"id":"A","text":"Wear face mask"},{"id":"B","text":"Boiling water before drinking"},{"id":"C","text":"Vaccine"},{"id":"D","text":"Chemoprophylaxis"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Chemoprophylaxis. Travel to a yellow-fever-risk area requires destination-specific vaccination and mosquito-bite prevention, with entry requirements checked before travel.","sourceLocations":[{"assessment":"Midterm","batch":"436","questionNumber":21,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":64021},{"id":"community-mid-prevention-and-control-of-infectious-ec31b2be","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"436","sourceLabel":"Community Medicine Gift","stem":"You work in prevention of malaria in west Africa, what is the best prevention?","options":[{"id":"A","text":"Mass vaccination"},{"id":"B","text":"Use insecticides in beds and crops"},{"id":"C","text":"Use sprayed nets"},{"id":"D","text":"Drinking a lot of orange juice"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Use sprayed nets. Malaria prevention combines vector control—especially insecticide-treated nets and indoor residual spraying—with chemoprevention and prompt diagnosis where indicated.","sourceLocations":[{"assessment":"Midterm","batch":"436","questionNumber":22,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":64022},{"id":"community-mid-prevention-and-control-of-infectious-6906c029","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"436","sourceLabel":"Community Medicine Gift","stem":"What is the main reservoir for influenza A?","options":[{"id":"A","text":"Human"},{"id":"B","text":"Animal"},{"id":"C","text":"Water"},{"id":"D","text":"Food"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Animal. A reservoir is the habitat in which an infectious agent normally lives, grows and multiplies; it is not always the same as the immediate source of exposure.","sourceLocations":[{"assessment":"Midterm","batch":"436","questionNumber":23,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":64023},{"id":"community-mid-prevention-and-control-of-infectious-34c6ad62","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"436","sourceLabel":"Community Medicine Gift","stem":"What should pregnant women avoid to protect against toxoplasmosis?","options":[{"id":"A","text":"Vegetables"},{"id":"B","text":"Goat cheese"},{"id":"C","text":"Tuna"},{"id":"D","text":"Smoked meat"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Smoked meat. All tobacco products can cause harm, nicotine drives dependence, and vaping is not harmless. Cessation combines behavioral support with evidence-based pharmacotherapy when appropriate.","sourceLocations":[{"assessment":"Midterm","batch":"436","questionNumber":24,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":64024},{"id":"community-mid-disparities-in-health-baf9ae41","subjectId":"community","lecture":"Disparities in Health","assessment":"Midterm","sourceBatch":"436","sourceLabel":"Community Medicine Gift","stem":"In a tuberculosis study 200 cases where reported, 7 of which died, what can be calculated?","options":[{"id":"A","text":"Disease specific mortality rate"},{"id":"B","text":"Case fatality rate"},{"id":"C","text":"Standardized mortality rate"},{"id":"D","text":"Proportionate mortality rate"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Case fatality rate. Case fatality is deaths among diagnosed cases divided by all cases of that disease; it describes severity rather than population risk.","sourceLocations":[{"assessment":"Midterm","batch":"436","questionNumber":25,"sourceType":"Gift"}],"references":[{"title":"WHO — Health inequities and their causes","url":"https://www.who.int/news-room/facts-in-pictures/detail/health-inequities-and-their-causes"}],"lectureOrder":8,"referenceOrder":64025},{"id":"community-mid-disparities-in-health-559c82c8","subjectId":"community","lecture":"Disparities in Health","assessment":"Midterm","sourceBatch":"436","sourceLabel":"Community Medicine Gift","stem":"Death from colon cancer per 100 people, this is called?","options":[{"id":"A","text":"Disease specific mortality rate"},{"id":"B","text":"Case fatality rate"},{"id":"C","text":"Standardized mortality rate"},{"id":"D","text":"Proportionate mortality rate"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Disease specific mortality rate. A cause-specific mortality rate uses deaths from the named cause in the numerator and the relevant population in the denominator over a stated period.","sourceLocations":[{"assessment":"Midterm","batch":"436","questionNumber":27,"sourceType":"Gift"}],"references":[{"title":"WHO — Health inequities and their causes","url":"https://www.who.int/news-room/facts-in-pictures/detail/health-inequities-and-their-causes"}],"lectureOrder":8,"referenceOrder":64027},{"id":"community-mid-disparities-in-health-358150df","subjectId":"community","lecture":"Disparities in Health","assessment":"Midterm","sourceBatch":"436","sourceLabel":"Community Medicine Gift","stem":"(Table of KSA from 2016, 2025, and 2050. The description of the table: increased population size, decreased birth rate, increased mortality, and increased age) Why is the crude mortality rate increased?","options":[{"id":"A","text":"Decreased birth rate"},{"id":"B","text":"Increased population size"},{"id":"C","text":"Increased age"},{"id":"D","text":"Deteriorated life style"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Increased age. The crude death rate is all deaths during the period divided by the mid-year population, usually expressed per 1,000 population.","sourceLocations":[{"assessment":"Midterm","batch":"436","questionNumber":28,"sourceType":"Gift"}],"references":[{"title":"WHO — Health inequities and their causes","url":"https://www.who.int/news-room/facts-in-pictures/detail/health-inequities-and-their-causes"}],"lectureOrder":8,"referenceOrder":64028},{"id":"community-mid-disparities-in-health-949dc984","subjectId":"community","lecture":"Disparities in Health","assessment":"Midterm","sourceBatch":"436","sourceLabel":"Community Medicine Gift","stem":"Death due to colon cancer was 7 among 22 diagnosed with cancer, what does this indicate?","options":[{"id":"A","text":"Disease specific mortality rate"},{"id":"B","text":"Case fatality rate"},{"id":"C","text":"Standardized mortality rate"},{"id":"D","text":"Proportionate mortality rate"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Case fatality rate. Case fatality is deaths among diagnosed cases divided by all cases of that disease; it describes severity rather than population risk.","sourceLocations":[{"assessment":"Midterm","batch":"436","questionNumber":29,"sourceType":"Gift"}],"references":[{"title":"WHO — Health inequities and their causes","url":"https://www.who.int/news-room/facts-in-pictures/detail/health-inequities-and-their-causes"}],"lectureOrder":8,"referenceOrder":64029},{"id":"community-mid-disparities-in-health-cb694c66","subjectId":"community","lecture":"Disparities in Health","assessment":"Midterm","sourceBatch":"436","sourceLabel":"Community Medicine Gift","stem":"What is the best indicator of global health?","options":[{"id":"A","text":"Infant mortality rate"},{"id":"B","text":"Life expectancy at birth"},{"id":"C","text":"Literacy rate"},{"id":"D","text":"Unemployment rate"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B, Source: 436 slides","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Life expectancy at birth. Life expectancy summarizes the average years a person is expected to live under current mortality patterns, making it useful for broad population comparisons.","sourceLocations":[{"assessment":"Midterm","batch":"436","questionNumber":30,"sourceType":"Gift"}],"references":[{"title":"WHO — Health inequities and their causes","url":"https://www.who.int/news-room/facts-in-pictures/detail/health-inequities-and-their-causes"}],"lectureOrder":8,"referenceOrder":64030},{"id":"community-mid-prevention-and-control-of-infectious-684c1c3a","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"436","sourceLabel":"Community Medicine Gift","stem":"Which of the following will prevent disease by killing of infectious agent?","options":[{"id":"A","text":"Elimination"},{"id":"B","text":"Eradication"},{"id":"C","text":"Control"},{"id":"D","text":"Herd immunity"}],"images":["question-media/community/community-436-q31.png"],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Eradication. Eradication means permanent worldwide reduction to zero of infection caused by the agent, after which routine control measures are no longer required.","sourceLocations":[{"assessment":"Midterm","batch":"436","questionNumber":31,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":64031},{"id":"community-mid-global-demography-concepts-and-popul-3047d6ae","subjectId":"community","lecture":"Global Demography Concepts and Population Pyramid","assessment":"Midterm","sourceBatch":"436","sourceLabel":"Community Medicine Gift","stem":"Which of the following represent this population pyramid?","options":[{"id":"A","text":"Declining"},{"id":"B","text":"Constrictive"},{"id":"C","text":"Expansive"},{"id":"D","text":"Stationary"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Constrictive. A population pyramid displays age and sex structure; a broad base suggests high fertility and a younger population, while a narrower base and larger older groups suggest ageing.","sourceLocations":[{"assessment":"Midterm","batch":"436","questionNumber":32,"sourceType":"Gift"}],"references":[{"title":"United Nations World Population Prospects","url":"https://www.un.org/development/desa/pd/content/world-population-prospects-2024"}],"lectureOrder":2,"referenceOrder":64032},{"id":"community-mid-natural-history-of-disease-and-conce-66521aaf","subjectId":"community","lecture":"Natural History of Disease and Concepts of Prevention and Control","assessment":"Midterm","sourceBatch":"436","sourceLabel":"Community Medicine Gift","stem":"For some illnesses, few are reported and many remain hidden representing \"the tip of the iceberg\". Which of the following illustrates the above phenomenon?","options":[{"id":"A","text":"Chickenpox"},{"id":"B","text":"Yellow fever"},{"id":"C","text":"Meningitis"},{"id":"D","text":"Measles"}],"images":["question-media/community/community-436-q33.jpg"],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Yellow fever. Travel to a yellow-fever-risk area requires destination-specific vaccination and mosquito-bite prevention, with entry requirements checked before travel.","sourceLocations":[{"assessment":"Midterm","batch":"436","questionNumber":33,"sourceType":"Gift"},{"assessment":"Midterm","batch":"432","questionNumber":7,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/index.html"}],"lectureOrder":1,"referenceOrder":64033},{"id":"community-mid-natural-history-of-disease-and-conce-6d4644dd","subjectId":"community","lecture":"Natural History of Disease and Concepts of Prevention and Control","assessment":"Midterm","sourceBatch":"436","sourceLabel":"Community Medicine Gift","stem":"Which level of prevention apply for the setting of policies to address behaviours of the population and environment?","options":[{"id":"A","text":"Primary prevention"},{"id":"B","text":"Tertiary prevention"},{"id":"C","text":"Primordial prevention"},{"id":"D","text":"Secondary prevention"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Primordial prevention. Primordial prevention changes upstream social and environmental conditions so risk factors do not become established in the population.","sourceLocations":[{"assessment":"Midterm","batch":"436","questionNumber":34,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/index.html"}],"lectureOrder":1,"referenceOrder":64034},{"id":"community-mid-natural-history-of-disease-and-conce-80e0bb26","subjectId":"community","lecture":"Natural History of Disease and Concepts of Prevention and Control","assessment":"Midterm","sourceBatch":"436","sourceLabel":"Community Medicine Gift","stem":"Main objective of prevention of primary prevention level?","options":[{"id":"A","text":"Prevention of complications"},{"id":"B","text":"Limit progression of disease"},{"id":"C","text":"Reduce incidence rate"},{"id":"D","text":"Early recovery"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Reduce incidence rate. Incidence counts new cases arising in an at-risk population during a stated period, so it measures risk or the rate of developing disease.","sourceLocations":[{"assessment":"Midterm","batch":"436","questionNumber":35,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/index.html"}],"lectureOrder":1,"referenceOrder":64035},{"id":"community-mid-principles-of-epidemiology-7ccd682b","subjectId":"community","lecture":"Principles of Epidemiology","assessment":"Midterm","sourceBatch":"435","sourceLabel":"Community Medicine Gift","stem":"Which of the following theories is suitable for postulating the development of ischemic heart disease?","options":[{"id":"A","text":"Germ"},{"id":"B","text":"Epidemiological triad"},{"id":"C","text":"Web of causation"},{"id":"D","text":"Epidemiological wheel"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Web of causation. The web-of-causation model suits multifactorial chronic disease because several interacting causes contribute rather than one necessary agent.","sourceLocations":[{"assessment":"Midterm","batch":"435","questionNumber":1,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Measures of Risk","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson3/section2.html"}],"lectureOrder":3,"referenceOrder":65001},{"id":"community-mid-prevention-and-control-of-infectious-c7032e62","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"435","sourceLabel":"Community Medicine Gift","stem":"Which of the following is an extrinsic risk factor for the occurrence of tuberculosis?","options":[{"id":"A","text":"High altitude"},{"id":"B","text":"Overcrowding"},{"id":"C","text":"Mycobacterium tuberculosis"},{"id":"D","text":"Poor hygiene"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Overcrowding. Extrinsic tuberculosis risks arise from the social or physical environment—such as poverty, crowding and poor access to care—rather than from host biology.","sourceLocations":[{"assessment":"Midterm","batch":"435","questionNumber":2,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":65002},{"id":"community-mid-prevention-and-control-of-infectious-8bad72ed","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"435","sourceLabel":"Community Medicine Gift","stem":"When assessing causation of malaria using epidemiological wheel theory which of the following determinants has the least effect in the occurrence of malaria?","options":[{"id":"A","text":"Social"},{"id":"B","text":"Physical"},{"id":"C","text":"Biological"},{"id":"D","text":"Genetic"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Genetic. The wheel model places the host's genetic core at the center and surrounds it with biological, physical and social environments, emphasizing multiple interacting causes.","sourceLocations":[{"assessment":"Midterm","batch":"435","questionNumber":3,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":65003},{"id":"community-mid-prevention-and-control-of-infectious-e9306611","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"435","sourceLabel":"Community Medicine Gift","stem":"Which of the following applies to the epidemiologic triad theory of disease occurrence?","options":[{"id":"A","text":"The oldest theory describing occurrence of infectious diseases"},{"id":"B","text":"Addresses the effect of agent, host and environment on disease occurrence"},{"id":"C","text":"The agent in this theory is limited to biological agents of diseases"},{"id":"D","text":"Postulates that environmental component influences only the agent"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Addresses the effect of agent, host and environment on disease occurrence. The epidemiologic triad organizes causation into agent, host and environment; changing any one can alter whether disease occurs.","sourceLocations":[{"assessment":"Midterm","batch":"435","questionNumber":4,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":65004},{"id":"community-mid-prevention-and-control-of-infectious-95cc8875","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"435","sourceLabel":"Community Medicine Gift","stem":"Presence of living infectious agent on the exterior surface of the body is the definition of which of the following?","options":[{"id":"A","text":"Infection"},{"id":"B","text":"Contamination"},{"id":"C","text":"Colonization"},{"id":"D","text":"Carrier"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Contamination. Infestation is the lodgement or development of arthropods on the body surface or in clothing; infection refers to invasion and multiplication within the host.","sourceLocations":[{"assessment":"Midterm","batch":"435","questionNumber":5,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":65005},{"id":"community-mid-disparities-in-health-dc3462f6","subjectId":"community","lecture":"Disparities in Health","assessment":"Midterm","sourceBatch":"435","sourceLabel":"Community Medicine Gift","stem":"Which of the following characteristics of a health indicator means reproducibility of indicator?","options":[{"id":"A","text":"Valid"},{"id":"B","text":"Sensitive"},{"id":"C","text":"Reliable"},{"id":"D","text":"Specific"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Reliable. Reliability is reproducibility: the indicator gives consistent results when measurement is repeated under comparable conditions.","sourceLocations":[{"assessment":"Midterm","batch":"435","questionNumber":6,"sourceType":"Gift"}],"references":[{"title":"WHO — Health inequities and their causes","url":"https://www.who.int/news-room/facts-in-pictures/detail/health-inequities-and-their-causes"}],"lectureOrder":8,"referenceOrder":65006},{"id":"community-mid-disparities-in-health-37281715","subjectId":"community","lecture":"Disparities in Health","assessment":"Midterm","sourceBatch":"435","sourceLabel":"Community Medicine Gift","stem":"Percentage of infants born weighing less than 2500 grams is an example of which of the following health indicators?","options":[{"id":"A","text":"Morbidity"},{"id":"B","text":"Nutrition"},{"id":"C","text":"Healthcare delivery"},{"id":"D","text":"Quality of life"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Nutrition. The percentage of liveborn infants below 2,500 g is a morbidity and maternal-child-health indicator reflecting fetal growth and prematurity.","sourceLocations":[{"assessment":"Midterm","batch":"435","questionNumber":7,"sourceType":"Gift"}],"references":[{"title":"WHO — Health inequities and their causes","url":"https://www.who.int/news-room/facts-in-pictures/detail/health-inequities-and-their-causes"}],"lectureOrder":8,"referenceOrder":65007},{"id":"community-mid-disparities-in-health-00e87acc","subjectId":"community","lecture":"Disparities in Health","assessment":"Midterm","sourceBatch":"435","sourceLabel":"Community Medicine Gift","stem":"Which of the following is a limitation of the crude death rate?","options":[{"id":"A","text":"Information is often limited to deaths occurring in health facilities"},{"id":"B","text":"Doesn't reflect the health status of the population"},{"id":"C","text":"Denominator doesn't reflect the actual number of the population"},{"id":"D","text":"Doesn't provide information on the cause of death"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Doesn't provide information on the cause of death. The crude death rate is all deaths during the period divided by the mid-year population, usually expressed per 1,000 population.","sourceLocations":[{"assessment":"Midterm","batch":"435","questionNumber":8,"sourceType":"Gift"}],"references":[{"title":"WHO — Health inequities and their causes","url":"https://www.who.int/news-room/facts-in-pictures/detail/health-inequities-and-their-causes"}],"lectureOrder":8,"referenceOrder":65008},{"id":"community-mid-disparities-in-health-d67c2057","subjectId":"community","lecture":"Disparities in Health","assessment":"Midterm","sourceBatch":"435","sourceLabel":"Community Medicine Gift","stem":"Following an outbreak of Mers-CoV, which of the following indicators is the most suitable to reflect the severity of the disease?","options":[{"id":"A","text":"Mortality rate"},{"id":"B","text":"Proportionate mortality rate"},{"id":"C","text":"Cause specific death rate"},{"id":"D","text":"Case fatality rate"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Case fatality rate. Case fatality is deaths among diagnosed cases divided by all cases of that disease; it describes severity rather than population risk.","sourceLocations":[{"assessment":"Midterm","batch":"435","questionNumber":9,"sourceType":"Gift"}],"references":[{"title":"WHO — Health inequities and their causes","url":"https://www.who.int/news-room/facts-in-pictures/detail/health-inequities-and-their-causes"}],"lectureOrder":8,"referenceOrder":65009},{"id":"community-mid-maternal-health-ac6798b7","subjectId":"community","lecture":"Maternal Health","assessment":"Midterm","sourceBatch":"435","sourceLabel":"Community Medicine Gift","stem":"In a community of 100 000 individuals, 1200 births and 1500 deaths were recorded. Of the deaths, 20 were attributed to maternal causes, 100 were in the first year of life of which 30 were in the first month and 50 resulted from road traffic injuries. What is the rate of neonatal deaths?","options":[{"id":"A","text":"30/100"},{"id":"B","text":"30/1500"},{"id":"C","text":"30/1200"},{"id":"D","text":"30/100 000"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C, Neonatal mortality = number of deaths within the first 28 days of life / number of live births","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is 30/1200. Neonatal mortality covers deaths during the first 28 completed days of life and is expressed per 1,000 live births.","sourceLocations":[{"assessment":"Midterm","batch":"435","questionNumber":10,"sourceType":"Gift"}],"references":[{"title":"WHO — Maternal health","url":"https://www.who.int/health-topics/maternal-health"}],"lectureOrder":11,"referenceOrder":65010},{"id":"community-mid-principles-of-epidemiology-e88a6440","subjectId":"community","lecture":"Principles of Epidemiology","assessment":"Midterm","sourceBatch":"435","sourceLabel":"Community Medicine Gift","stem":"Which of the following reflect occurrence of new cases of disease among the population at risk during a given period of time?","options":[{"id":"A","text":"Morbidity rate"},{"id":"B","text":"Prevalence rate"},{"id":"C","text":"Mortality rate"},{"id":"D","text":"Incidence rate"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Incidence rate. Incidence counts new cases arising in an at-risk population during a stated period, so it measures risk or the rate of developing disease.","sourceLocations":[{"assessment":"Midterm","batch":"435","questionNumber":11,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Measures of Risk","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson3/section2.html"}],"lectureOrder":3,"referenceOrder":65011},{"id":"community-mid-prevention-and-control-of-infectious-382e4dcc","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"435","sourceLabel":"Community Medicine Gift","stem":"What is the reason for the resurgence of tuberculosis common to developing and developed countries?","options":[{"id":"A","text":"The deterioration of living conditions"},{"id":"B","text":"The emergence of resistant strains of the bacteria"},{"id":"C","text":"Inadequate activities for detection and treatment of cases"},{"id":"D","text":"Failure to achieve universal BCG vaccination"}],"images":[],"incompleteSource":false,"sourceAnswer":["A","B"],"sourceAnswerNote":"A & B","aiAnswer":["A","B"],"aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is The deterioration of living conditions or The emergence of resistant strains of the bacteria. Developmental milestones are assessed by age and by domains such as gross motor, fine motor, language and social skills; sitting with support at six months is generally age-appropriate.","sourceLocations":[{"assessment":"Midterm","batch":"435","questionNumber":12,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":65012},{"id":"community-mid-prevention-and-control-of-infectious-da777cc1","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"435","sourceLabel":"Community Medicine Gift","stem":"In the Directly observed Therapy Short Course for the treatment of tuberculosis, which of the following combinations is included in the initial 2 months of the treatment?","options":[{"id":"A","text":"Rifampicin, Isoniazid, Ethambutol and Pyrazinamide"},{"id":"B","text":"Rifampicin, Streptomycin, Ethambutol and Pyrazinamide"},{"id":"C","text":"Streptomycin, Isoniazid, Ethambutol and Pyrazinamide"},{"id":"D","text":"Rifampicin. Isoniazid, Streptomycin and Pyrazinamide"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Rifampicin, Isoniazid, Ethambutol and Pyrazinamide. Directly observed therapy supports completion of an effective multidrug tuberculosis regimen and reduces treatment failure, relapse and acquired resistance.","sourceLocations":[{"assessment":"Midterm","batch":"435","questionNumber":13,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":65013},{"id":"community-mid-prevention-and-control-of-infectious-14eab759","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"435","sourceLabel":"Community Medicine Gift","stem":"In the treatment of cases of tuberculosis, what is the main advantage of fixed dose combination therapy?","options":[{"id":"A","text":"Reduce side effects"},{"id":"B","text":"Shorten the duration of treatment"},{"id":"C","text":"Improve patient's compliance"},{"id":"D","text":"Reduce cost of treatment"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Improve patient's compliance. Fixed-dose combination treatment simplifies dosing and reduces inadvertent monotherapy, helping adherence and limiting selection of drug resistance.","sourceLocations":[{"assessment":"Midterm","batch":"435","questionNumber":14,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":65014},{"id":"community-mid-prevention-and-control-of-infectious-b5a8ede5","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"435","sourceLabel":"Community Medicine Gift","stem":"Which of the following tuberculosis with tuberculin test measures is applicable to contact cases of 0mm?","options":[{"id":"A","text":"Perform chest radiography"},{"id":"B","text":"Start chemoprophylaxis"},{"id":"C","text":"Immunize with BCG"},{"id":"D","text":"Repeat tuberculin test within 4 weeks"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D, If a person was in contact with TB we should do a skin test: if it is negative (no reaction, 0mm) then we should repeat the test; if negative again we give vaccine but if positive we give chemoprophylaxis.","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Repeat tuberculin test within 4 weeks. Tuberculin skin-test interpretation depends on induration size and risk group; immunosuppressed contacts use a lower positive threshold and require clinical assessment.","sourceLocations":[{"assessment":"Midterm","batch":"435","questionNumber":16,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":65016},{"id":"community-mid-adolescent-and-child-health-c0ff3a2e","subjectId":"community","lecture":"Adolescent and Child Health","assessment":"Midterm","sourceBatch":"435","sourceLabel":"Community Medicine Gift","stem":"In Saudi Arabia, BCG vaccine is indicated for which of the following groups?","options":[{"id":"A","text":"Newborns"},{"id":"B","text":"Industrial workers"},{"id":"C","text":"Health care workers"},{"id":"D","text":"Contacts of active case of pulmonary tuberculosis"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Newborns. BCG is given to newborns in the Saudi schedule to reduce severe childhood tuberculosis; it is not routinely used as an occupational booster.","sourceLocations":[{"assessment":"Midterm","batch":"435","questionNumber":17,"sourceType":"Gift"}],"references":[{"title":"WHO — Adolescent health","url":"https://www.who.int/health-topics/adolescent-health"}],"lectureOrder":10,"referenceOrder":65017},{"id":"community-mid-prevention-and-control-of-infectious-25076307","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"435","sourceLabel":"Community Medicine Gift","stem":"Which of the following study designs is most appropriate to investigate an outbreak source?","options":[{"id":"A","text":"Cross-sectional"},{"id":"B","text":"Prospective cohort"},{"id":"C","text":"Randomized trial"},{"id":"D","text":"Retrospective cohort"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Retrospective cohort. A retrospective cohort is efficient when the exposed group is well defined, while a case-control study is useful when the full population at risk cannot be enumerated; the outbreak setting determines the choice.","sourceLocations":[{"assessment":"Midterm","batch":"435","questionNumber":18,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":65018},{"id":"community-mid-prevention-and-control-of-infectious-cb124417","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"435","sourceLabel":"Community Medicine Gift","stem":"An outbreak of gastroenteritis started at an elementary school in Riyadh in September. 2017 Although the investigation team was able to establish the causative organism, the source of the infection was still unknown. What is the next step the team should take?","options":[{"id":"A","text":"Communicate their findings with the community"},{"id":"B","text":"Develop hypotheses for the possible causes of the outbreak"},{"id":"C","text":"Verify and confirm the diagnosis by microscopy"},{"id":"D","text":"Isolate the cases and control"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"B","aiSuggestion":"After confirming the outbreak and describing it, the team should develop hypotheses about the unknown source; repeating diagnostic confirmation does not identify the source.","verification":"conflict","explanation":"The causative organism has already been established but the source remains unknown. The next investigative step is to develop testable hypotheses about possible exposures, so the AI answer is B rather than the recorded C.","sourceLocations":[{"assessment":"Midterm","batch":"435","questionNumber":19,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":65019},{"id":"community-mid-prevention-and-control-of-infectious-8167acd6","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"435","sourceLabel":"Community Medicine Gift","stem":"A break of Shiga toxin-producing Escherichia coli (STEC) occurred in 12 states in the USA from January to May 2017, A total of 32 cases identified, all of who reported eating the same brand of soy-butter prior to experiencing the gastrointestinal (GI) symptoms. Given that the average incubation period for STEC infection is 3-4 days what type of epidemic curve is this? \"People infected with the outbreak strains at E coli 0157 H7 by date of illness onset\"","options":[{"id":"A","text":"Point source"},{"id":"B","text":"Identifiable source"},{"id":"C","text":"Propagated source"},{"id":"D","text":"Continuous common source"}],"images":["question-media/community/community-435-q20.png"],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Propagated source. A propagated epidemic curve shows successive waves as infection spreads person to person, often separated by roughly one incubation period.","sourceLocations":[{"assessment":"Midterm","batch":"435","questionNumber":20,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":65020},{"id":"community-mid-surveillance-and-screening-7a390ad0","subjectId":"community","lecture":"Surveillance and Screening","assessment":"Midterm","sourceBatch":"435","sourceLabel":"Community Medicine Gift","stem":"Which of the following indicator is preferable in a screening test?","options":[{"id":"A","text":"Sensitivity"},{"id":"B","text":"Specificity"},{"id":"C","text":"Predictive value"},{"id":"D","text":"Reliability"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D - An attribute of an ideal screening test is its repeatability (BOOK)","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Reliability. Secondary prevention detects disease early in apparently healthy people so timely treatment can reduce progression or complications.","sourceLocations":[{"assessment":"Midterm","batch":"435","questionNumber":21,"sourceType":"Gift"}],"references":[{"title":"WHO — Screening programmes: a short guide","url":"https://www.who.int/publications/i/item/9789289054782"}],"lectureOrder":5,"referenceOrder":65021},{"id":"community-mid-surveillance-and-screening-e4cb4ef5","subjectId":"community","lecture":"Surveillance and Screening","assessment":"Midterm","sourceBatch":"435","sourceLabel":"Community Medicine Gift","stem":"PSA screening test for prostate cancer is tested against prostate biopsy, The PSA test was able to detect 22 cases among 45 subjects who were confirmed positive by the biopsy. Among 64 who were identified as free of prostate cancer by the biopsy, the PSA test reported 4 cases affected with prostate cancer. What is the sensitivity of the PSA test?","options":[{"id":"A","text":"49%"},{"id":"B","text":"51%"},{"id":"C","text":"85%"},{"id":"D","text":"72%"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A - 22/45 * 100 = 48.8 = 49%","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is 49%. Sensitivity is the proportion of people with the condition who test positive: TP/(TP+FN). A highly sensitive test therefore minimizes false negatives.","sourceLocations":[{"assessment":"Midterm","batch":"435","questionNumber":22,"sourceType":"Gift"}],"references":[{"title":"WHO — Screening programmes: a short guide","url":"https://www.who.int/publications/i/item/9789289054782"}],"lectureOrder":5,"referenceOrder":65022},{"id":"community-mid-surveillance-and-screening-1d0a2f1b","subjectId":"community","lecture":"Surveillance and Screening","assessment":"Midterm","sourceBatch":"435","sourceLabel":"Community Medicine Gift","stem":"The following is a cross tabulation of 100 000 women screened for breast cancer using breast mammogram followed by pathological examination of biopsy specimen for confirmation. Table: Breast Mammogram | Biopsy results | Biopsy results | Total / Breast Mammogram | Present | Absent | Total / Positive | 1500 | 200 | 1700 / Negative | 2500 | 95800 | 98300 / Total | 4000 | 96000 | 100000 What is the sensitivity of the screening test?","options":[{"id":"A","text":"2500/98300"},{"id":"B","text":"200/96000"},{"id":"C","text":"1500/4000"},{"id":"D","text":"1500/1700"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is 1500/4000. Sensitivity is the proportion of people with the condition who test positive: TP/(TP+FN). A highly sensitive test therefore minimizes false negatives.","sourceLocations":[{"assessment":"Midterm","batch":"435","questionNumber":23,"sourceType":"Gift"}],"references":[{"title":"WHO — Screening programmes: a short guide","url":"https://www.who.int/publications/i/item/9789289054782"}],"lectureOrder":5,"referenceOrder":65023},{"id":"community-mid-surveillance-and-screening-f5800afb","subjectId":"community","lecture":"Surveillance and Screening","assessment":"Midterm","sourceBatch":"435","sourceLabel":"Community Medicine Gift","stem":"Which of the following represents an error of a screening test?","options":[{"id":"A","text":"Sensitivity"},{"id":"B","text":"Specificity"},{"id":"C","text":"False results"},{"id":"D","text":"Predictive value"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is False results. Secondary prevention detects disease early in apparently healthy people so timely treatment can reduce progression or complications.","sourceLocations":[{"assessment":"Midterm","batch":"435","questionNumber":24,"sourceType":"Gift"}],"references":[{"title":"WHO — Screening programmes: a short guide","url":"https://www.who.int/publications/i/item/9789289054782"}],"lectureOrder":5,"referenceOrder":65024},{"id":"community-mid-global-demography-concepts-and-popul-0dd4a9cb","subjectId":"community","lecture":"Global Demography Concepts and Population Pyramid","assessment":"Midterm","sourceBatch":"435","sourceLabel":"Community Medicine Gift","stem":"Which of the following applies to the De jure census?","options":[{"id":"A","text":"Easy in conducting"},{"id":"B","text":"Requires few resources"},{"id":"C","text":"Miss people in transit"},{"id":"D","text":"Provides a factual figure"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Provides a factual figure. A de jure census counts people at their usual legal residence, rather than where they happen to be on census day.","sourceLocations":[{"assessment":"Midterm","batch":"435","questionNumber":25,"sourceType":"Gift"}],"references":[{"title":"United Nations World Population Prospects","url":"https://www.un.org/development/desa/pd/content/world-population-prospects-2024"}],"lectureOrder":2,"referenceOrder":65025},{"id":"community-mid-global-demography-concepts-and-popul-bfc5c50c","subjectId":"community","lecture":"Global Demography Concepts and Population Pyramid","assessment":"Midterm","sourceBatch":"435","sourceLabel":"Community Medicine Gift","stem":"Which of the following indicators predicts the fertility of the next generation?","options":[{"id":"A","text":"Age specific fertility rate"},{"id":"B","text":"Total fertility rate"},{"id":"C","text":"General fertility rate"},{"id":"D","text":"Gross reproduction rate"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Gross reproduction rate. Reliability is reproducibility: the indicator gives consistent results when measurement is repeated under comparable conditions.","sourceLocations":[{"assessment":"Midterm","batch":"435","questionNumber":26,"sourceType":"Gift"}],"references":[{"title":"United Nations World Population Prospects","url":"https://www.un.org/development/desa/pd/content/world-population-prospects-2024"}],"lectureOrder":2,"referenceOrder":65026},{"id":"community-mid-global-demography-concepts-and-popul-f0946b7c","subjectId":"community","lecture":"Global Demography Concepts and Population Pyramid","assessment":"Midterm","sourceBatch":"435","sourceLabel":"Community Medicine Gift","stem":"The total population of a country is 365797 number of individuals below 15 year is 43211 number of individuals between 15 and 60 cars is 250332 and number of individuals above 60 years is 72254.What is the total dependency ratio?","options":[{"id":"A","text":"21%"},{"id":"B","text":"46%"},{"id":"C","text":"17%"},{"id":"D","text":"29%"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B, (43211 +72254) / 250332 = 46%","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is 46%. The dependency ratio compares younger and older dependants with the working-age population, usually expressed per 100 working-age people.","sourceLocations":[{"assessment":"Midterm","batch":"435","questionNumber":27,"sourceType":"Gift"}],"references":[{"title":"United Nations World Population Prospects","url":"https://www.un.org/development/desa/pd/content/world-population-prospects-2024"}],"lectureOrder":2,"referenceOrder":65027},{"id":"community-mid-global-demography-concepts-and-popul-d4c8f63f","subjectId":"community","lecture":"Global Demography Concepts and Population Pyramid","assessment":"Midterm","sourceBatch":"435","sourceLabel":"Community Medicine Gift","stem":"Which of the following is a demographic force?","options":[{"id":"A","text":"Natality"},{"id":"B","text":"Size"},{"id":"C","text":"Composition"},{"id":"D","text":"Distribution"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Natality. Natality is births as a force of population change; mortality and migration are the other major demographic forces.","sourceLocations":[{"assessment":"Midterm","batch":"435","questionNumber":28,"sourceType":"Gift"}],"references":[{"title":"United Nations World Population Prospects","url":"https://www.un.org/development/desa/pd/content/world-population-prospects-2024"}],"lectureOrder":2,"referenceOrder":65028},{"id":"community-mid-global-demography-concepts-and-popul-f369bf1a","subjectId":"community","lecture":"Global Demography Concepts and Population Pyramid","assessment":"Midterm","sourceBatch":"435","sourceLabel":"Community Medicine Gift","stem":"What is the demographic stage of a country showing a high birth rate and a rapidly declining death rate?","options":[{"id":"A","text":"Low stationary"},{"id":"B","text":"High stationary"},{"id":"C","text":"Early expanding"},{"id":"D","text":"Late expanding"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Early expanding. The early-expanding stage combines a high birth rate with a rapidly falling death rate, producing rapid population growth.","sourceLocations":[{"assessment":"Midterm","batch":"435","questionNumber":29,"sourceType":"Gift"}],"references":[{"title":"United Nations World Population Prospects","url":"https://www.un.org/development/desa/pd/content/world-population-prospects-2024"}],"lectureOrder":2,"referenceOrder":65029},{"id":"community-mid-global-demography-concepts-and-popul-3f62c246","subjectId":"community","lecture":"Global Demography Concepts and Population Pyramid","assessment":"Midterm","sourceBatch":"435","sourceLabel":"Community Medicine Gift","stem":"What is the estimated population of Saudi Arabia in the year 2051 assuming an annual growth rate of 2% and a population of 27 million as of the year 2016?","options":[{"id":"A","text":"30 million"},{"id":"B","text":"50 million"},{"id":"C","text":"54 million"},{"id":"D","text":"45 million"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C (with a growth rate of 2% the population will double in 35 years, i.e from 2016 to 2051, so 27 * 2 = 54)","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is 54 million. Using the rule of 70, a 2% annual growth rate gives an approximate doubling time of 35 years; 27 million therefore becomes about 54 million by 2051.","sourceLocations":[{"assessment":"Midterm","batch":"435","questionNumber":30,"sourceType":"Gift"}],"references":[{"title":"United Nations World Population Prospects","url":"https://www.un.org/development/desa/pd/content/world-population-prospects-2024"}],"lectureOrder":2,"referenceOrder":65030},{"id":"community-mid-surveillance-and-screening-b6abf169","subjectId":"community","lecture":"Surveillance and Screening","assessment":"Midterm","sourceBatch":"435","sourceLabel":"Community Medicine Gift","stem":"\"Systematic and continuous collection of information about the occurrence of disease and other health phenomena\" is the definition for?","options":[{"id":"A","text":"Case finding"},{"id":"B","text":"Public health surveillance"},{"id":"C","text":"Screening"},{"id":"D","text":"Outbreak investigation"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Public health surveillance. This is the definition of public-health surveillance: ongoing systematic collection, analysis, interpretation and dissemination of data for action.","sourceLocations":[{"assessment":"Midterm","batch":"435","questionNumber":31,"sourceType":"Gift"}],"references":[{"title":"WHO — Screening programmes: a short guide","url":"https://www.who.int/publications/i/item/9789289054782"}],"lectureOrder":5,"referenceOrder":65031},{"id":"community-mid-surveillance-and-screening-b2c3ae04","subjectId":"community","lecture":"Surveillance and Screening","assessment":"Midterm","sourceBatch":"435","sourceLabel":"Community Medicine Gift","stem":"What is the most common type of surveillance system?","options":[{"id":"A","text":"Active"},{"id":"B","text":"Sentinel"},{"id":"C","text":"Passive"},{"id":"D","text":"National"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Passive. Passive surveillance relies on routine reports sent by healthcare providers or laboratories; it is inexpensive but vulnerable to under-reporting.","sourceLocations":[{"assessment":"Midterm","batch":"435","questionNumber":32,"sourceType":"Gift"}],"references":[{"title":"WHO — Screening programmes: a short guide","url":"https://www.who.int/publications/i/item/9789289054782"}],"lectureOrder":5,"referenceOrder":65032},{"id":"community-mid-prevention-and-control-of-infectious-6d3c2030","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"435","sourceLabel":"Community Medicine Gift","stem":"Which one of the following is the best way to control malaria disease?","options":[{"id":"A","text":"Administering vaccine to newborns"},{"id":"B","text":"Using personal protective equipment"},{"id":"C","text":"Vector control by spraying insecticides"},{"id":"D","text":"Preventing infected people from work for 14 days after developing fever"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Vector control by spraying insecticides. Malaria prevention combines vector control—especially insecticide-treated nets and indoor residual spraying—with chemoprevention and prompt diagnosis where indicated.","sourceLocations":[{"assessment":"Midterm","batch":"435","questionNumber":33,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":65033},{"id":"community-mid-prevention-and-control-of-infectious-8895a070","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"435","sourceLabel":"Community Medicine Gift","stem":"In Saudi Arabia, Malaria is most commonly found in which region?","options":[{"id":"A","text":"Central"},{"id":"B","text":"Southern"},{"id":"C","text":"Eastern"},{"id":"D","text":"Northern"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Southern. Local malaria risk is concentrated where competent vectors and transmission conditions persist; the keyed region reflects the course's Saudi epidemiology.","sourceLocations":[{"assessment":"Midterm","batch":"435","questionNumber":34,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":65034},{"id":"community-mid-prevention-and-control-of-infectious-b4134a02","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"435","sourceLabel":"Community Medicine Gift","stem":"How can HBV be transmitted?","options":[{"id":"A","text":"Direct contact with infected body fluids"},{"id":"B","text":"Vector borne by mosquito bites"},{"id":"C","text":"Airborne mode"},{"id":"D","text":"Ingestion of raw fish"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Direct contact with infected body fluids. Direct transmission occurs through immediate physical contact with an infected person, body fluid, soil or another source without an intervening vehicle or vector.","sourceLocations":[{"assessment":"Midterm","batch":"435","questionNumber":35,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":65035},{"id":"community-mid-prevention-and-control-of-infectious-f4b8aced","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"435","sourceLabel":"Community Medicine Gift","stem":"A nurse in Uganda had been in direct unprotected contact with a case of confirmed Ebola infection. For how long should he be observed and his health be checked?","options":[{"id":"A","text":"4 days"},{"id":"B","text":"7days"},{"id":"C","text":"14 days"},{"id":"D","text":"21 days"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is 21 days. Ebola control in healthcare relies on rapid isolation, appropriate personal protective equipment, safe specimen and waste handling, and active contact monitoring for the incubation period.","sourceLocations":[{"assessment":"Midterm","batch":"435","questionNumber":36,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":65036},{"id":"community-mid-prevention-and-control-of-infectious-54134690","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"435","sourceLabel":"Community Medicine Gift","stem":"What is the most effective method for prevention of sexual transmission in the Mediterranean Region?","options":[{"id":"A","text":"Mutual fidelity and condom use"},{"id":"B","text":"Adherence to religious teachings and health education"},{"id":"C","text":"Screening measures in blood banks"},{"id":"D","text":"Genetic and premarital counselling and services"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Adherence to religious teachings and health education. The recorded answer follows the course's culturally framed prevention hierarchy; medically, comprehensive HIV prevention combines effective barrier protection, testing, treatment and risk-reduction counselling.","sourceLocations":[{"assessment":"Midterm","batch":"435","questionNumber":37,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":65037},{"id":"community-mid-prevention-and-control-of-infectious-6b7d5481","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"435","sourceLabel":"Community Medicine Gift","stem":"Which of the following will be reduced by health education efforts against HIV AIDs?","options":[{"id":"A","text":"Incidence"},{"id":"B","text":"Mortality"},{"id":"C","text":"Complications"},{"id":"D","text":"Severity"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Incidence. Incidence counts new cases arising in an at-risk population during a stated period, so it measures risk or the rate of developing disease.","sourceLocations":[{"assessment":"Midterm","batch":"435","questionNumber":38,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":65038},{"id":"community-mid-prevention-and-control-of-infectious-0d798648","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"435","sourceLabel":"Community Medicine Gift","stem":"In addition tetravalent (ACYW 135) vaccine against meningitis ten days before arrival to Saudi Arabia for Hajj. Which of the following categories should be administered with chemoprophylaxis at the port of entry?","options":[{"id":"A","text":"Visitors who have not taken the vaccine"},{"id":"B","text":"Visitors from countries in the African meningitis belt"},{"id":"C","text":"People arriving from South America"},{"id":"D","text":"Pregnant women and children"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Visitors from countries in the African meningitis belt. Quadrivalent meningococcal vaccination before Hajj reduces individual risk and transmission in crowded settings; validity requirements follow current Saudi rules.","sourceLocations":[{"assessment":"Midterm","batch":"435","questionNumber":39,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":65039},{"id":"community-mid-prevention-and-control-of-infectious-7f136ce6","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"435","sourceLabel":"Community Medicine Gift","stem":"Transmission of hepatitis A virus through contaminated eating utensils is an example of which type of transmission?","options":[{"id":"A","text":"Direct contact"},{"id":"B","text":"Airborne"},{"id":"C","text":"Vector-borne"},{"id":"D","text":"Vehicle-borne"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Vehicle-borne. Vehicle-borne transmission occurs through a contaminated non-living medium such as food, water, blood or a fomite.","sourceLocations":[{"assessment":"Midterm","batch":"435","questionNumber":40,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":65040},{"id":"community-mid-principles-of-epidemiology-9585f842","subjectId":"community","lecture":"Principles of Epidemiology","assessment":"Midterm","sourceBatch":"434","sourceLabel":"Community Medicine Gift","stem":"From the above table, Identify the food item with highest relative risk of being the source of infection? Table: Ate the food item | Ate the food item | Ate the food item | Ate the food item | | Did not eat the food item | Did not eat the food item | Did not eat the food item / Food Item | No. People | No. ill | Attack Rate | | No. People | No. ill | Attack Rate / Beef Burritos | 276 | 28 | 10.1 | | 266 | 27 | 10.2 / Cheese Burger | 218 | 21 | 9.6 | | 131 | 14 | 10.7 / Tossed Salad | 105 | 49 | 46.7 | | 297 | 15 | 5.1 / Baked Potato | 139 | 11 | 7.9 | | 213 | 31 | 14.6 / Fruit Cocktail | 88 | 48 | 54.5 | | 279 | 25 | 9.0 / Ice Cream | 175 | 18 | 10.3 | | 203 | 49 | 24.1","options":[{"id":"A","text":"Cheese Burger"},{"id":"B","text":"Fruit Cocktail"},{"id":"C","text":"Ice Cream"},{"id":"D","text":"Tossed Salad RR of ice cream = 0.42, RR of tossed salad= 9.1, RR of fruit cocktail= 6.05 ...etc"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D, By calculating the relative risk (risk ratio)= AR in exposed / AR in non-exposed.","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Tossed Salad RR of ice cream = 0.42, RR of tossed salad= 9.1, RR of fruit cocktail= 6.05 ...etc. For each food, compare the attack rate among those who ate it with the attack rate among those who did not. The highest risk ratio points to the most likely vehicle; the lowest argues against it.","sourceLocations":[{"assessment":"Midterm","batch":"434","questionNumber":1,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Measures of Risk","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson3/section2.html"}],"lectureOrder":3,"referenceOrder":66001},{"id":"community-mid-principles-of-epidemiology-9f7588a8","subjectId":"community","lecture":"Principles of Epidemiology","assessment":"Midterm","sourceBatch":"434","sourceLabel":"Community Medicine Gift","stem":"From the above table, Which food item that seem to be the least possible source to be contaminated?","options":[{"id":"A","text":"Beef Burritos"},{"id":"B","text":"Ice Cream"},{"id":"C","text":"Baked Potato"},{"id":"D","text":"Cheese Burger RR of ice cream = 0.42, RR of tossed salad= 9.1, RR of fruit cocktail= 6.05 ...etc"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B, By calculating the relative risk (risk ratio)= AR in exposed/ AR in non-exposed.","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Ice Cream. For each food, compare the attack rate among those who ate it with the attack rate among those who did not. The highest risk ratio points to the most likely vehicle; the lowest argues against it.","sourceLocations":[{"assessment":"Midterm","batch":"434","questionNumber":2,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Measures of Risk","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson3/section2.html"}],"lectureOrder":3,"referenceOrder":66002},{"id":"community-mid-principles-of-epidemiology-7cc40cf6","subjectId":"community","lecture":"Principles of Epidemiology","assessment":"Midterm","sourceBatch":"434","sourceLabel":"Community Medicine Gift","stem":"Clinical diagnosis but there is no lab confirmation, what is it called?","options":[{"id":"A","text":"Possible"},{"id":"B","text":"Probable"},{"id":"C","text":"Confirmer"},{"id":"D","text":"Inevitable"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B - If positive in lab so will be confirmed","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Probable. Outbreak case classifications combine clinical, epidemiologic and laboratory criteria. A clinically compatible case without confirmatory laboratory evidence is not a confirmed case.","sourceLocations":[{"assessment":"Midterm","batch":"434","questionNumber":4,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Measures of Risk","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson3/section2.html"}],"lectureOrder":3,"referenceOrder":66004},{"id":"community-mid-prevention-and-control-of-infectious-703a1487","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"434","sourceLabel":"Community Medicine Gift","stem":"After an outbreak, the shape of the curve contains a multiple peaks over a 3 months, what is the pattern?","options":[{"id":"A","text":"Point source."},{"id":"B","text":"Propagation source."},{"id":"C","text":"Common intermittent source."},{"id":"D","text":"Common continuous source."}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B - One peak → point source, multiple peaks → propagated or (person to person)","aiAnswer":"B","aiSuggestion":"Successive peaks separated by roughly an incubation period suggest propagated person-to-person spread.","verification":"supported","explanation":"A propagated outbreak produces successive waves or peaks as infection passes from person to person, often separated by an incubation period. A single sharp peak is more typical of a point source.","sourceLocations":[{"assessment":"Midterm","batch":"434","questionNumber":5,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":66005},{"id":"community-mid-prevention-and-control-of-infectious-75134220","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"434","sourceLabel":"Community Medicine Gift","stem":"Influenza Virus has low immunogenicity. The immunogenicity of an infectious agent will be measured by which of the following?","options":[{"id":"A","text":"Case fatality rate"},{"id":"B","text":"Second attack frequency"},{"id":"C","text":"Clinical to subclinical ratio"},{"id":"D","text":"Secondary attack rate with contacts"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":null,"aiSuggestion":"Immunogenicity is assessed by the immune response, such as seroconversion or antibody titre. None of the listed epidemiologic measures states that directly.","verification":"conflict","explanation":"Immunogenicity means the ability to induce an immune response and is evaluated with measures such as seroconversion or antibody titre. The listed attack-rate and severity measures do not directly measure immunogenicity, so no option is graded by the AI.","sourceLocations":[{"assessment":"Midterm","batch":"434","questionNumber":9,"sourceType":"Gift"},{"assessment":"Midterm","batch":"433","questionNumber":12,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":66009},{"id":"community-mid-surveillance-and-screening-ec342960","subjectId":"community","lecture":"Surveillance and Screening","assessment":"Midterm","sourceBatch":"434","sourceLabel":"Community Medicine Gift","stem":"A collaboration between the WHO and Ministry of Health in KSA to start a surveillance program about MERS Cov at Alhajj. What is the purpose of this collaboration?","options":[{"id":"A","text":"To detect outbreaks"},{"id":"B","text":"To identify registration method"},{"id":"C","text":"To monitor cause­ ‐ specific death rate"},{"id":"D","text":"To evaluate health practice"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is To detect outbreaks. Timely surveillance detects unusual increases above the expected baseline so investigation and control can begin early.","sourceLocations":[{"assessment":"Midterm","batch":"434","questionNumber":10,"sourceType":"Gift"}],"references":[{"title":"WHO — Screening programmes: a short guide","url":"https://www.who.int/publications/i/item/9789289054782"}],"lectureOrder":5,"referenceOrder":66010},{"id":"community-mid-adolescent-and-child-health-4c048cc3","subjectId":"community","lecture":"Adolescent and Child Health","assessment":"Midterm","sourceBatch":"434","sourceLabel":"Community Medicine Gift","stem":"According to the compulsory vaccination schedule in Saudi Arabia, what is the time of the first dose of Hepatitis B vaccine given to infants?","options":[{"id":"A","text":"At birth"},{"id":"B","text":"Second month"},{"id":"C","text":"9th month"},{"id":"D","text":"12th month"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is At birth. The first hepatitis B dose is scheduled at birth to reduce perinatal and early-childhood transmission; subsequent doses complete the primary series.","sourceLocations":[{"assessment":"Midterm","batch":"434","questionNumber":12,"sourceType":"Gift"},{"assessment":"Midterm","batch":"433","questionNumber":8,"sourceType":"Gift"}],"references":[{"title":"WHO — Adolescent health","url":"https://www.who.int/health-topics/adolescent-health"}],"lectureOrder":10,"referenceOrder":66012},{"id":"community-mid-prevention-and-control-of-infectious-30f49e8a","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"434","sourceLabel":"Community Medicine Gift","stem":"What type of immunity a child would have after a measles infection?","options":[{"id":"A","text":"Active natural immunity"},{"id":"B","text":"Active acquired immunity"},{"id":"C","text":"Passive natural immunity"},{"id":"D","text":"Passive acquired immunity"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Active natural immunity. Recovery from natural measles infection produces naturally acquired active immunity because the person's own immune system responds to the infection.","sourceLocations":[{"assessment":"Midterm","batch":"434","questionNumber":13,"sourceType":"Gift"},{"assessment":"Midterm","batch":"433","questionNumber":16,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":66013},{"id":"community-mid-prevention-and-control-of-infectious-1fe5d48a","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"434","sourceLabel":"Community Medicine Gift","stem":"What is the scientific name for a disease or an infectious agent that is constantly present in a population or a geographic area?","options":[{"id":"A","text":"Outbreak"},{"id":"B","text":"Endemic"},{"id":"C","text":"Pandemic"},{"id":"D","text":"Epidemic"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Endemic. Endemic means the constant or usual presence of a disease or agent in a defined geographic area or population.","sourceLocations":[{"assessment":"Midterm","batch":"434","questionNumber":14,"sourceType":"Gift"},{"assessment":"Midterm","batch":"433","questionNumber":17,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":66014},{"id":"community-mid-surveillance-and-screening-5271f205","subjectId":"community","lecture":"Surveillance and Screening","assessment":"Midterm","sourceBatch":"434","sourceLabel":"Community Medicine Gift","stem":"A New Screening test for coronaVirus Infection (MERS­CoV) is tested against PCR analysis. The new screening test was able to detect 22 case among 45 subjects who were confirmed positive by PCR analysis. Among 64 who were identified as free of MERS­CoV By PCR, the new test reported 4 cases affected with MERS­CoV. Which one is the sensitivity of the new test?","options":[{"id":"A","text":"49%"},{"id":"B","text":"51%"},{"id":"C","text":"85%"},{"id":"D","text":"72% 22\\45*100 Table: New test | PCR | PCR / | +ve | -ve / +ve | 22 | 4 / -ve | | / Total | 45 | 64"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is 49%. A suspected MERS case with camel exposure requires prompt notification through the designated national surveillance system and appropriate infection-control precautions.","sourceLocations":[{"assessment":"Midterm","batch":"434","questionNumber":15,"sourceType":"Gift"}],"references":[{"title":"WHO — Screening programmes: a short guide","url":"https://www.who.int/publications/i/item/9789289054782"}],"lectureOrder":5,"referenceOrder":66015},{"id":"community-mid-prevention-and-control-of-infectious-526af010","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"434","sourceLabel":"Community Medicine Gift","stem":"Which one of the following is a preventive measure for hepatitis A?","options":[{"id":"A","text":"Restrict needle use"},{"id":"B","text":"Universal vaccine"},{"id":"C","text":"Prohibit blood donation"},{"id":"D","text":"All the above"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Universal vaccine. Hepatitis A prevention combines vaccination with safe water, sanitation, food hygiene and hand hygiene; blood-borne precautions address other hepatitis viruses.","sourceLocations":[{"assessment":"Midterm","batch":"434","questionNumber":16,"sourceType":"Gift"},{"assessment":"Midterm","batch":"433","questionNumber":20,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":66016},{"id":"community-mid-natural-history-of-disease-and-conce-ea5264aa","subjectId":"community","lecture":"Natural History of Disease and Concepts of Prevention and Control","assessment":"Midterm","sourceBatch":"434","sourceLabel":"Community Medicine Gift","stem":"What is the main objective of preventing disease at the primary prevention time?","options":[{"id":"A","text":"Prevent complications"},{"id":"B","text":"Reduction of mortality"},{"id":"C","text":"Early recovery from disease"},{"id":"D","text":"Reduce the Incidence of the disease"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Reduce the Incidence of the disease. Incidence counts new cases arising in an at-risk population during a stated period, so it measures risk or the rate of developing disease.","sourceLocations":[{"assessment":"Midterm","batch":"434","questionNumber":17,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/index.html"}],"lectureOrder":1,"referenceOrder":66017},{"id":"community-mid-global-demography-concepts-and-popul-a7273b05","subjectId":"community","lecture":"Global Demography Concepts and Population Pyramid","assessment":"Midterm","sourceBatch":"434","sourceLabel":"Community Medicine Gift","stem":"What does a wide base of a population pyramid indicate?","options":[{"id":"A","text":"High mortality rates"},{"id":"B","text":"High Birth rate"},{"id":"C","text":"High net migration"},{"id":"D","text":"High proportion of females"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is High Birth rate. A population pyramid displays age and sex structure; a broad base suggests high fertility and a younger population, while a narrower base and larger older groups suggest ageing.","sourceLocations":[{"assessment":"Midterm","batch":"434","questionNumber":18,"sourceType":"Gift"}],"references":[{"title":"United Nations World Population Prospects","url":"https://www.un.org/development/desa/pd/content/world-population-prospects-2024"}],"lectureOrder":2,"referenceOrder":66018},{"id":"community-mid-surveillance-and-screening-385308ac","subjectId":"community","lecture":"Surveillance and Screening","assessment":"Midterm","sourceBatch":"434","sourceLabel":"Community Medicine Gift","stem":"New screening test was applied and it showed the same result when repeated to the same subjects but it correlates poorly with the confirmatory test. Which one of the following is applied to the test?","options":[{"id":"A","text":"Accurate"},{"id":"B","text":"Reliable"},{"id":"C","text":"Sensitive"},{"id":"D","text":"Specific"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Reliable. Secondary prevention detects disease early in apparently healthy people so timely treatment can reduce progression or complications.","sourceLocations":[{"assessment":"Midterm","batch":"434","questionNumber":19,"sourceType":"Gift"},{"assessment":"Midterm","batch":"432","questionNumber":30,"sourceType":"Gift"}],"references":[{"title":"WHO — Screening programmes: a short guide","url":"https://www.who.int/publications/i/item/9789289054782"}],"lectureOrder":5,"referenceOrder":66019},{"id":"community-mid-prevention-and-control-of-infectious-ee35349c","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"434","sourceLabel":"Community Medicine Gift","stem":"Influenza H1N1 Is an example of:","options":[{"id":"A","text":"Epidemic"},{"id":"B","text":"Endemic"},{"id":"C","text":"Outbreak"},{"id":"D","text":"Pandemic"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Pandemic. A pandemic is an epidemic with sustained spread across multiple countries or continents, affecting a large number of people.","sourceLocations":[{"assessment":"Midterm","batch":"434","questionNumber":20,"sourceType":"Gift"},{"assessment":"Midterm","batch":"433","questionNumber":31,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":66020},{"id":"community-mid-prevention-and-control-of-infectious-f18b3f21","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"434","sourceLabel":"Community Medicine Gift","stem":"What determines virulence of organism?","options":[{"id":"A","text":"Case fatality rate"},{"id":"B","text":"Age -specific death rate"},{"id":"C","text":"Cause -specific death rate"},{"id":"D","text":"Life expectancy"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Case fatality rate. Case fatality is deaths among diagnosed cases divided by all cases of that disease; it describes severity rather than population risk.","sourceLocations":[{"assessment":"Midterm","batch":"434","questionNumber":21,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":66021},{"id":"community-mid-prevention-and-control-of-infectious-06a9c6c4","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"434","sourceLabel":"Community Medicine Gift","stem":"Reservoir means:","options":[{"id":"A","text":"The habitat in which the host benefit from the invading agent"},{"id":"B","text":"The place where infectious agents are not able to cause disease"},{"id":"C","text":"The place where the organism grows and before entry to the host"},{"id":"D","text":"The habitat in which an infectious agent normally lives, grows, and multiplies"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is The habitat in which an infectious agent normally lives, grows, and multiplies. A reservoir is the habitat in which an infectious agent normally lives, grows and multiplies; it is not always the same as the immediate source of exposure.","sourceLocations":[{"assessment":"Midterm","batch":"434","questionNumber":22,"sourceType":"Gift"},{"assessment":"Midterm","batch":"433","questionNumber":29,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":66022},{"id":"community-mid-prevention-and-control-of-infectious-21dc1f38","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"434","sourceLabel":"Community Medicine Gift","stem":"Which one of the following is a mode of transmission of Ebola virus?","options":[{"id":"A","text":"Airborne"},{"id":"B","text":"Direct contact"},{"id":"C","text":"Food borne"},{"id":"D","text":"Vector borne"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Direct contact. Direct transmission occurs through immediate physical contact with an infected person, body fluid, soil or another source without an intervening vehicle or vector.","sourceLocations":[{"assessment":"Midterm","batch":"434","questionNumber":23,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":66023},{"id":"community-mid-prevention-and-control-of-infectious-dae4b324","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"434","sourceLabel":"Community Medicine Gift","stem":"What is the main natural reservoir of Ebola virus disease?","options":[{"id":"A","text":"Bats"},{"id":"B","text":"Rodents"},{"id":"C","text":"Spiders"},{"id":"D","text":"Ticks"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Bats. A reservoir is the habitat in which an infectious agent normally lives, grows and multiplies; it is not always the same as the immediate source of exposure.","sourceLocations":[{"assessment":"Midterm","batch":"434","questionNumber":24,"sourceType":"Gift"},{"assessment":"Midterm","batch":"432","questionNumber":3,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":66024},{"id":"community-mid-principles-of-epidemiology-f9ffca71","subjectId":"community","lecture":"Principles of Epidemiology","assessment":"Midterm","sourceBatch":"434","sourceLabel":"Community Medicine Gift","stem":"The core of the epidemiological wheel is?","options":[{"id":"A","text":"Genetic Factors"},{"id":"B","text":"Physical environment"},{"id":"C","text":"The host"},{"id":"D","text":"Biological environment"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Genetic Factors. The wheel model places the host's genetic core at the center and surrounds it with biological, physical and social environments, emphasizing multiple interacting causes.","sourceLocations":[{"assessment":"Midterm","batch":"434","questionNumber":25,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Measures of Risk","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson3/section2.html"}],"lectureOrder":3,"referenceOrder":66025},{"id":"community-mid-prevention-and-control-of-infectious-5f2bf58e","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"434","sourceLabel":"Community Medicine Gift","stem":"Brucellosis is a disease that has always been in the Kingdom of Saudi Arabia with the same prevalence each year. Which of the following describes the pattern of occurrence?","options":[{"id":"A","text":"Pandemic"},{"id":"B","text":"Endemic"},{"id":"C","text":"Epidemic"},{"id":"D","text":"Outbreak"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Endemic. Prevalence includes all existing cases at a point or during a period. It is influenced by both incidence and disease duration.","sourceLocations":[{"assessment":"Midterm","batch":"434","questionNumber":26,"sourceType":"Gift"},{"assessment":"Midterm","batch":"432","questionNumber":8,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":66026},{"id":"community-mid-prevention-and-control-of-infectious-b997592a","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"434","sourceLabel":"Community Medicine Gift","stem":"Many countries try to achieve high vaccination coverage against poliomyelitis infection as part of worldwide efforts to reduce its incidence to zero level. Which of the following describes these efforts?","options":[{"id":"A","text":"Elimination"},{"id":"B","text":"Eradication"},{"id":"C","text":"Control"},{"id":"D","text":"Prevention"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Elimination. Incidence counts new cases arising in an at-risk population during a stated period, so it measures risk or the rate of developing disease.","sourceLocations":[{"assessment":"Midterm","batch":"434","questionNumber":27,"sourceType":"Gift"},{"assessment":"Midterm","batch":"432","questionNumber":9,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":66027},{"id":"community-mid-prevention-and-control-of-infectious-e4b58eed","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"434","sourceLabel":"Community Medicine Gift","stem":"Which of the following public health measures is applied to susceptible host?","options":[{"id":"A","text":"Chemoprophylaxis"},{"id":"B","text":"Exclusion from work"},{"id":"C","text":"Isolation"},{"id":"D","text":"Reporting"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Chemoprophylaxis. Measures directed at susceptible hosts include immunization, chemoprophylaxis and improving host resistance; they do not remove the reservoir or route itself.","sourceLocations":[{"assessment":"Midterm","batch":"434","questionNumber":28,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":66028},{"id":"community-mid-prevention-and-control-of-infectious-909a91ed","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"434","sourceLabel":"Community Medicine Gift","stem":"During last week, a primary school student had measles and had sick leave from school. For how long she should be kept away from school?","options":[{"id":"A","text":"The longest incubation period"},{"id":"B","text":"The period of communicability"},{"id":"C","text":"Until she fully recovers"},{"id":"D","text":"The extrinsic incubation period"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is The period of communicability. The period of communicability is the interval during which an infected person can transmit the agent, which determines the necessary exclusion or isolation period.","sourceLocations":[{"assessment":"Midterm","batch":"434","questionNumber":29,"sourceType":"Gift"},{"assessment":"Midterm","batch":"432","questionNumber":13,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":66029},{"id":"community-mid-surveillance-and-screening-c524189f","subjectId":"community","lecture":"Surveillance and Screening","assessment":"Midterm","sourceBatch":"434","sourceLabel":"Community Medicine Gift","stem":"Which one of the following is most applicable for screening of health problems?","options":[{"id":"A","text":"It is from the subjects' request."},{"id":"B","text":"It is basis for treatment"},{"id":"C","text":"Because there is Asymptomatic"},{"id":"D","text":"It is Conclusive"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Because there is Asymptomatic. Secondary prevention detects disease early in apparently healthy people so timely treatment can reduce progression or complications.","sourceLocations":[{"assessment":"Midterm","batch":"434","questionNumber":31,"sourceType":"Gift"}],"references":[{"title":"WHO — Screening programmes: a short guide","url":"https://www.who.int/publications/i/item/9789289054782"}],"lectureOrder":5,"referenceOrder":66031},{"id":"community-mid-prevention-and-control-of-infectious-fd2f4eda","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"434","sourceLabel":"Community Medicine Gift","stem":"What is the type of Measles vaccine?","options":[{"id":"A","text":"Live attenuated"},{"id":"B","text":"Inactivated"},{"id":"C","text":"Subunit"},{"id":"D","text":"Toxoid"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Live attenuated. Measles-containing vaccines such as MMR are live attenuated vaccines; the schedule and contraindications must follow the current national programme.","sourceLocations":[{"assessment":"Midterm","batch":"434","questionNumber":32,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":66032},{"id":"community-mid-adolescent-and-child-health-a2a87bb6","subjectId":"community","lecture":"Adolescent and Child Health","assessment":"Midterm","sourceBatch":"434","sourceLabel":"Community Medicine Gift","stem":"What is the route of administration of BCG?","options":[{"id":"A","text":"Intramuscular"},{"id":"B","text":"Intradermal"},{"id":"C","text":"Intravenous"},{"id":"D","text":"Oral"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Intradermal. BCG is administered intradermally; correct technique produces a small local wheal and helps avoid injection-related complications.","sourceLocations":[{"assessment":"Midterm","batch":"434","questionNumber":33,"sourceType":"Gift"},{"assessment":"Midterm","batch":"432","questionNumber":35,"sourceType":"Gift"}],"references":[{"title":"WHO — Adolescent health","url":"https://www.who.int/health-topics/adolescent-health"}],"lectureOrder":10,"referenceOrder":66033},{"id":"community-mid-prevention-and-control-of-infectious-339f4639","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"434","sourceLabel":"Community Medicine Gift","stem":"Which of the following age group has the highest risk of developing chronic hepatitis B carrier state?","options":[{"id":"A","text":"Elderly"},{"id":"B","text":"Infants"},{"id":"C","text":"Pregnant Women"},{"id":"D","text":"Young Adults"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Infants. A carrier harbors the agent without apparent illness yet can transmit it, making detection and appropriate management important for control.","sourceLocations":[{"assessment":"Midterm","batch":"434","questionNumber":34,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":66034},{"id":"community-mid-prevention-and-control-of-infectious-aa5b9b33","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"434","sourceLabel":"Community Medicine Gift","stem":"A mother with chronic Hepatitis B virus infection gave birth to a baby, which preventive measures this newborn should receive?","options":[{"id":"A","text":"Immune globulins"},{"id":"B","text":"Chemoprophylaxis"},{"id":"C","text":"Hepatitis B vaccine"},{"id":"D","text":"Hepatitis B vaccine and immune globulins"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Hepatitis B vaccine and immune globulins. Age and immune status strongly affect chronic viral-hepatitis risk; hepatitis B becomes chronic far more often after perinatal infection than after adult infection.","sourceLocations":[{"assessment":"Midterm","batch":"434","questionNumber":35,"sourceType":"Gift"},{"assessment":"Midterm","batch":"432","questionNumber":37,"sourceType":"Gift"},{"assessment":"Midterm","batch":"431","questionNumber":35,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":66035},{"id":"community-mid-prevention-and-control-of-infectious-acf82e27","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"434","sourceLabel":"Community Medicine Gift","stem":"Which one of the following is preventive measure for hepatitis A?","options":[{"id":"A","text":"Avoid Tattooing"},{"id":"B","text":"Screening for blood donors"},{"id":"C","text":"Universal Infant Vaccination"},{"id":"D","text":"Prevention of sexual transmission"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Universal Infant Vaccination. Hepatitis A prevention combines vaccination with safe water, sanitation, food hygiene and hand hygiene; blood-borne precautions address other hepatitis viruses.","sourceLocations":[{"assessment":"Midterm","batch":"434","questionNumber":36,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":66036},{"id":"community-mid-prevention-and-control-of-infectious-ceb2baba","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"434","sourceLabel":"Community Medicine Gift","stem":"What is the main reservoir for influenza A?","options":[{"id":"A","text":"Animals"},{"id":"B","text":"Human carriers"},{"id":"C","text":"Soil"},{"id":"D","text":"Water pools"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Animals. A reservoir is the habitat in which an infectious agent normally lives, grows and multiplies; it is not always the same as the immediate source of exposure.","sourceLocations":[{"assessment":"Midterm","batch":"434","questionNumber":37,"sourceType":"Gift"},{"assessment":"Midterm","batch":"432","questionNumber":43,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":66037},{"id":"community-mid-prevention-and-control-of-infectious-92bd2752","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"434","sourceLabel":"Community Medicine Gift","stem":"Which one of the following interventions for malaria prevention is implemented at the secondary level?","options":[{"id":"A","text":"Case management"},{"id":"B","text":"Chemoprophylaxis"},{"id":"C","text":"Larva control"},{"id":"D","text":"Malaria mass vaccination"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Case management. Secondary prevention focuses on early diagnosis and effective treatment to prevent progression and reduce the infectious reservoir.","sourceLocations":[{"assessment":"Midterm","batch":"434","questionNumber":38,"sourceType":"Gift"},{"assessment":"Midterm","batch":"432","questionNumber":44,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":66038},{"id":"community-mid-prevention-and-control-of-infectious-6313cac9","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"434","sourceLabel":"Community Medicine Gift","stem":"What is the current WHO recommended tuberculosis control strategy?","options":[{"id":"A","text":"BCG vaccination"},{"id":"B","text":"Treatment with DOTS strategy"},{"id":"C","text":"Isolation of patients"},{"id":"D","text":"Occupational and social rehabilitation"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Treatment with DOTS strategy. Directly observed therapy supports completion of an effective multidrug tuberculosis regimen and reduces treatment failure, relapse and acquired resistance.","sourceLocations":[{"assessment":"Midterm","batch":"434","questionNumber":39,"sourceType":"Gift"},{"assessment":"Midterm","batch":"432","questionNumber":52,"sourceType":"Gift"},{"assessment":"Midterm","batch":"431","questionNumber":38,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":66039},{"id":"community-mid-prevention-and-control-of-infectious-cf25bf81","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"434","sourceLabel":"Community Medicine Gift","stem":"What is the main reservoir of Tetanus Infection?","options":[{"id":"A","text":"Human Cases"},{"id":"B","text":"Animal"},{"id":"C","text":"Soil"},{"id":"D","text":"Water"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Soil. A reservoir is the habitat in which an infectious agent normally lives, grows and multiplies; it is not always the same as the immediate source of exposure.","sourceLocations":[{"assessment":"Midterm","batch":"434","questionNumber":40,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":66040},{"id":"community-mid-prevention-and-control-of-infectious-7d7d8bf1","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"434","sourceLabel":"Community Medicine Gift","stem":"What is the most efficient mode of transmission of HIV/AIDS?","options":[{"id":"A","text":"Blood Transfusion"},{"id":"B","text":"Needle­Prick"},{"id":"C","text":"Perinatal"},{"id":"D","text":"Sexual"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A - Question ask about efficient not predominant","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Blood Transfusion. Measures aimed at the transmission route include sanitation, disinfection, ventilation, vector control and safe food, water or injection practices, depending on the agent.","sourceLocations":[{"assessment":"Midterm","batch":"434","questionNumber":41,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":66041},{"id":"community-mid-prevention-and-control-of-infectious-149acd2a","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"434","sourceLabel":"Community Medicine Gift","stem":"What is the predominant route of transmission of HIV/AIDS Infection In KSA?","options":[{"id":"A","text":"Intravenous Drug User"},{"id":"B","text":"Mother to fetal transmission"},{"id":"C","text":"Sexual Intercourse"},{"id":"D","text":"Blood Transfusion"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Sexual Intercourse. HIV transmission patterns vary by population and period; the keyed answer reflects the course epidemiology, while prevention targets sexual, blood-borne and vertical routes.","sourceLocations":[{"assessment":"Midterm","batch":"434","questionNumber":42,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":66042},{"id":"community-mid-natural-history-of-disease-and-conce-e71efdb6","subjectId":"community","lecture":"Natural History of Disease and Concepts of Prevention and Control","assessment":"Midterm","sourceBatch":"434","sourceLabel":"Community Medicine Gift","stem":"Which level of prevention applies for the setting of policies and legislations to address behaviour of the population and environment?","options":[{"id":"A","text":"Primordial Prevention"},{"id":"B","text":"Primary Prevention"},{"id":"C","text":"Secondary Prevention"},{"id":"D","text":"Tertiary Prevention"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Primordial Prevention. Primordial prevention changes upstream social and environmental conditions so risk factors do not become established in the population.","sourceLocations":[{"assessment":"Midterm","batch":"434","questionNumber":43,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/index.html"}],"lectureOrder":1,"referenceOrder":66043},{"id":"community-mid-global-demography-concepts-and-popul-448309b5","subjectId":"community","lecture":"Global Demography Concepts and Population Pyramid","assessment":"Midterm","sourceBatch":"434","sourceLabel":"Community Medicine Gift","stem":"Which of the following is a characteristic of the “De Jure” Census?","options":[{"id":"A","text":"Easy In conduction"},{"id":"B","text":"Requires few resources"},{"id":"C","text":"Miss People in transit"},{"id":"D","text":"Provides a factual figure"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Provides a factual figure. A de jure census counts people at their usual legal residence, rather than where they happen to be on census day.","sourceLocations":[{"assessment":"Midterm","batch":"434","questionNumber":44,"sourceType":"Gift"}],"references":[{"title":"United Nations World Population Prospects","url":"https://www.un.org/development/desa/pd/content/world-population-prospects-2024"}],"lectureOrder":2,"referenceOrder":66044},{"id":"community-mid-global-demography-concepts-and-popul-8c2d2add","subjectId":"community","lecture":"Global Demography Concepts and Population Pyramid","assessment":"Midterm","sourceBatch":"434","sourceLabel":"Community Medicine Gift","stem":"What does the population pyramid represent?","options":[{"id":"A","text":"Distribution of the population"},{"id":"B","text":"Age and sex composition"},{"id":"C","text":"The births and deaths"},{"id":"D","text":"Population growth"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Age and sex composition. A population pyramid displays age and sex structure; a broad base suggests high fertility and a younger population, while a narrower base and larger older groups suggest ageing.","sourceLocations":[{"assessment":"Midterm","batch":"434","questionNumber":45,"sourceType":"Gift"}],"references":[{"title":"United Nations World Population Prospects","url":"https://www.un.org/development/desa/pd/content/world-population-prospects-2024"}],"lectureOrder":2,"referenceOrder":66045},{"id":"community-mid-prevention-and-control-of-infectious-12ee6800","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"434","sourceLabel":"Community Medicine Gift","stem":"Which of the following groups has the highest rate of mortality from Hepatitis E Infection?","options":[{"id":"A","text":"Infants"},{"id":"B","text":"Young Adults"},{"id":"C","text":"Pregnant Women"},{"id":"D","text":"Elderly"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Pregnant Women. Hepatitis E can be particularly severe during pregnancy, with a higher risk of fulminant hepatitis and maternal death.","sourceLocations":[{"assessment":"Midterm","batch":"434","questionNumber":47,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":66047},{"id":"community-mid-prevention-and-control-of-infectious-b90cf1d8","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"434","sourceLabel":"Community Medicine Gift","stem":"What is the main mode of transmission in malaria?","options":[{"id":"A","text":"Blood Transfusion"},{"id":"B","text":"Animal bite"},{"id":"C","text":"Trans­Placental"},{"id":"D","text":"Vector borne"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D - Anopheles mosquito","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Vector borne. Measures aimed at the transmission route include sanitation, disinfection, ventilation, vector control and safe food, water or injection practices, depending on the agent.","sourceLocations":[{"assessment":"Midterm","batch":"434","questionNumber":48,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":66048},{"id":"community-mid-prevention-and-control-of-infectious-b33f7f67","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"434","sourceLabel":"Community Medicine Gift","stem":"Influenza virus is characterized by the occurrence of large number of cases in several countries and across continents at the same time. What is the pattern of the above­ described occurrence?","options":[{"id":"A","text":"Epidemic"},{"id":"B","text":"Outbreak"},{"id":"C","text":"Pandemic"},{"id":"D","text":"Endemic"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Pandemic. A pandemic is an epidemic with sustained spread across multiple countries or continents, affecting a large number of people.","sourceLocations":[{"assessment":"Midterm","batch":"434","questionNumber":49,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":66049},{"id":"community-mid-prevention-and-control-of-infectious-52b634c4","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"434","sourceLabel":"Community Medicine Gift","stem":"A Physician working in an emergency room in KKUH, has just examined a farmer with a history of recent contact with camels, The Physician suspects the man might have MERS­CoV. To Whom should the physician notify?","options":[{"id":"A","text":"The Infection control department in the hospital"},{"id":"B","text":"The preventive sector of ministry of health (MOH)"},{"id":"C","text":"The Regional Public health in the ministry of health"},{"id":"D","text":"The World Health Organization (WHO)"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C - by HESN","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is The Regional Public health in the ministry of health. A suspected MERS case with camel exposure requires prompt notification through the designated national surveillance system and appropriate infection-control precautions.","sourceLocations":[{"assessment":"Midterm","batch":"434","questionNumber":50,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":66050},{"id":"community-mid-surveillance-and-screening-bfa95628","subjectId":"community","lecture":"Surveillance and Screening","assessment":"Midterm","sourceBatch":"434","sourceLabel":"Community Medicine Gift","stem":"What is the purpose of public health surveillance?","options":[{"id":"A","text":"To Describe disease registration method"},{"id":"B","text":"To identify variations in case definition of a disease"},{"id":"C","text":"To keep the public aware of new diseases"},{"id":"D","text":"To Provide Information for public health action"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is To Provide Information for public health action. Surveillance is useful only when analyzed information is communicated to decision-makers and used for prevention and control.","sourceLocations":[{"assessment":"Midterm","batch":"434","questionNumber":51,"sourceType":"Gift"}],"references":[{"title":"WHO — Screening programmes: a short guide","url":"https://www.who.int/publications/i/item/9789289054782"}],"lectureOrder":5,"referenceOrder":66051},{"id":"community-mid-maternal-health-ae8b49e0","subjectId":"community","lecture":"Maternal Health","assessment":"Midterm","sourceBatch":"434","sourceLabel":"Community Medicine Gift","stem":"A mid year population of a town was 250.000 individuals. The number of live births was 3000 and the total number of deaths was 316 of them 120 were due to maternal causes. What is the maternal mortality rate?","options":[{"id":"A","text":"4000 per 100000 live births"},{"id":"B","text":"126 per 100000 deaths"},{"id":"C","text":"37.9 per 100000 live births"},{"id":"D","text":"48 per 100000 population"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A - (120/3000)*100.000","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is 4000 per 100000 live births. The maternal mortality rate uses women of reproductive age in the denominator, unlike the maternal mortality ratio, which uses live births.","sourceLocations":[{"assessment":"Midterm","batch":"434","questionNumber":52,"sourceType":"Gift"}],"references":[{"title":"WHO — Maternal health","url":"https://www.who.int/health-topics/maternal-health"}],"lectureOrder":11,"referenceOrder":66052},{"id":"community-mid-adolescent-and-child-health-21e7bdbf","subjectId":"community","lecture":"Adolescent and Child Health","assessment":"Midterm","sourceBatch":"434","sourceLabel":"Community Medicine Gift","stem":"In KSA, in 2011, the estimated mid year population was 28.376.355. The number of live births was 648.000 and the number of infants deaths was 9.850. Considering the above data, which one of the following is the “Infant Mortality Ratio” for KSA In 2011?","options":[{"id":"A","text":"3.37"},{"id":"B","text":"33.7"},{"id":"C","text":"15.2"},{"id":"D","text":"16.38"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C - (9850/648000)*1000","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is 15.2. In a ratio, the numerator is not necessarily part of the denominator. In a proportion it is included, and a rate additionally incorporates the occurrence of events over time.","sourceLocations":[{"assessment":"Midterm","batch":"434","questionNumber":53,"sourceType":"Gift"}],"references":[{"title":"WHO — Adolescent health","url":"https://www.who.int/health-topics/adolescent-health"}],"lectureOrder":10,"referenceOrder":66053},{"id":"community-mid-surveillance-and-screening-c78c714a","subjectId":"community","lecture":"Surveillance and Screening","assessment":"Midterm","sourceBatch":"434","sourceLabel":"Community Medicine Gift","stem":"Which one of the following statements is the description of “Public Health Surveillance”?","options":[{"id":"A","text":"A Method to monitor the occurrence of public health problems"},{"id":"B","text":"A Program to control disease outbreaks"},{"id":"C","text":"A System for collecting health related information"},{"id":"D","text":"A System for monitoring persons who have been exposed to a communicable disease."}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is A System for collecting health related information. Public-health surveillance is continuous, systematic collection, analysis, interpretation and dissemination of health data for action.","sourceLocations":[{"assessment":"Midterm","batch":"434","questionNumber":54,"sourceType":"Gift"}],"references":[{"title":"WHO — Screening programmes: a short guide","url":"https://www.who.int/publications/i/item/9789289054782"}],"lectureOrder":5,"referenceOrder":66054},{"id":"community-mid-global-demography-concepts-and-popul-97ac15e0","subjectId":"community","lecture":"Global Demography Concepts and Population Pyramid","assessment":"Midterm","sourceBatch":"434","sourceLabel":"Community Medicine Gift","stem":"Which of the following indicators predicts the fertility of the next generation?","options":[{"id":"A","text":"Age Specific Fertility Rate"},{"id":"B","text":"Total Fertility Rate"},{"id":"C","text":"General Fertility Rate"},{"id":"D","text":"Gross Reproductive Rate"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Gross Reproductive Rate. Reliability is reproducibility: the indicator gives consistent results when measurement is repeated under comparable conditions.","sourceLocations":[{"assessment":"Midterm","batch":"434","questionNumber":55,"sourceType":"Gift"}],"references":[{"title":"United Nations World Population Prospects","url":"https://www.un.org/development/desa/pd/content/world-population-prospects-2024"}],"lectureOrder":2,"referenceOrder":66055},{"id":"community-mid-prevention-and-control-of-infectious-5d5fc9a0","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"434","sourceLabel":"Community Medicine Gift","stem":"Which one of the following is the main preventive measures for hepatitis C?","options":[{"id":"A","text":"Vaccination"},{"id":"B","text":"Screening of blood donors"},{"id":"C","text":"Hand washing"},{"id":"D","text":"Inspection of food handlers"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Screening of blood donors. Secondary prevention detects disease early in apparently healthy people so timely treatment can reduce progression or complications.","sourceLocations":[{"assessment":"Midterm","batch":"434","questionNumber":56,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":66056},{"id":"community-mid-prevention-and-control-of-infectious-b0388ccb","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"434","sourceLabel":"Community Medicine Gift","stem":"A person or animal that harbors an infectious organism but displays no symptoms and can transmit the disease to others. This definition stands for:","options":[{"id":"A","text":"Host"},{"id":"B","text":"Carrier"},{"id":"C","text":"Habitat"},{"id":"D","text":"Environment"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Carrier. A carrier harbors the agent without apparent illness yet can transmit it, making detection and appropriate management important for control.","sourceLocations":[{"assessment":"Midterm","batch":"434","questionNumber":57,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":66057},{"id":"community-mid-prevention-and-control-of-infectious-8790f00e","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"433","sourceLabel":"Community Medicine Gift","stem":"Which of the following routes of transmission is the hardest to control?","options":[{"id":"A","text":"Water borne"},{"id":"B","text":"Food borne"},{"id":"C","text":"Airborne"},{"id":"D","text":"Contact"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Airborne. Airborne transmission involves small droplet nuclei or particles that remain suspended and can travel beyond close-range droplet spread.","sourceLocations":[{"assessment":"Midterm","batch":"433","questionNumber":1,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":67001},{"id":"community-mid-maternal-health-7b595d09","subjectId":"community","lecture":"Maternal Health","assessment":"Midterm","sourceBatch":"433","sourceLabel":"Community Medicine Gift","stem":"Which one of the following vaccinations is recommended for pregnant women?","options":[{"id":"A","text":"MMR vaccine."},{"id":"B","text":"Hepatitis A vaccine."},{"id":"C","text":"German measles vaccine."},{"id":"D","text":"Tetanus toxoid vaccine."}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Tetanus toxoid vaccine.. Inactivated vaccines recommended for maternal protection can be given during pregnancy when indicated; live attenuated vaccines are generally contraindicated.","sourceLocations":[{"assessment":"Midterm","batch":"433","questionNumber":2,"sourceType":"Gift"}],"references":[{"title":"WHO — Maternal health","url":"https://www.who.int/health-topics/maternal-health"}],"lectureOrder":11,"referenceOrder":67002},{"id":"community-mid-surveillance-and-screening-12b96e9e","subjectId":"community","lecture":"Surveillance and Screening","assessment":"Midterm","sourceBatch":"433","sourceLabel":"Community Medicine Gift","stem":"A collaboration between WHO and ministry of health in KSA to start a surveillance program about MERSCov at Alhajj. What is the purpose of this collaboration?","options":[{"id":"A","text":"To detect outbreaks"},{"id":"B","text":"To identify registration method"},{"id":"C","text":"To monitor cause-­‐specific death rate"},{"id":"D","text":"To calculate the prevalence"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is To detect outbreaks. Timely surveillance detects unusual increases above the expected baseline so investigation and control can begin early.","sourceLocations":[{"assessment":"Midterm","batch":"433","questionNumber":3,"sourceType":"Gift"}],"references":[{"title":"WHO — Screening programmes: a short guide","url":"https://www.who.int/publications/i/item/9789289054782"}],"lectureOrder":5,"referenceOrder":67003},{"id":"community-mid-disparities-in-health-dd3fccf3","subjectId":"community","lecture":"Disparities in Health","assessment":"Midterm","sourceBatch":"433","sourceLabel":"Community Medicine Gift","stem":"Which of the following is an example of a healthcare delivery indicator?","options":[{"id":"A","text":"Bed population ratio"},{"id":"B","text":"Bed occupancy rate"},{"id":"C","text":"Bed turnover ratio"},{"id":"D","text":"Percentage of female attending family planning clinics"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Bed population ratio. In a ratio, the numerator is not necessarily part of the denominator. In a proportion it is included, and a rate additionally incorporates the occurrence of events over time.","sourceLocations":[{"assessment":"Midterm","batch":"433","questionNumber":4,"sourceType":"Gift"}],"references":[{"title":"WHO — Health inequities and their causes","url":"https://www.who.int/news-room/facts-in-pictures/detail/health-inequities-and-their-causes"}],"lectureOrder":8,"referenceOrder":67004},{"id":"community-mid-global-demography-concepts-and-popul-0c6f15b9","subjectId":"community","lecture":"Global Demography Concepts and Population Pyramid","assessment":"Midterm","sourceBatch":"433","sourceLabel":"Community Medicine Gift","stem":"Which one of the following is a characteristic for a low stationary transition model?","options":[{"id":"A","text":"Both birth rate and death rate are low"},{"id":"B","text":"Higher birth rate than death rate"},{"id":"C","text":"High death rate and birth rate"},{"id":"D","text":"Birth rate and death rate are high"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Both birth rate and death rate are low. Stage 4 has low birth and death rates, so population growth is low and the population is relatively stable.","sourceLocations":[{"assessment":"Midterm","batch":"433","questionNumber":5,"sourceType":"Gift"}],"references":[{"title":"United Nations World Population Prospects","url":"https://www.un.org/development/desa/pd/content/world-population-prospects-2024"}],"lectureOrder":2,"referenceOrder":67005},{"id":"community-mid-natural-history-of-disease-and-conce-c146a59e","subjectId":"community","lecture":"Natural History of Disease and Concepts of Prevention and Control","assessment":"Midterm","sourceBatch":"433","sourceLabel":"Community Medicine Gift","stem":"What is the concept behind \"mass treatment\" as a measure of secondary prevention of endemic diseases?","options":[{"id":"A","text":"Lack of suitable measures of primary prevention"},{"id":"B","text":"Difficulties in the identification of clinical cases"},{"id":"C","text":"The high ratio of latent infection to each clinical case"},{"id":"D","text":"Low utilization of health services by the population"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is The high ratio of latent infection to each clinical case. Secondary prevention detects disease early in apparently healthy people so timely treatment can reduce progression or complications.","sourceLocations":[{"assessment":"Midterm","batch":"433","questionNumber":7,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/index.html"}],"lectureOrder":1,"referenceOrder":67007},{"id":"community-mid-surveillance-and-screening-93beb376","subjectId":"community","lecture":"Surveillance and Screening","assessment":"Midterm","sourceBatch":"433","sourceLabel":"Community Medicine Gift","stem":"Which one of the following diseases is suitable for screening programs?","options":[{"id":"A","text":"A disease with high fatality rate"},{"id":"B","text":"A disease with high prevalence of asymptomatic cases"},{"id":"C","text":"Diseases with no effective treatment"},{"id":"D","text":"A disease with fast development of clinically apparent signs and symptoms"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is A disease with high prevalence of asymptomatic cases. Prevalence includes all existing cases at a point or during a period. It is influenced by both incidence and disease duration.","sourceLocations":[{"assessment":"Midterm","batch":"433","questionNumber":9,"sourceType":"Gift"}],"references":[{"title":"WHO — Screening programmes: a short guide","url":"https://www.who.int/publications/i/item/9789289054782"}],"lectureOrder":5,"referenceOrder":67009},{"id":"community-mid-prevention-and-control-of-infectious-c05d0e67","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"433","sourceLabel":"Community Medicine Gift","stem":"Pathogenicity of the organism refers to which one of the following?","options":[{"id":"A","text":"Invasion of the tissues"},{"id":"B","text":"Multiplication in the host"},{"id":"C","text":"Production of toxins"},{"id":"D","text":"Production of a specific disease"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Production of a specific disease. Pathogenicity is the ability of an agent to cause clinical disease among infected hosts; virulence describes the severity of resulting disease.","sourceLocations":[{"assessment":"Midterm","batch":"433","questionNumber":10,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":67010},{"id":"community-mid-surveillance-and-screening-4b78abef","subjectId":"community","lecture":"Surveillance and Screening","assessment":"Midterm","sourceBatch":"433","sourceLabel":"Community Medicine Gift","stem":"Which of the following describes a difference between survey and surveillance?","options":[{"id":"A","text":"Survey monitors long term trends whereas surveillance informs about patterns of disease occurrence"},{"id":"B","text":"Survey provides data for new cases of diseases whereas surveillance provides history of old and new cases of diseases"},{"id":"C","text":"Survey is time consuming while surveillance is relatively quick"},{"id":"D","text":"Survey is a one time activity and surveillance is an ongoing collection of data"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Survey is a one time activity and surveillance is an ongoing collection of data. Surveillance is continuous, systematic collection, analysis, interpretation and dissemination for public-health action; a survey is time-limited.","sourceLocations":[{"assessment":"Midterm","batch":"433","questionNumber":11,"sourceType":"Gift"}],"references":[{"title":"WHO — Screening programmes: a short guide","url":"https://www.who.int/publications/i/item/9789289054782"}],"lectureOrder":5,"referenceOrder":67011},{"id":"community-mid-prevention-and-control-of-infectious-0d324a4d","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"433","sourceLabel":"Community Medicine Gift","stem":"Which one of the following is primary zoonotic disease?","options":[{"id":"A","text":"Rabies"},{"id":"B","text":"Malaria"},{"id":"C","text":"Hepatitis A"},{"id":"D","text":"Poliomyelitis"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Rabies. A zoonosis is naturally transmitted between vertebrate animals and humans; whether onward human-to-human spread occurs depends on the specific agent.","sourceLocations":[{"assessment":"Midterm","batch":"433","questionNumber":13,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":67013},{"id":"community-mid-maternal-health-e9af7589","subjectId":"community","lecture":"Maternal Health","assessment":"Midterm","sourceBatch":"433","sourceLabel":"Community Medicine Gift","stem":"Which of the following indicators represent deaths attribute to pregnancy, delivery and peripartum?","options":[{"id":"A","text":"Perinatal Mortality Rate."},{"id":"B","text":"Early Neonatal Mortality Rate."},{"id":"C","text":"Infected Mortality Rate."},{"id":"D","text":"Maternal Mortality Rate."}],"images":[],"incompleteSource":false,"sourceAnswer":["A","D"],"sourceAnswerNote":"A or D - The question is missing, if they want infant deaths then the answer is A, but if they want death of the mothers then the answer is D.","aiAnswer":"D","aiSuggestion":"Because the stem asks about deaths attributable to pregnancy, delivery and the puerperium, maternal mortality is the intended indicator.","verification":"conflict","explanation":"Deaths attributable to pregnancy, childbirth or the puerperium are maternal deaths, so the indicator is maternal mortality. Perinatal mortality concerns late fetal and early neonatal deaths, not deaths of the mother.","sourceLocations":[{"assessment":"Midterm","batch":"433","questionNumber":14,"sourceType":"Gift"}],"references":[{"title":"WHO — Maternal health","url":"https://www.who.int/health-topics/maternal-health"}],"lectureOrder":11,"referenceOrder":67014},{"id":"community-mid-prevention-and-control-of-infectious-e75738b8","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"433","sourceLabel":"Community Medicine Gift","stem":"How can hepatitis B get transmitted among health care providers?","options":[{"id":"A","text":"Needle sticks"},{"id":"B","text":"Direct contact"},{"id":"C","text":"Tattoos"},{"id":"D","text":"Wounds cleaning"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Needle sticks. Occupational hepatitis B transmission occurs mainly through percutaneous or mucosal exposure to infected blood, such as a needlestick injury.","sourceLocations":[{"assessment":"Midterm","batch":"433","questionNumber":15,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":67015},{"id":"community-mid-prevention-and-control-of-infectious-8e9b47bd","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"433","sourceLabel":"Community Medicine Gift","stem":"Which type of immunity a child would have from his mother?","options":[{"id":"A","text":"Natural passive"},{"id":"B","text":"Natural active"},{"id":"C","text":"Passive artificial"},{"id":"D","text":"Active artificial"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Natural passive. Passive surveillance relies on routine reports sent by healthcare providers or laboratories; it is inexpensive but vulnerable to under-reporting.","sourceLocations":[{"assessment":"Midterm","batch":"433","questionNumber":18,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":67018},{"id":"community-mid-surveillance-and-screening-d64e0564","subjectId":"community","lecture":"Surveillance and Screening","assessment":"Midterm","sourceBatch":"433","sourceLabel":"Community Medicine Gift","stem":"A new screening test can detect 22 out of 45 patients with positive PCR test. And shows negative results for 2 patients with negative PCR, What is the sensitivity of the new screening tool?","options":[{"id":"A","text":"33%"},{"id":"B","text":"84%"},{"id":"C","text":"48%"},{"id":"D","text":"50%"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C - 22/45 * 100 = 48.8%","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is 48%. Sensitivity is the proportion of people with the condition who test positive: TP/(TP+FN). A highly sensitive test therefore minimizes false negatives.","sourceLocations":[{"assessment":"Midterm","batch":"433","questionNumber":19,"sourceType":"Gift"}],"references":[{"title":"WHO — Screening programmes: a short guide","url":"https://www.who.int/publications/i/item/9789289054782"}],"lectureOrder":5,"referenceOrder":67019},{"id":"community-mid-natural-history-of-disease-and-conce-473a7733","subjectId":"community","lecture":"Natural History of Disease and Concepts of Prevention and Control","assessment":"Midterm","sourceBatch":"433","sourceLabel":"Community Medicine Gift","stem":"What to do in secondary prevention?","options":[{"id":"A","text":"Reduction of disease occurrence"},{"id":"B","text":"Treat disabled people"},{"id":"C","text":"Early treatment for ill‐patients"},{"id":"D","text":"Prevent complications"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Early treatment for ill‐patients. Secondary prevention detects disease early in apparently healthy people so timely treatment can reduce progression or complications.","sourceLocations":[{"assessment":"Midterm","batch":"433","questionNumber":21,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/index.html"}],"lectureOrder":1,"referenceOrder":67021},{"id":"community-mid-principles-of-epidemiology-271a152e","subjectId":"community","lecture":"Principles of Epidemiology","assessment":"Midterm","sourceBatch":"433","sourceLabel":"Community Medicine Gift","stem":"Which one of the following are components of analytic epidemiologic triangle model?","options":[{"id":"A","text":"Host, agent, and environment."},{"id":"B","text":"Person, place, and time."},{"id":"C","text":"Fertility, mortality, and migration."},{"id":"D","text":"Distribution, eradication and determinants."}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Host, agent, and environment.. The analytic epidemiologic triad is agent, host and environment; person, place and time belong to descriptive epidemiology.","sourceLocations":[{"assessment":"Midterm","batch":"433","questionNumber":22,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Measures of Risk","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson3/section2.html"}],"lectureOrder":3,"referenceOrder":67022},{"id":"community-mid-maternal-health-a76c4b5f","subjectId":"community","lecture":"Maternal Health","assessment":"Midterm","sourceBatch":"433","sourceLabel":"Community Medicine Gift","stem":"Which one of these vaccines is recommended in pregnant women?","options":[{"id":"A","text":"MMR"},{"id":"B","text":"Hepatitis A"},{"id":"D","text":"German measles virus"},{"id":"C","text":"Tetanus toxoid vaccine"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D","aiAnswer":"C","aiSuggestion":"Tetanus toxoid is the recommended listed vaccine in pregnancy. The source labels it C but records D, which is German measles vaccine and is contraindicated.","verification":"conflict","explanation":"Tetanus toxoid is the recommended listed vaccine during pregnancy. In the extracted source it is option C; the recorded D is German measles vaccine, a live vaccine that is contraindicated during pregnancy.","sourceLocations":[{"assessment":"Midterm","batch":"433","questionNumber":23,"sourceType":"Gift"}],"references":[{"title":"WHO — Maternal health","url":"https://www.who.int/health-topics/maternal-health"}],"lectureOrder":11,"referenceOrder":67023},{"id":"community-mid-natural-history-of-disease-and-conce-d0173d21","subjectId":"community","lecture":"Natural History of Disease and Concepts of Prevention and Control","assessment":"Midterm","sourceBatch":"433","sourceLabel":"Community Medicine Gift","stem":"What is the main objective of preventing a disease at the primary prevention time?","options":[{"id":"A","text":"Prevent complications"},{"id":"B","text":"Reduction of mortality"},{"id":"C","text":"Early recovery from disease"},{"id":"D","text":"Reduce occurrence of a disease"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Reduce occurrence of a disease. Primary prevention acts before disease begins through health promotion or specific protection. Screening is not primary prevention; it is secondary prevention.","sourceLocations":[{"assessment":"Midterm","batch":"433","questionNumber":24,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/index.html"}],"lectureOrder":1,"referenceOrder":67024},{"id":"community-mid-prevention-and-control-of-infectious-28972f2f","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"433","sourceLabel":"Community Medicine Gift","stem":"Which of the following is the Contamination definition?","options":[{"id":"A","text":"Entry and development or multiplication of an infectious agent in the body"},{"id":"B","text":"Eradication of all living and nonliving organisms on surfaces"},{"id":"C","text":"The presence of living infectious agents on the exterior surface of the body"},{"id":"D","text":"Ability of an organism to invade host tissues"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is The presence of living infectious agents on the exterior surface of the body. Infestation is the lodgement or development of arthropods on the body surface or in clothing; infection refers to invasion and multiplication within the host.","sourceLocations":[{"assessment":"Midterm","batch":"433","questionNumber":25,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":67025},{"id":"community-mid-global-demography-concepts-and-popul-125dcd50","subjectId":"community","lecture":"Global Demography Concepts and Population Pyramid","assessment":"Midterm","sourceBatch":"433","sourceLabel":"Community Medicine Gift","stem":"What does a wide base of a population pyramid indicate?","options":[{"id":"A","text":"High mortality rates"},{"id":"B","text":"High proportion of children"},{"id":"C","text":"High old dependency ratio"},{"id":"D","text":"High proportion of females"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is High proportion of children. The dependency ratio compares younger and older dependants with the working-age population, usually expressed per 100 working-age people.","sourceLocations":[{"assessment":"Midterm","batch":"433","questionNumber":26,"sourceType":"Gift"},{"assessment":"Midterm","batch":"432","questionNumber":45,"sourceType":"Gift"}],"references":[{"title":"United Nations World Population Prospects","url":"https://www.un.org/development/desa/pd/content/world-population-prospects-2024"}],"lectureOrder":2,"referenceOrder":67026},{"id":"community-mid-natural-history-of-disease-and-conce-ea42c895","subjectId":"community","lecture":"Natural History of Disease and Concepts of Prevention and Control","assessment":"Midterm","sourceBatch":"433","sourceLabel":"Community Medicine Gift","stem":"Autism is an irreversible disease with unknown cause, which of the following is the suitable intervention for such disease?","options":[{"id":"A","text":"Tertiary prevention"},{"id":"B","text":"Primary"},{"id":"C","text":"Secondary"},{"id":"D","text":"None of them"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Tertiary prevention. Tertiary prevention limits disability and restores function after disease is established, including rehabilitation and complication prevention.","sourceLocations":[{"assessment":"Midterm","batch":"433","questionNumber":27,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/index.html"}],"lectureOrder":1,"referenceOrder":67027},{"id":"community-mid-disparities-in-health-d8cb1c53","subjectId":"community","lecture":"Disparities in Health","assessment":"Midterm","sourceBatch":"433","sourceLabel":"Community Medicine Gift","stem":"Reliable indicator means which of the following?","options":[{"id":"A","text":"Measures what it is supposed to measure"},{"id":"B","text":"Reflects changes only in the situation concerned"},{"id":"C","text":"Give the same results on repeated measurement by different individuals"},{"id":"D","text":"Gives inaccurate results"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Give the same results on repeated measurement by different individuals. Reliability is reproducibility: the indicator gives consistent results when measurement is repeated under comparable conditions.","sourceLocations":[{"assessment":"Midterm","batch":"433","questionNumber":28,"sourceType":"Gift"}],"references":[{"title":"WHO — Health inequities and their causes","url":"https://www.who.int/news-room/facts-in-pictures/detail/health-inequities-and-their-causes"}],"lectureOrder":8,"referenceOrder":67028},{"id":"community-mid-prevention-and-control-of-infectious-8802d8f9","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"433","sourceLabel":"Community Medicine Gift","stem":"Which of the following is the definition of endemic?","options":[{"id":"A","text":"An epidemic occurring over a very wide area"},{"id":"B","text":"Affecting large number of community in a short time"},{"id":"C","text":"The constant presence of a disease or infectious agent within a given geographic area or population"},{"id":"D","text":"The occurrence of more cases of a disease than expected in a given area"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is The constant presence of a disease or infectious agent within a given geographic area or population. Endemic means the constant or usual presence of a disease or agent in a defined geographic area or population.","sourceLocations":[{"assessment":"Midterm","batch":"433","questionNumber":30,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":67030},{"id":"community-mid-prevention-and-control-of-infectious-b8ed3861","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"433","sourceLabel":"Community Medicine Gift","stem":"The death rate of HIV declined within the last few years, but the rates of infection increased. What does that mean? (The statement was based on a graph given in the question)","options":[{"id":"A","text":"Decrease awareness about the disease"},{"id":"B","text":"High number of children born with AIDS"},{"id":"C","text":"Increase burden of healthcare cost"},{"id":"D","text":"Decrease burden of healthcare cost"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Increase burden of healthcare cost. Falling mortality while incidence or prevalence remains high can reflect longer survival with effective treatment rather than elimination of transmission.","sourceLocations":[{"assessment":"Midterm","batch":"433","questionNumber":32,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":67032},{"id":"community-mid-prevention-and-control-of-infectious-1f238203","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"433","sourceLabel":"Community Medicine Gift","stem":"There are Few cases of new disease beginning with sore throat and bleeding What you do?","options":[{"id":"A","text":"Calculate the incidence"},{"id":"B","text":"Formulate Inclusion criteria"},{"id":"C","text":"Formulate a team and establish the existence of an outbreak D. Calculate the prevalence"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Formulate a team and establish the existence of an outbreak D. Calculate the prevalence. Prevalence includes all existing cases at a point or during a period. It is influenced by both incidence and disease duration.","sourceLocations":[{"assessment":"Midterm","batch":"433","questionNumber":33,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":67033},{"id":"community-mid-prevention-and-control-of-infectious-1038586b","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"433","sourceLabel":"Community Medicine Gift","stem":"What determines the virulence of an organism?","options":[{"id":"A","text":"Case fatality rate"},{"id":"B","text":"Age-specific death rate"},{"id":"C","text":"Cause-specific death rate"},{"id":"D","text":"Life expectancy"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Case fatality rate. Case fatality is deaths among diagnosed cases divided by all cases of that disease; it describes severity rather than population risk.","sourceLocations":[{"assessment":"Midterm","batch":"433","questionNumber":34,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":67034},{"id":"community-mid-determinants-of-health-8eb5d9b6","subjectId":"community","lecture":"Determinants of Health","assessment":"Midterm","sourceBatch":"433","sourceLabel":"Community Medicine Gift","stem":"Crowding and poverty is an example of?","options":[{"id":"A","text":"Healthcare delivery indicator"},{"id":"B","text":"Environmental factor"},{"id":"C","text":"Agent factor"},{"id":"D","text":"Host factor"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Environmental factor. Features of the built and physical environment—such as housing, walkability, crowding, water and pollution—are environmental determinants of health.","sourceLocations":[{"assessment":"Midterm","batch":"433","questionNumber":35,"sourceType":"Gift"}],"references":[{"title":"WHO — Social determinants of health","url":"https://www.who.int/health-topics/social-determinants-of-health"}],"lectureOrder":4,"referenceOrder":67035},{"id":"community-mid-natural-history-of-disease-and-conce-59074ffa","subjectId":"community","lecture":"Natural History of Disease and Concepts of Prevention and Control","assessment":"Midterm","sourceBatch":"433","sourceLabel":"Community Medicine Gift","stem":"Iceberg Phenomenon describes which of the following?","options":[{"id":"A","text":"The correlation between the disease severity and its mortality"},{"id":"B","text":"Number of undiagnosed or wrongly diagnosed patients"},{"id":"C","text":"Relation between risk factors and disease development"},{"id":"D","text":"Number of people who have the disease"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Number of undiagnosed or wrongly diagnosed patients. The visible diagnosed cases are the tip of the iceberg, while undiagnosed, subclinical or carrier states form the much larger hidden portion.","sourceLocations":[{"assessment":"Midterm","batch":"433","questionNumber":36,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/index.html"}],"lectureOrder":1,"referenceOrder":67036},{"id":"community-mid-prevention-and-control-of-infectious-592f0b34","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"433","sourceLabel":"Community Medicine Gift","stem":"What is the scientific name that describes the state of immunity of a group of people or a community?","options":[{"id":"A","text":"Active immunity"},{"id":"B","text":"Herd immunity"},{"id":"C","text":"Immunogenicity"},{"id":"D","text":"Passive immunity"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Herd immunity. Herd immunity is indirect community protection when enough people are immune to interrupt sustained transmission, helping protect those who cannot be immunized.","sourceLocations":[{"assessment":"Midterm","batch":"433","questionNumber":37,"sourceType":"Gift"},{"assessment":"Midterm","batch":"432","questionNumber":10,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":67037},{"id":"community-mid-adolescent-and-child-health-0fae1abb","subjectId":"community","lecture":"Adolescent and Child Health","assessment":"Midterm","sourceBatch":"433","sourceLabel":"Community Medicine Gift","stem":"According to the MOH, in 1433 the number of infants death was 106,419, the mid year population was 29,195,895 and the total number of live births was 656,907. Calculate the infant mortality rate?","options":[{"id":"A","text":"166/1000"},{"id":"B","text":"145/1000"},{"id":"C","text":"162/1000"},{"id":"D","text":"132/1000 Infant mortality rate = number of infant deaths / number of live births = 106419/656907 = 0.162"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is 162/1000. Infant mortality uses deaths before age one in the numerator and live births in the denominator, conventionally expressed per 1,000 live births.","sourceLocations":[{"assessment":"Midterm","batch":"433","questionNumber":38,"sourceType":"Gift"}],"references":[{"title":"WHO — Adolescent health","url":"https://www.who.int/health-topics/adolescent-health"}],"lectureOrder":10,"referenceOrder":67038},{"id":"community-mid-maternal-health-8ec3cd84","subjectId":"community","lecture":"Maternal Health","assessment":"Midterm","sourceBatch":"433","sourceLabel":"Community Medicine Gift","stem":"The estimated mid­‐year population in country A was 28,376,355, while the number of live births was 650,000 and the number of maternal deaths was 95. Calculate the maternal mortality ratio?","options":[{"id":"A","text":"3.34"},{"id":"B","text":"14.6"},{"id":"C","text":"18.8"},{"id":"D","text":"22.9"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B - Maternal mortality ratio = number of maternal deaths / number of live births = 95 / 650000 = 0.000146 or 14.6 per 100,000 live births","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is 14.6. The maternal mortality ratio is maternal deaths during a period divided by live births in the same period, conventionally multiplied by 100,000.","sourceLocations":[{"assessment":"Midterm","batch":"433","questionNumber":39,"sourceType":"Gift"}],"references":[{"title":"WHO — Maternal health","url":"https://www.who.int/health-topics/maternal-health"}],"lectureOrder":11,"referenceOrder":67039},{"id":"community-mid-disparities-in-health-b598e0cc","subjectId":"community","lecture":"Disparities in Health","assessment":"Midterm","sourceBatch":"432","sourceLabel":"Community Medicine Gift","stem":"In the current outbreak of Ebola virus disease in 2014, which had severe outcomes. Which one of the following epidemiological measures is used?","options":[{"id":"A","text":"Case fatality rate"},{"id":"B","text":"Ratio of clinical to subclinical cases"},{"id":"C","text":"Secondary attack frequency"},{"id":"D","text":"Secondary attack rate among contacts"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Case fatality rate. Case fatality is deaths among diagnosed cases divided by all cases of that disease; it describes severity rather than population risk.","sourceLocations":[{"assessment":"Midterm","batch":"432","questionNumber":1,"sourceType":"Gift"}],"references":[{"title":"WHO — Health inequities and their causes","url":"https://www.who.int/news-room/facts-in-pictures/detail/health-inequities-and-their-causes"}],"lectureOrder":8,"referenceOrder":68001},{"id":"community-mid-prevention-and-control-of-infectious-a4329ea0","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"432","sourceLabel":"Community Medicine Gift","stem":"Which one of the following is a mode of transmission of Ebola virus?","options":[{"id":"A","text":"Air-borne"},{"id":"B","text":"Direct contact"},{"id":"C","text":"Food borne"},{"id":"D","text":"Vector borne"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Direct contact. Direct transmission occurs through immediate physical contact with an infected person, body fluid, soil or another source without an intervening vehicle or vector.","sourceLocations":[{"assessment":"Midterm","batch":"432","questionNumber":2,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":68002},{"id":"community-mid-prevention-and-control-of-infectious-96d85196","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"432","sourceLabel":"Community Medicine Gift","stem":"What is the main preventive measure for Ebola virus disease in healthcare settings?","options":[{"id":"A","text":"Chemoprophylaxis with novel antiviral agents"},{"id":"B","text":"Provision of standard case management"},{"id":"C","text":"Taking standard precautions during patient care"},{"id":"D","text":"Vaccination of healthcare workers"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Taking standard precautions during patient care. Ebola control in healthcare relies on rapid isolation, appropriate personal protective equipment, safe specimen and waste handling, and active contact monitoring for the incubation period.","sourceLocations":[{"assessment":"Midterm","batch":"432","questionNumber":4,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":68004},{"id":"community-mid-principles-of-epidemiology-6a986bd5","subjectId":"community","lecture":"Principles of Epidemiology","assessment":"Midterm","sourceBatch":"432","sourceLabel":"Community Medicine Gift","stem":"In Epidemiological triad which one is environmental factor?","options":[{"id":"A","text":"Availability of health services"},{"id":"B","text":"Educational status"},{"id":"C","text":"Infectivity of the agent"},{"id":"D","text":"Lifestyle such as tobacco use"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Availability of health services. Features of the built and physical environment—such as housing, walkability, crowding, water and pollution—are environmental determinants of health.","sourceLocations":[{"assessment":"Midterm","batch":"432","questionNumber":5,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Measures of Risk","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson3/section2.html"}],"lectureOrder":3,"referenceOrder":68005},{"id":"community-mid-principles-of-epidemiology-7429f891","subjectId":"community","lecture":"Principles of Epidemiology","assessment":"Midterm","sourceBatch":"432","sourceLabel":"Community Medicine Gift","stem":"In epidemiological triad which type of factors is the microbiological agent?","options":[{"id":"A","text":"Necessary factor"},{"id":"B","text":"Significant factor"},{"id":"C","text":"Precipitating factor"},{"id":"D","text":"Sufficient factor"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Necessary factor. A necessary cause must be present for the disease to occur, even though it may not be sufficient by itself.","sourceLocations":[{"assessment":"Midterm","batch":"432","questionNumber":6,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Measures of Risk","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson3/section2.html"}],"lectureOrder":3,"referenceOrder":68006},{"id":"community-mid-natural-history-of-disease-and-conce-46e15380","subjectId":"community","lecture":"Natural History of Disease and Concepts of Prevention and Control","assessment":"Midterm","sourceBatch":"432","sourceLabel":"Community Medicine Gift","stem":"What is the main object of preventing diseases at primary preventive level?","options":[{"id":"A","text":"Early recovery from disease"},{"id":"B","text":"Prevention of complication"},{"id":"C","text":"Reduction of mortality"},{"id":"D","text":"Reduction of recurrence of disease"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Reduction of recurrence of disease. Primary prevention acts during susceptibility, before pathologic changes or symptoms occur, through health promotion and specific protection.","sourceLocations":[{"assessment":"Midterm","batch":"432","questionNumber":11,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/index.html"}],"lectureOrder":1,"referenceOrder":68011},{"id":"community-mid-prevention-and-control-of-infectious-e5edb0ed","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"432","sourceLabel":"Community Medicine Gift","stem":"Which of the following public health measures is applied to susceptible hosts?","options":[{"id":"A","text":"Chemoprophylaxis"},{"id":"B","text":"Exclusion from work"},{"id":"C","text":"Isolation"},{"id":"D","text":"Reporting"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Chemoprophylaxis. Measures directed at susceptible hosts include immunization, chemoprophylaxis and improving host resistance; they do not remove the reservoir or route itself.","sourceLocations":[{"assessment":"Midterm","batch":"432","questionNumber":12,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":68012},{"id":"community-mid-prevention-and-control-of-infectious-98292214","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"432","sourceLabel":"Community Medicine Gift","stem":"What is the type of immunity acquired by an infant born to a fully immunized pregnant mother with tetanus toxoid?","options":[{"id":"A","text":"Artificial active immunity"},{"id":"B","text":"Artificial passive immunity"},{"id":"C","text":"Natural active immunity"},{"id":"D","text":"Natural passive immunity"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Natural passive immunity. Passive surveillance relies on routine reports sent by healthcare providers or laboratories; it is inexpensive but vulnerable to under-reporting.","sourceLocations":[{"assessment":"Midterm","batch":"432","questionNumber":14,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":68014},{"id":"community-mid-adolescent-and-child-health-abe8f9bb","subjectId":"community","lecture":"Adolescent and Child Health","assessment":"Midterm","sourceBatch":"432","sourceLabel":"Community Medicine Gift","stem":"A premature baby was admitted to the hospital and given antibiotic therapy for his severe illness. His mother mentioned that he is on breast- feeding and his vaccination is due this week. Which of the following is considered a contraindication to his vaccine?","options":[{"id":"A","text":"Antibiotic therapy"},{"id":"B","text":"Breast-feeding"},{"id":"C","text":"Prematurity"},{"id":"D","text":"Severe illness"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Severe illness. Illness is the person's subjective experience of feeling unwell; disease is a professionally identified pathology, and sickness is the social role or consequence attached to the condition.","sourceLocations":[{"assessment":"Midterm","batch":"432","questionNumber":15,"sourceType":"Gift"}],"references":[{"title":"WHO — Adolescent health","url":"https://www.who.int/health-topics/adolescent-health"}],"lectureOrder":10,"referenceOrder":68015},{"id":"community-mid-prevention-and-control-of-infectious-26310b48","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"432","sourceLabel":"Community Medicine Gift","stem":"Which one of the following is associated with a high risk of meningitis during mass gathering situation?","options":[{"id":"A","text":"Contaminated food"},{"id":"B","text":"Hot weather condition"},{"id":"C","text":"Insect bite"},{"id":"D","text":"Lack of vaccination"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Lack of vaccination. Crowding during mass gatherings increases droplet transmission of meningococcal disease, which is why destination-specific vaccination requirements apply.","sourceLocations":[{"assessment":"Midterm","batch":"432","questionNumber":17,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":68017},{"id":"community-mid-prevention-and-control-of-infectious-ba933483","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"432","sourceLabel":"Community Medicine Gift","stem":"What is the preventive measure that pilgrims should apply to avoid occurrence of blood borne infections?","options":[{"id":"A","text":"Avoid contaminated food"},{"id":"B","text":"Avoid insect bite"},{"id":"C","text":"Hand washing"},{"id":"D","text":"Use of disposable razors"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Use of disposable razors. Avoiding unsafe injections, razors and other blood-contaminated instruments reduces blood-borne infection risk during mass gatherings.","sourceLocations":[{"assessment":"Midterm","batch":"432","questionNumber":18,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":68018},{"id":"community-mid-prevention-and-control-of-infectious-f2e9c976","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"432","sourceLabel":"Community Medicine Gift","stem":"The following graph shows the distribution of 58 cases that were reported as salmonella outbreak in a wedding reception in Tabuk in 2012. What epidemic pattern is visible in this graph?","options":[{"id":"A","text":"Continuous"},{"id":"B","text":"Mixed"},{"id":"C","text":"Propagated"},{"id":"D","text":"Point-source"}],"images":["question-media/community/community-432-q20.jpg"],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Point-source. A shared exposure at one event produces a point-source outbreak, with cases concentrated within one incubation period.","sourceLocations":[{"assessment":"Midterm","batch":"432","questionNumber":20,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":68020},{"id":"community-mid-prevention-and-control-of-infectious-3315fcdc","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"432","sourceLabel":"Community Medicine Gift","stem":"What should a case definition in an outbreak investigation include?","options":[{"id":"A","text":"Clinical criteria, lab investigation, morbidity"},{"id":"B","text":"Clinical criteria, place, duration of outbreak"},{"id":"C","text":"Clinical criteria about previous outbreak and duration"},{"id":"D","text":"Clinical criteria restricted to person, place and time"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Clinical criteria restricted to person, place and time. An outbreak case definition normally specifies clinical criteria plus restrictions by person, place and time so cases are counted consistently.","sourceLocations":[{"assessment":"Midterm","batch":"432","questionNumber":21,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":68021},{"id":"community-mid-prevention-and-control-of-infectious-1db62e9b","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"432","sourceLabel":"Community Medicine Gift","stem":"In plotting the epidemic curve, against which one of the following the distribution of the cases is plotted?","options":[{"id":"A","text":"The incubation period"},{"id":"B","text":"Time of confirmation of diagnosis"},{"id":"C","text":"Time of diagnosis of cases"},{"id":"D","text":"Time of onset of symptoms"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Time of onset of symptoms. An epidemic curve plots the number of cases on the vertical axis against time of illness onset on the horizontal axis.","sourceLocations":[{"assessment":"Midterm","batch":"432","questionNumber":22,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":68022},{"id":"community-mid-prevention-and-control-of-infectious-cebc5953","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"432","sourceLabel":"Community Medicine Gift","stem":"There has been an outbreak of food poisoning in your locality and you were asked by MOH to conduct an investigation. You formulate a team, establish the existence of an outbreak, and verify the diagnosis. What is the next step?","options":[{"id":"A","text":"Formulate line listing"},{"id":"B","text":"Calculate the incidence"},{"id":"C","text":"Calculating prevalence"},{"id":"D","text":"Dissemination your finding"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Formulate line listing. After describing an outbreak by person, place and time, investigators formulate a testable hypothesis about the source and then evaluate it analytically.","sourceLocations":[{"assessment":"Midterm","batch":"432","questionNumber":23,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":68023},{"id":"community-mid-surveillance-and-screening-57ff944b","subjectId":"community","lecture":"Surveillance and Screening","assessment":"Midterm","sourceBatch":"432","sourceLabel":"Community Medicine Gift","stem":"What is the main function of a well running surveillance system?","options":[{"id":"A","text":"Classification of risk factors"},{"id":"B","text":"Collection of data on occasional basis"},{"id":"C","text":"Taking a timely action for unusual events"},{"id":"D","text":"Introducing tertiary prevention"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Taking a timely action for unusual events. Public-health surveillance is continuous, systematic collection, analysis, interpretation and dissemination of health data for action.","sourceLocations":[{"assessment":"Midterm","batch":"432","questionNumber":24,"sourceType":"Gift"}],"references":[{"title":"WHO — Screening programmes: a short guide","url":"https://www.who.int/publications/i/item/9789289054782"}],"lectureOrder":5,"referenceOrder":68024},{"id":"community-mid-surveillance-and-screening-97ed6c1a","subjectId":"community","lecture":"Surveillance and Screening","assessment":"Midterm","sourceBatch":"432","sourceLabel":"Community Medicine Gift","stem":"Which one of the following is an obstacle for obtaining high quality surveillance data?","options":[{"id":"A","text":"On time responsiveness"},{"id":"B","text":"Under reporting"},{"id":"C","text":"Use of active surveillance system"},{"id":"D","text":"Well-trained staff"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Under reporting. Under-reporting and poor service use make surveillance incomplete, biasing estimates downward and delaying outbreak detection.","sourceLocations":[{"assessment":"Midterm","batch":"432","questionNumber":25,"sourceType":"Gift"}],"references":[{"title":"WHO — Screening programmes: a short guide","url":"https://www.who.int/publications/i/item/9789289054782"}],"lectureOrder":5,"referenceOrder":68025},{"id":"community-mid-surveillance-and-screening-03400045","subjectId":"community","lecture":"Surveillance and Screening","assessment":"Midterm","sourceBatch":"432","sourceLabel":"Community Medicine Gift","stem":"Which one of the following can directly be achieved by establishing a breast cancer surveillance system for women in community settings?","options":[{"id":"A","text":"Estimating the prevalence of breast cancer"},{"id":"B","text":"Evaluation of quality"},{"id":"C","text":"Screening of breast cancer awareness among cases"},{"id":"D","text":"Updating educational material about breast cancer"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C (not sure)","aiAnswer":"A","aiSuggestion":"A population surveillance system directly measures disease occurrence and can estimate prevalence; the Gift tentatively records C.","verification":"conflict","explanation":"A surveillance system continuously collects and analyzes occurrence data, so it can directly estimate the prevalence and distribution of breast cancer. Awareness screening and educational-material updates are separate activities.","sourceLocations":[{"assessment":"Midterm","batch":"432","questionNumber":26,"sourceType":"Gift"}],"references":[{"title":"WHO — Screening programmes: a short guide","url":"https://www.who.int/publications/i/item/9789289054782"}],"lectureOrder":5,"referenceOrder":68026},{"id":"community-mid-prevention-and-control-of-infectious-2c794e22","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"432","sourceLabel":"Community Medicine Gift","stem":"Which of the following criteria is used by the communicable diseases reporting system to classify diseases?","options":[{"id":"A","text":"Ease to generate data"},{"id":"B","text":"Extent of communicability"},{"id":"C","text":"Rate of recovery"},{"id":"D","text":"Rate of complication"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B (not sure)","aiAnswer":"B","aiSuggestion":"Extent of communicability is a relevant criterion when prioritizing communicable diseases for mandatory reporting.","verification":"supported","explanation":"Communicable-disease reporting prioritization considers public-health importance and transmissibility. Among the choices, extent of communicability is the relevant classification criterion.","sourceLocations":[{"assessment":"Midterm","batch":"432","questionNumber":27,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":68027},{"id":"community-mid-surveillance-and-screening-facc79cf","subjectId":"community","lecture":"Surveillance and Screening","assessment":"Midterm","sourceBatch":"432","sourceLabel":"Community Medicine Gift","stem":"In screening test applied on 400 elderly with proven hearing impairment and 400 with no hearing impairment confirmed by audiometry. The test results positive in 100 of those with hearing impairment and 50 of those with no hearing impairment. What is the predictive value positive of this test?","options":[{"id":"A","text":"25%"},{"id":"B","text":"67%"},{"id":"C","text":"57%"},{"id":"D","text":"78%"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B , 100 / 150 = 0.667 = 67%","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is 67%. Secondary prevention detects disease early in apparently healthy people so timely treatment can reduce progression or complications.","sourceLocations":[{"assessment":"Midterm","batch":"432","questionNumber":29,"sourceType":"Gift"}],"references":[{"title":"WHO — Screening programmes: a short guide","url":"https://www.who.int/publications/i/item/9789289054782"}],"lectureOrder":5,"referenceOrder":68029},{"id":"community-mid-surveillance-and-screening-9dae69f1","subjectId":"community","lecture":"Surveillance and Screening","assessment":"Midterm","sourceBatch":"432","sourceLabel":"Community Medicine Gift","stem":"Which one of the following is most applicable for screening of health problems? It from subjects' request. It is basis for treatment","options":[{"id":"A","text":"Because there is a symptom"},{"id":"B","text":"It is not conclusive"},{"id":"C","text":"The following questions 32-33 are based on the finding of screening test results presented in the next table. It shows the results of 100,000 persons based on the clinical diagnosis and confirmed by biopsy:"},{"id":"D","text":"Table: Total | Biopsy negative | Biopsy positive | / / 1700 | 200 | 1500 | Positive clinical diagnosis / 98300 | 95800 | 2500 | Negative clinical diagnosis / 100,000 | 96000 | 4000 | Total"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Table: Total | Biopsy negative | Biopsy positive | / / 1700 | 200 | 1500 | Positive clinical diagnosis / 98300 | 95800 | 2500 | Negative clinical diagnosis / 100,000 | 96000 | 4000 | Total. Secondary prevention detects disease early in apparently healthy people so timely treatment can reduce progression or complications.","sourceLocations":[{"assessment":"Midterm","batch":"432","questionNumber":31,"sourceType":"Gift"}],"references":[{"title":"WHO — Screening programmes: a short guide","url":"https://www.who.int/publications/i/item/9789289054782"}],"lectureOrder":5,"referenceOrder":68031},{"id":"community-mid-surveillance-and-screening-a2e0bdd0","subjectId":"community","lecture":"Surveillance and Screening","assessment":"Midterm","sourceBatch":"432","sourceLabel":"Community Medicine Gift","stem":"What is the specificity?","options":[{"id":"A","text":"2500/98300"},{"id":"B","text":"200/96000"},{"id":"C","text":"95800/98300"},{"id":"D","text":"95800/96000"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is 95800/96000. Specificity is the proportion of people without the condition who test negative: TN/(TN+FP). A highly specific test therefore minimizes false positives.","sourceLocations":[{"assessment":"Midterm","batch":"432","questionNumber":32,"sourceType":"Gift"}],"references":[{"title":"WHO — Screening programmes: a short guide","url":"https://www.who.int/publications/i/item/9789289054782"}],"lectureOrder":5,"referenceOrder":68032},{"id":"community-mid-surveillance-and-screening-1e36bbb8","subjectId":"community","lecture":"Surveillance and Screening","assessment":"Midterm","sourceBatch":"432","sourceLabel":"Community Medicine Gift","stem":"What is the rate of false negative results?","options":[{"id":"A","text":"2500/4000"},{"id":"B","text":"200/96000"},{"id":"C","text":"1500/4000"},{"id":"D","text":"2500/98300"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is 2500/4000. The false-negative proportion among people who truly have disease is FN/(TP+FN), which also equals 1 minus sensitivity.","sourceLocations":[{"assessment":"Midterm","batch":"432","questionNumber":33,"sourceType":"Gift"}],"references":[{"title":"WHO — Screening programmes: a short guide","url":"https://www.who.int/publications/i/item/9789289054782"}],"lectureOrder":5,"referenceOrder":68033},{"id":"community-mid-adolescent-and-child-health-cf3423cd","subjectId":"community","lecture":"Adolescent and Child Health","assessment":"Midterm","sourceBatch":"432","sourceLabel":"Community Medicine Gift","stem":"What is the type of BCG vaccine?","options":[{"id":"A","text":"Live attenuated"},{"id":"B","text":"Inactivated"},{"id":"C","text":"Subunit"},{"id":"D","text":"Protein based"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Live attenuated. BCG is a live attenuated vaccine derived from Mycobacterium bovis and is administered intradermally.","sourceLocations":[{"assessment":"Midterm","batch":"432","questionNumber":34,"sourceType":"Gift"}],"references":[{"title":"WHO — Adolescent health","url":"https://www.who.int/health-topics/adolescent-health"}],"lectureOrder":10,"referenceOrder":68034},{"id":"community-mid-prevention-and-control-of-infectious-68a9f4f1","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"432","sourceLabel":"Community Medicine Gift","stem":"Which of the following age groups has the highest risk of developing chronic hepatitis B carrier state?","options":[{"id":"A","text":"Under 5 age"},{"id":"B","text":"Young adult"},{"id":"C","text":"Mid age"},{"id":"D","text":"Elderly"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Under 5 age. A carrier harbors the agent without apparent illness yet can transmit it, making detection and appropriate management important for control.","sourceLocations":[{"assessment":"Midterm","batch":"432","questionNumber":36,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":68036},{"id":"community-mid-prevention-and-control-of-infectious-c7abce04","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"432","sourceLabel":"Community Medicine Gift","stem":"What the type of hepatitis A vaccine?","options":[{"id":"A","text":"Inactivated toxoid vaccine"},{"id":"B","text":"Subunit vaccine"},{"id":"C","text":"Live attenuated vaccines"},{"id":"D","text":"Inactivated viral vaccines"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Inactivated viral vaccines. Hepatitis A vaccines used in routine practice are inactivated vaccines; they produce active immunity without live viral replication.","sourceLocations":[{"assessment":"Midterm","batch":"432","questionNumber":38,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":68038},{"id":"community-mid-prevention-and-control-of-infectious-b411b896","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"432","sourceLabel":"Community Medicine Gift","stem":"Which one of the following is preventive measure for hepatitis C?","options":[{"id":"A","text":"Control over food handlers"},{"id":"B","text":"Screening for blood donors"},{"id":"C","text":"Treatment of carriers"},{"id":"D","text":"Water sanitation"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Screening for blood donors. Secondary prevention detects disease early in apparently healthy people so timely treatment can reduce progression or complications.","sourceLocations":[{"assessment":"Midterm","batch":"432","questionNumber":39,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":68039},{"id":"community-mid-prevention-and-control-of-infectious-f985e1e3","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"432","sourceLabel":"Community Medicine Gift","stem":"Which one of the following is the current strategy for prevention of hepatitis A in KSA?","options":[{"id":"A","text":"Hand washing"},{"id":"B","text":"Use of disposable needles"},{"id":"C","text":"Infant vaccination"},{"id":"D","text":"Blood screening"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Hand washing. Hygiene, safe water and sanitation interrupt fecal–oral transmission and are central environmental controls for enteric infections.","sourceLocations":[{"assessment":"Midterm","batch":"432","questionNumber":40,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":68040},{"id":"community-mid-adolescent-and-child-health-7001f9c5","subjectId":"community","lecture":"Adolescent and Child Health","assessment":"Midterm","sourceBatch":"432","sourceLabel":"Community Medicine Gift","stem":"According to the compulsory vaccination schedule in Saudi Arabia, what is the time of the first dose HBV vaccination for infants?","options":[{"id":"A","text":"At birth"},{"id":"B","text":"2nd month"},{"id":"C","text":"6th month"},{"id":"D","text":"1 year"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is At birth. The first hepatitis B dose is scheduled at birth to reduce perinatal and early-childhood transmission; subsequent doses complete the primary series.","sourceLocations":[{"assessment":"Midterm","batch":"432","questionNumber":41,"sourceType":"Gift"}],"references":[{"title":"WHO — Adolescent health","url":"https://www.who.int/health-topics/adolescent-health"}],"lectureOrder":10,"referenceOrder":68041},{"id":"community-mid-prevention-and-control-of-infectious-9d8bf0b0","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"432","sourceLabel":"Community Medicine Gift","stem":"Influenza virus is characterized by the occurrence of a large number of cases in several countries and across continents at the same time. What is the pattern of the above-described occurrence?","options":[{"id":"A","text":"Epidemic"},{"id":"B","text":"Outbreak"},{"id":"C","text":"Pandemic"},{"id":"D","text":"Cluster"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Pandemic. A pandemic is an epidemic with sustained spread across multiple countries or continents, affecting a large number of people.","sourceLocations":[{"assessment":"Midterm","batch":"432","questionNumber":42,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":68042},{"id":"community-mid-global-demography-concepts-and-popul-88a20121","subjectId":"community","lecture":"Global Demography Concepts and Population Pyramid","assessment":"Midterm","sourceBatch":"432","sourceLabel":"Community Medicine Gift","stem":"Which one of the following is characteristic of the population pyramid of KSA in recent years?","options":[{"id":"A","text":"The base is narrow"},{"id":"B","text":"The median age is high"},{"id":"C","text":"The sides are steep"},{"id":"D","text":"Young dependency ratio is high"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Young dependency ratio is high. The dependency ratio compares younger and older dependants with the working-age population, usually expressed per 100 working-age people.","sourceLocations":[{"assessment":"Midterm","batch":"432","questionNumber":46,"sourceType":"Gift"}],"references":[{"title":"United Nations World Population Prospects","url":"https://www.un.org/development/desa/pd/content/world-population-prospects-2024"}],"lectureOrder":2,"referenceOrder":68046},{"id":"community-mid-global-demography-concepts-and-popul-b0792b12","subjectId":"community","lecture":"Global Demography Concepts and Population Pyramid","assessment":"Midterm","sourceBatch":"432","sourceLabel":"Community Medicine Gift","stem":"Which one of the following rates describes the number of children that would be born to a woman through her reproductive period?","options":[{"id":"A","text":"Crude birth rate"},{"id":"B","text":"General fertility rate"},{"id":"C","text":"Gross reproduction rate"},{"id":"D","text":"Total fertility rate"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Total fertility rate. Reliability is reproducibility: the indicator gives consistent results when measurement is repeated under comparable conditions.","sourceLocations":[{"assessment":"Midterm","batch":"432","questionNumber":47,"sourceType":"Gift"}],"references":[{"title":"United Nations World Population Prospects","url":"https://www.un.org/development/desa/pd/content/world-population-prospects-2024"}],"lectureOrder":2,"referenceOrder":68047},{"id":"community-mid-global-demography-concepts-and-popul-95e8f779","subjectId":"community","lecture":"Global Demography Concepts and Population Pyramid","assessment":"Midterm","sourceBatch":"432","sourceLabel":"Community Medicine Gift","stem":"According to the information provided by MOH in KSA, 1433, the estimated population growth rate was 1.87. If this rate remained constant, what will be the population doubling time?","options":[{"id":"A","text":"34"},{"id":"B","text":"36"},{"id":"C","text":"37"},{"id":"D","text":"39"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C - 70/1.87 = 37.4","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is 37. The rule of 70 estimates doubling time as 70 divided by the annual percentage growth rate; 70/1.87 is about 37 years.","sourceLocations":[{"assessment":"Midterm","batch":"432","questionNumber":48,"sourceType":"Gift"}],"references":[{"title":"United Nations World Population Prospects","url":"https://www.un.org/development/desa/pd/content/world-population-prospects-2024"}],"lectureOrder":2,"referenceOrder":68048},{"id":"community-mid-adolescent-and-child-health-0b0bd0cd","subjectId":"community","lecture":"Adolescent and Child Health","assessment":"Midterm","sourceBatch":"432","sourceLabel":"Community Medicine Gift","stem":"According to the MOH, in 1433 the number of infants death was 106,419, the mid year population was 29,195,895 and the total number of life births was 656,907. Calculate the infant mortality rate?","options":[{"id":"A","text":"162/1000"},{"id":"B","text":"132/1000"},{"id":"C","text":"145/1000"},{"id":"D","text":"166/1000"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A - 106419/656907 = 0.162 → 162/1000","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is 162/1000. Infant mortality uses deaths before age one in the numerator and live births in the denominator, conventionally expressed per 1,000 live births.","sourceLocations":[{"assessment":"Midterm","batch":"432","questionNumber":49,"sourceType":"Gift"}],"references":[{"title":"WHO — Adolescent health","url":"https://www.who.int/health-topics/adolescent-health"}],"lectureOrder":10,"referenceOrder":68049},{"id":"community-mid-global-demography-concepts-and-popul-9688a342","subjectId":"community","lecture":"Global Demography Concepts and Population Pyramid","assessment":"Midterm","sourceBatch":"432","sourceLabel":"Community Medicine Gift","stem":"According to demographic transition theory which of the following is characteristic of declining stage?","options":[{"id":"A","text":"Both birth and death rate are high"},{"id":"B","text":"Birth rate is higher than death rate"},{"id":"C","text":"Death rate is higher than birth rate"},{"id":"D","text":"Population growth rate equals zero"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Death rate is higher than birth rate. In demographic transition stage 5, the birth rate falls below the death rate, leading to population ageing and possible natural decrease.","sourceLocations":[{"assessment":"Midterm","batch":"432","questionNumber":50,"sourceType":"Gift"}],"references":[{"title":"United Nations World Population Prospects","url":"https://www.un.org/development/desa/pd/content/world-population-prospects-2024"}],"lectureOrder":2,"referenceOrder":68050},{"id":"community-mid-prevention-and-control-of-infectious-7fa8afee","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"432","sourceLabel":"Community Medicine Gift","stem":"Which one of the following is the primary intervention in malaria?","options":[{"id":"A","text":"Insecticide-treated bed nets"},{"id":"B","text":"Mass malaria vaccination"},{"id":"C","text":"Treat malaria in children"},{"id":"D","text":"Hand washing"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Insecticide-treated bed nets. Malaria prevention combines vector control—especially insecticide-treated nets and indoor residual spraying—with chemoprevention and prompt diagnosis where indicated.","sourceLocations":[{"assessment":"Midterm","batch":"432","questionNumber":51,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":68051},{"id":"community-mid-prevention-and-control-of-infectious-2f271ad9","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"431","sourceLabel":"Community Medicine Gift","stem":"What is the scientific term that describes the habitat in which an infectious agent normally lives, grows, and multiplies?","options":[{"id":"A","text":"Risk factor"},{"id":"B","text":"Reservoir"},{"id":"C","text":"Zoonosis"},{"id":"D","text":"Carrier"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Reservoir. A reservoir is the habitat in which an infectious agent normally lives, grows and multiplies; it is not always the same as the immediate source of exposure.","sourceLocations":[{"assessment":"Midterm","batch":"431","questionNumber":1,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":69001},{"id":"community-mid-prevention-and-control-of-infectious-78303ee1","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"431","sourceLabel":"Community Medicine Gift","stem":"What is the scientific term that describes the state of immunity of a group of people or a community?","options":[{"id":"A","text":"Herd immunity"},{"id":"B","text":"Active immunity"},{"id":"C","text":"Immunogenicity"},{"id":"D","text":"Passive immunity"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Herd immunity. Herd immunity is indirect community protection when enough people are immune to interrupt sustained transmission, helping protect those who cannot be immunized.","sourceLocations":[{"assessment":"Midterm","batch":"431","questionNumber":2,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":69002},{"id":"community-mid-prevention-and-control-of-infectious-14b09e55","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"431","sourceLabel":"Community Medicine Gift","stem":"How can the infectivity of infectious disease be defined?","options":[{"id":"A","text":"The ability of the organism to produce specific immunity"},{"id":"B","text":"The ability of an infectious agent to cause severe disease"},{"id":"C","text":"The ability of an organism to produce specific clinical reaction"},{"id":"D","text":"The ability of the germs to invade and multiply in a susceptible host"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is The ability of the germs to invade and multiply in a susceptible host. Infectivity is an agent's ability to enter, survive and multiply in a susceptible host; it differs from pathogenicity and virulence.","sourceLocations":[{"assessment":"Midterm","batch":"431","questionNumber":3,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":69003},{"id":"community-mid-prevention-and-control-of-infectious-3afaec43","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"431","sourceLabel":"Community Medicine Gift","stem":"Which of the following is primarily a zoonotic disease ?","options":[{"id":"A","text":"Rabies"},{"id":"B","text":"Measles"},{"id":"C","text":"Hepatitis A"},{"id":"D","text":"Polio"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Rabies. A zoonosis is naturally transmitted between vertebrate animals and humans; whether onward human-to-human spread occurs depends on the specific agent.","sourceLocations":[{"assessment":"Midterm","batch":"431","questionNumber":4,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":69004},{"id":"community-mid-prevention-and-control-of-infectious-a49d0c92","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"431","sourceLabel":"Community Medicine Gift","stem":"Which one of the following represents indirect mode of transmission ?","options":[{"id":"A","text":"Sneeze causing infection"},{"id":"B","text":"Mosquito bite causing malaria"},{"id":"C","text":"Bite of an animal having rabies"},{"id":"D","text":"Trans-placental transmission of HIV"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Mosquito bite causing malaria. Measures aimed at the transmission route include sanitation, disinfection, ventilation, vector control and safe food, water or injection practices, depending on the agent.","sourceLocations":[{"assessment":"Midterm","batch":"431","questionNumber":5,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":69005},{"id":"community-mid-prevention-and-control-of-infectious-e1f60213","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"431","sourceLabel":"Community Medicine Gift","stem":"How can pathogenicity of an infectious agent be measured?","options":[{"id":"A","text":"Case fertility rate"},{"id":"B","text":"Secondary attack frequency"},{"id":"C","text":"Ratio of clinical to subclinical case"},{"id":"D","text":"Secondary attack rate"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Ratio of clinical to subclinical case. Pathogenicity is the ability of an agent to cause clinical disease among infected hosts; virulence describes the severity of resulting disease.","sourceLocations":[{"assessment":"Midterm","batch":"431","questionNumber":6,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":69006},{"id":"community-mid-prevention-and-control-of-infectious-e5e92d81","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"431","sourceLabel":"Community Medicine Gift","stem":"During last week, Mona had measles. She received a sick leave from school. For how long should Mona be kept away from school?","options":[{"id":"A","text":"The period of communicability"},{"id":"B","text":"The longest incubation period"},{"id":"C","text":"The extrinsic incubation period"},{"id":"D","text":"Until the time she fully recovers"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is The period of communicability. The period of communicability is the interval during which an infected person can transmit the agent, which determines the necessary exclusion or isolation period.","sourceLocations":[{"assessment":"Midterm","batch":"431","questionNumber":7,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":69007},{"id":"community-mid-prevention-and-control-of-infectious-6136e9ae","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"431","sourceLabel":"Community Medicine Gift","stem":"What is the appropriate measure towards carriers of communicable disease?","options":[{"id":"A","text":"Surveillance"},{"id":"B","text":"Vaccination"},{"id":"C","text":"Exclusion from certain jobs"},{"id":"D","text":"Isolation away from the community"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Exclusion from certain jobs. A carrier harbors the agent without apparent illness yet can transmit it, making detection and appropriate management important for control.","sourceLocations":[{"assessment":"Midterm","batch":"431","questionNumber":8,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":69008},{"id":"community-mid-prevention-and-control-of-infectious-2f0e1410","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"431","sourceLabel":"Community Medicine Gift","stem":"Which of the following public health actions targets the mode of transmission?","options":[{"id":"A","text":"Vaccination"},{"id":"B","text":"Vector control"},{"id":"C","text":"Sero-prophylaxis"},{"id":"D","text":"Chemoprophylaxis"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Vector control. Measures aimed at the transmission route include sanitation, disinfection, ventilation, vector control and safe food, water or injection practices, depending on the agent.","sourceLocations":[{"assessment":"Midterm","batch":"431","questionNumber":9,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":69009},{"id":"community-mid-principles-of-epidemiology-ffea977c","subjectId":"community","lecture":"Principles of Epidemiology","assessment":"Midterm","sourceBatch":"431","sourceLabel":"Community Medicine Gift","stem":"What are the components of the analytical Epidemiologic Triad model?","options":[{"id":"A","text":"Frequency, distribution and determinants"},{"id":"B","text":"Host, agent and environment"},{"id":"C","text":"Person, place, time"},{"id":"D","text":"Mortality, fertility and migration"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Host, agent and environment. The epidemiologic triad organizes causation into agent, host and environment; changing any one can alter whether disease occurs.","sourceLocations":[{"assessment":"Midterm","batch":"431","questionNumber":10,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Measures of Risk","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson3/section2.html"}],"lectureOrder":3,"referenceOrder":69010},{"id":"community-mid-natural-history-of-disease-and-conce-6c93242d","subjectId":"community","lecture":"Natural History of Disease and Concepts of Prevention and Control","assessment":"Midterm","sourceBatch":"431","sourceLabel":"Community Medicine Gift","stem":"Which one of the following is a primary level of prevention for tuberculosis?","options":[{"id":"A","text":"BCG vaccination"},{"id":"B","text":"Tuberculosis screening"},{"id":"C","text":"Psychological rehabilitation"},{"id":"D","text":"Treatment of tuberculosis patient"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is BCG vaccination. Primary prevention of tuberculosis aims to prevent infection or disease before onset through measures such as BCG for eligible groups, infection control and risk reduction.","sourceLocations":[{"assessment":"Midterm","batch":"431","questionNumber":11,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/index.html"}],"lectureOrder":1,"referenceOrder":69011},{"id":"community-mid-prevention-and-control-of-infectious-2afe6dc9","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"431","sourceLabel":"Community Medicine Gift","stem":"What is the recommended duration of isolation for travelers arriving from an endemic area for a quarantinable disease?","options":[{"id":"A","text":"The whole duration of the epidemic"},{"id":"B","text":"The longest incubation period of the disease"},{"id":"C","text":"The period of communicability of that disease"},{"id":"D","text":"The period for which the patient is under treatment"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is The longest incubation period of the disease. Isolation separates infectious cases during the period of communicability to reduce exposure of susceptible contacts.","sourceLocations":[{"assessment":"Midterm","batch":"431","questionNumber":12,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":69012},{"id":"community-mid-natural-history-of-disease-and-conce-d70014b3","subjectId":"community","lecture":"Natural History of Disease and Concepts of Prevention and Control","assessment":"Midterm","sourceBatch":"431","sourceLabel":"Community Medicine Gift","stem":"Which of the following describes the progress of a disease in an individual over time, in the absence of any intervention?","options":[{"id":"A","text":"Natural history of the disease"},{"id":"B","text":"Spectrum of the disease"},{"id":"C","text":"Subclinical stage of the disease"},{"id":"D","text":"Disease pathogenicity"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Natural history of the disease. Natural history describes how a disease progresses from susceptibility through subclinical and clinical stages to recovery, disability or death without intervention.","sourceLocations":[{"assessment":"Midterm","batch":"431","questionNumber":13,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/index.html"}],"lectureOrder":1,"referenceOrder":69013},{"id":"community-mid-natural-history-of-disease-and-conce-83a3c1c8","subjectId":"community","lecture":"Natural History of Disease and Concepts of Prevention and Control","assessment":"Midterm","sourceBatch":"431","sourceLabel":"Community Medicine Gift","stem":"For some of the diseases only a few cases are identified while many others are hidden and stay unidentified. What is this situation called?","options":[{"id":"A","text":"Natural history of the disease"},{"id":"B","text":"Spectrum of the disease"},{"id":"C","text":"Iceberg phenomena"},{"id":"D","text":"Epidemic"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Iceberg phenomena. The visible diagnosed cases are the tip of the iceberg, while undiagnosed, subclinical or carrier states form the much larger hidden portion.","sourceLocations":[{"assessment":"Midterm","batch":"431","questionNumber":14,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/index.html"}],"lectureOrder":1,"referenceOrder":69014},{"id":"community-mid-prevention-and-control-of-infectious-2c78dc00","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"431","sourceLabel":"Community Medicine Gift","stem":"While providing health care for hepatitis B patients, a nurse was exposed to needle stick injury. She was given immunoglobulin and vaccination for Hepatitis B. What is the type of immunity she would acquire through her hepatitis B vaccine? Artificial active immunity","options":[{"id":"A","text":"Artificial passive immunity"},{"id":"B","text":"Natural active immunity"},{"id":"C","text":"Natural passive immunity"},{"id":"D","text":"The killed vaccine gives artificial active immunity."}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Artificial passive immunity. Passive surveillance relies on routine reports sent by healthcare providers or laboratories; it is inexpensive but vulnerable to under-reporting.","sourceLocations":[{"assessment":"Midterm","batch":"431","questionNumber":15,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":69015},{"id":"community-mid-prevention-and-control-of-infectious-30a3bb61","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"431","sourceLabel":"Community Medicine Gift","stem":"Which of the following best explains the statement “ vaccine is antigenic but not pathogenic” ?","options":[{"id":"A","text":"Vaccine can cause mild fever"},{"id":"B","text":"Vaccine produces immune response but does not cause illness"},{"id":"C","text":"Vaccine cause mild disease which in turn provide immunity"},{"id":"D","text":"Vaccine induce less immunity compared to the immunity induced by the disease"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Vaccine produces immune response but does not cause illness. Illness is the person's subjective experience of feeling unwell; disease is a professionally identified pathology, and sickness is the social role or consequence attached to the condition.","sourceLocations":[{"assessment":"Midterm","batch":"431","questionNumber":16,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":69016},{"id":"community-mid-adolescent-and-child-health-d72277a5","subjectId":"community","lecture":"Adolescent and Child Health","assessment":"Midterm","sourceBatch":"431","sourceLabel":"Community Medicine Gift","stem":"At a vaccine session at a clinic , a mother told the doctor that her baby is a little unwell today and asked if it is ok to vaccinate the baby. What is the true contraindications to vaccination?","options":[{"id":"A","text":"Breastfeeding"},{"id":"B","text":"High grade fever"},{"id":"C","text":"Premature birth"},{"id":"D","text":"Antibiotic therapy"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is High grade fever. A mild illness without significant fever is generally not a contraindication to routine vaccination; unnecessary delay leaves the child susceptible.","sourceLocations":[{"assessment":"Midterm","batch":"431","questionNumber":17,"sourceType":"Gift"}],"references":[{"title":"WHO — Adolescent health","url":"https://www.who.int/health-topics/adolescent-health"}],"lectureOrder":10,"referenceOrder":69017},{"id":"community-mid-prevention-and-control-of-infectious-4e8f0420","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"431","sourceLabel":"Community Medicine Gift","stem":"Which is the reason that makes vaccines generally very safe?","options":[{"id":"A","text":"Vaccines are given in small doses only"},{"id":"B","text":"Vaccine contain anti allergic substance"},{"id":"C","text":"Vaccines contain weakened or dead microorganisms"},{"id":"D","text":"Vaccine contain those strains of microorganisms which do not cause disease"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Vaccines contain weakened or dead microorganisms. Vaccines expose the immune system to antigen without causing the full natural disease; safety is established through testing and ongoing surveillance.","sourceLocations":[{"assessment":"Midterm","batch":"431","questionNumber":18,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":69018},{"id":"community-mid-adolescent-and-child-health-8ab50fb0","subjectId":"community","lecture":"Adolescent and Child Health","assessment":"Midterm","sourceBatch":"431","sourceLabel":"Community Medicine Gift","stem":"One of the new vaccines introduced to the Compulsory Vaccination Schedule in KSA is the Rotavirus vaccine. What is the routes of administration of this vaccine:","options":[{"id":"A","text":"Orally"},{"id":"B","text":"Intradermal"},{"id":"C","text":"Intramuscular"},{"id":"D","text":"Subcutaneous"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Orally. Rotavirus vaccine is administered orally, allowing mucosal immunization of the gastrointestinal tract.","sourceLocations":[{"assessment":"Midterm","batch":"431","questionNumber":19,"sourceType":"Gift"}],"references":[{"title":"WHO — Adolescent health","url":"https://www.who.int/health-topics/adolescent-health"}],"lectureOrder":10,"referenceOrder":69019},{"id":"community-mid-adolescent-and-child-health-689b2426","subjectId":"community","lecture":"Adolescent and Child Health","assessment":"Midterm","sourceBatch":"431","sourceLabel":"Community Medicine Gift","stem":"According to the compulsory vaccination schedule in Saudi Arabia, what is the time of BCG vaccination to infants?","options":[{"id":"A","text":"At birth."},{"id":"B","text":"2nd month."},{"id":"C","text":"9th month."},{"id":"D","text":"12th month"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is At birth.. BCG timing is taken from the Saudi national immunization schedule used in the course; schedules can change, so the current MOH table should be checked for clinical use.","sourceLocations":[{"assessment":"Midterm","batch":"431","questionNumber":20,"sourceType":"Gift"}],"references":[{"title":"WHO — Adolescent health","url":"https://www.who.int/health-topics/adolescent-health"}],"lectureOrder":10,"referenceOrder":69020},{"id":"community-mid-prevention-and-control-of-infectious-b347e6f3","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"431","sourceLabel":"Community Medicine Gift","stem":"What type of vaccine is used in a campaign against Measles, German measles and Mumps for college students?","options":[{"id":"A","text":"Killed Vaccine"},{"id":"B","text":"Subunit vaccine"},{"id":"C","text":"Inactivated vaccine"},{"id":"D","text":"Live-attenuated vaccine"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Live-attenuated vaccine. Measles-containing vaccines such as MMR are live attenuated vaccines; the schedule and contraindications must follow the current national programme.","sourceLocations":[{"assessment":"Midterm","batch":"431","questionNumber":21,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":69021},{"id":"community-mid-maternal-health-dc1631f2","subjectId":"community","lecture":"Maternal Health","assessment":"Midterm","sourceBatch":"431","sourceLabel":"Community Medicine Gift","stem":"A pregnant lady came to the antenatal care clinic for follow up. After receiving a routine check up, she was referred to the vaccination clinic. Which one of the following vaccines is recommended in pregnancy?","options":[{"id":"A","text":"Oral polio vaccine"},{"id":"B","text":"Tetanus toxoid vaccine"},{"id":"C","text":"German measles vaccine"},{"id":"D","text":"Rotavirus vaccine"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Tetanus toxoid vaccine. Inactivated vaccines recommended for maternal protection can be given during pregnancy when indicated; live attenuated vaccines are generally contraindicated.","sourceLocations":[{"assessment":"Midterm","batch":"431","questionNumber":22,"sourceType":"Gift"}],"references":[{"title":"WHO — Maternal health","url":"https://www.who.int/health-topics/maternal-health"}],"lectureOrder":11,"referenceOrder":69022},{"id":"community-mid-surveillance-and-screening-6cbc7e6e","subjectId":"community","lecture":"Surveillance and Screening","assessment":"Midterm","sourceBatch":"431","sourceLabel":"Community Medicine Gift","stem":"What is the purpose of the surveillance in public health?","options":[{"id":"A","text":"To describe classification of disease risk factors"},{"id":"B","text":"To identify disease registration method"},{"id":"C","text":"To identify variations in case definition of a disease"},{"id":"D","text":"To observe sudden changes in disease incidence"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is To observe sudden changes in disease incidence. Incidence counts new cases arising in an at-risk population during a stated period, so it measures risk or the rate of developing disease.","sourceLocations":[{"assessment":"Midterm","batch":"431","questionNumber":24,"sourceType":"Gift"}],"references":[{"title":"WHO — Screening programmes: a short guide","url":"https://www.who.int/publications/i/item/9789289054782"}],"lectureOrder":5,"referenceOrder":69024},{"id":"community-mid-surveillance-and-screening-b10ee4b4","subjectId":"community","lecture":"Surveillance and Screening","assessment":"Midterm","sourceBatch":"431","sourceLabel":"Community Medicine Gift","stem":"Which of the following factors hinders collection of high quality data in public health surveillance ?","options":[{"id":"A","text":"Application of case definitions"},{"id":"B","text":"Reporting most cases of notifiable diseases"},{"id":"C","text":"Motivation of health care providers"},{"id":"D","text":"Poor utilization of public health services"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Poor utilization of public health services. Under-reporting and poor service use make surveillance incomplete, biasing estimates downward and delaying outbreak detection.","sourceLocations":[{"assessment":"Midterm","batch":"431","questionNumber":25,"sourceType":"Gift"}],"references":[{"title":"WHO — Screening programmes: a short guide","url":"https://www.who.int/publications/i/item/9789289054782"}],"lectureOrder":5,"referenceOrder":69025},{"id":"community-mid-surveillance-and-screening-510d4ac0","subjectId":"community","lecture":"Surveillance and Screening","assessment":"Midterm","sourceBatch":"431","sourceLabel":"Community Medicine Gift","stem":"Which of the following is used to classify diseases for the purpose of public health surveillance ?","options":[{"id":"A","text":"Incidence"},{"id":"B","text":"Prevalence"},{"id":"C","text":"Communicability"},{"id":"D","text":"Easiness to generate data"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Communicability. Diseases are prioritized for surveillance using public-health importance, epidemic potential, preventability and the feasibility or legal need for reporting.","sourceLocations":[{"assessment":"Midterm","batch":"431","questionNumber":26,"sourceType":"Gift"}],"references":[{"title":"WHO — Screening programmes: a short guide","url":"https://www.who.int/publications/i/item/9789289054782"}],"lectureOrder":5,"referenceOrder":69026},{"id":"community-mid-surveillance-and-screening-4842d2c1","subjectId":"community","lecture":"Surveillance and Screening","assessment":"Midterm","sourceBatch":"431","sourceLabel":"Community Medicine Gift","stem":"An unknown new disease appeared in a city starting with fever, sore throat, bleeding from several sites resulting in a quick death. Which of the following would you follow in setting up a surveillance system for such disease ?","options":[{"id":"A","text":"Hire a team to treat this disease and inform the newspaper and television"},{"id":"B","text":"Appoint a research team to initiate research for the unknown new disease"},{"id":"C","text":"Develop a case definition for health care providers to report this disease"},{"id":"D","text":"Prepare guidelines to prevent this disease and circulate to all hospitals in the city"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Develop a case definition for health care providers to report this disease. Occupational hepatitis B transmission occurs mainly through percutaneous or mucosal exposure to infected blood, such as a needlestick injury.","sourceLocations":[{"assessment":"Midterm","batch":"431","questionNumber":27,"sourceType":"Gift"}],"references":[{"title":"WHO — Screening programmes: a short guide","url":"https://www.who.int/publications/i/item/9789289054782"}],"lectureOrder":5,"referenceOrder":69027},{"id":"community-mid-prevention-and-control-of-infectious-4a14ee49","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"431","sourceLabel":"Community Medicine Gift","stem":"Ministry of health (MOH) required that health care providers report notifiable diseases. For this purpose, MOH provide a list of notifiable diseases. Which of the following steps health care providers should follow ?","options":[{"id":"A","text":"Identify high risk populations and setting up of early warning system"},{"id":"B","text":"Isolation suspected cases, perform diagnostic tests, and refer to hospitals"},{"id":"C","text":"Detect the outbreak of disease and communicate results to international health authorities"},{"id":"D","text":"Recognize and identify reportable diseases and report to local health authorities"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Recognize and identify reportable diseases and report to local health authorities. Occupational hepatitis B transmission occurs mainly through percutaneous or mucosal exposure to infected blood, such as a needlestick injury.","sourceLocations":[{"assessment":"Midterm","batch":"431","questionNumber":28,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":69028},{"id":"community-mid-surveillance-and-screening-4e5f6761","subjectId":"community","lecture":"Surveillance and Screening","assessment":"Midterm","sourceBatch":"431","sourceLabel":"Community Medicine Gift","stem":"Which of the following describes a difference between survey and surveillance?","options":[{"id":"A","text":"Survey monitors long term trends whereas surveillance informs about patterns of disease occurrence"},{"id":"B","text":"Survey provides data for new cases of diseases whereas surveillance provides history of old and new cases of disease"},{"id":"C","text":"Survey is time consuming while surveillance is relatively quick"},{"id":"D","text":"Survey is a one time activity and surveillance is an ongoing collection of data"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Survey is a one time activity and surveillance is an ongoing collection of data. Surveillance is continuous, systematic collection, analysis, interpretation and dissemination for public-health action; a survey is time-limited.","sourceLocations":[{"assessment":"Midterm","batch":"431","questionNumber":29,"sourceType":"Gift"}],"references":[{"title":"WHO — Screening programmes: a short guide","url":"https://www.who.int/publications/i/item/9789289054782"}],"lectureOrder":5,"referenceOrder":69029},{"id":"community-mid-prevention-and-control-of-infectious-1b76f528","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"431","sourceLabel":"Community Medicine Gift","stem":"Which of the following defines disease outbreak ?","options":[{"id":"A","text":"An aggregation of cases in an area"},{"id":"B","text":"Occurrence of a more serious form of the disease"},{"id":"C","text":"Occurrence of more than usual number of cases of a disease"},{"id":"D","text":"Occurrence of expected number of cases of disease in a population group"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Occurrence of more than usual number of cases of a disease. An outbreak is occurrence of cases above the number normally expected in a defined place, population and period.","sourceLocations":[{"assessment":"Midterm","batch":"431","questionNumber":30,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":69030},{"id":"community-mid-prevention-and-control-of-infectious-7c6cf5c2","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"431","sourceLabel":"Community Medicine Gift","stem":"The following graph shows the cases that were reported in a measles outbreak. What epidemic pattern is visible in this graph ?","options":[{"id":"A","text":"A propagated source"},{"id":"B","text":"A common single-point source"},{"id":"C","text":"A common continuous source"},{"id":"D","text":"Common and propagated source"}],"images":["question-media/community/community-431-q31.jpg"],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is A propagated source. A propagated epidemic curve shows successive waves as infection spreads person to person, often separated by roughly one incubation period.","sourceLocations":[{"assessment":"Midterm","batch":"431","questionNumber":31,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":69031},{"id":"community-mid-prevention-and-control-of-infectious-f32a85b4","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"431","sourceLabel":"Community Medicine Gift","stem":"There has been an outbreak of food poisoning in your locality and you have been asked by the Ministry of Health to conduct an investigation to find the source of infection. You formulate a team, establish the existence of an outbreak, and verify the diagnosis by laboratory testing. What is the next step to be done ?","options":[{"id":"A","text":"Formulating a line listing"},{"id":"B","text":"Calculating the incidence"},{"id":"C","text":"Calculating the prevalence"},{"id":"D","text":"Disseminating your findings"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Formulating a line listing. After describing an outbreak by person, place and time, investigators formulate a testable hypothesis about the source and then evaluate it analytically.","sourceLocations":[{"assessment":"Midterm","batch":"431","questionNumber":32,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":69032},{"id":"community-mid-surveillance-and-screening-0e90e390","subjectId":"community","lecture":"Surveillance and Screening","assessment":"Midterm","sourceBatch":"431","sourceLabel":"Community Medicine Gift","stem":"What is the aim of loose case definition early in an outbreak investigation ?","options":[{"id":"A","text":"Generate a hypothesis"},{"id":"B","text":"Increase the yield of case finding"},{"id":"C","text":"Identify the exact extent of the outbreak"},{"id":"D","text":"Collect more information about cases"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Increase the yield of case finding. An intentionally sensitive early case definition captures more possible cases during an emerging outbreak, accepting more false positives for better case finding.","sourceLocations":[{"assessment":"Midterm","batch":"431","questionNumber":33,"sourceType":"Gift"}],"references":[{"title":"WHO — Screening programmes: a short guide","url":"https://www.who.int/publications/i/item/9789289054782"}],"lectureOrder":5,"referenceOrder":69033},{"id":"community-mid-prevention-and-control-of-infectious-6b5932c0","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"431","sourceLabel":"Community Medicine Gift","stem":"Among those who develop hepatitis B infection, who is more prone to develop CHRONIC hepatitis ?","options":[{"id":"A","text":"Infants"},{"id":"B","text":"Elderly"},{"id":"C","text":"Young adults"},{"id":"D","text":"Pregnant women"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Infants. Developmental milestones are assessed by age and by domains such as gross motor, fine motor, language and social skills; sitting with support at six months is generally age-appropriate.","sourceLocations":[{"assessment":"Midterm","batch":"431","questionNumber":34,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":69034},{"id":"community-mid-prevention-and-control-of-infectious-aae45b3f","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"431","sourceLabel":"Community Medicine Gift","stem":"Which one of the following is a preventive measure for hepatitis C viral infection ?","options":[{"id":"A","text":"Universal vaccination"},{"id":"B","text":"Treatment of patients"},{"id":"C","text":"Screening of blood donors"},{"id":"D","text":"Inspection of food handlers"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Screening of blood donors. Secondary prevention detects disease early in apparently healthy people so timely treatment can reduce progression or complications.","sourceLocations":[{"assessment":"Midterm","batch":"431","questionNumber":36,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":69036},{"id":"community-mid-prevention-and-control-of-infectious-0ebd484d","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"431","sourceLabel":"Community Medicine Gift","stem":"Which one of the following is the current strategy for prevention of viral for hepatitis A in KSA ?","options":[{"id":"A","text":"Avoid tattooing"},{"id":"B","text":"Screening of blood donors"},{"id":"C","text":"Universal infant vaccination"},{"id":"D","text":"Prevention of sexual transmission"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Universal infant vaccination. Hepatitis A prevention combines vaccination with safe water, sanitation, food hygiene and hand hygiene; blood-borne precautions address other hepatitis viruses.","sourceLocations":[{"assessment":"Midterm","batch":"431","questionNumber":37,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":69037},{"id":"community-mid-prevention-and-control-of-infectious-521d87b8","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"431","sourceLabel":"Community Medicine Gift","stem":"What is the most important mode of transmission of TB ?","options":[{"id":"A","text":"Vector-borne"},{"id":"B","text":"Direct contact"},{"id":"C","text":"Air-borne droplets"},{"id":"D","text":"Sexual transmission"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Air-borne droplets. Measures aimed at the transmission route include sanitation, disinfection, ventilation, vector control and safe food, water or injection practices, depending on the agent.","sourceLocations":[{"assessment":"Midterm","batch":"431","questionNumber":39,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":69039},{"id":"community-mid-prevention-and-control-of-infectious-76976e54","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"431","sourceLabel":"Community Medicine Gift","stem":"Which of the following sets includes the extrinsic risk factors for acquiring TB?","options":[{"id":"A","text":"HIV, diabetes mellitus, liver disease"},{"id":"B","text":"Latent TB , silicosis, vitamin D deficiency"},{"id":"C","text":"Poverty, crowding, poor health care"},{"id":"D","text":"Drug use, alcohol drinking and smoking"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Poverty, crowding, poor health care. Extrinsic tuberculosis risks arise from the social or physical environment—such as poverty, crowding and poor access to care—rather than from host biology.","sourceLocations":[{"assessment":"Midterm","batch":"431","questionNumber":40,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":69040},{"id":"community-mid-prevention-and-control-of-infectious-c3691bbb","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"431","sourceLabel":"Community Medicine Gift","stem":"WHO has conducted surveys in many countries to determine the disease burden of TB and to set goals for its reduction. Which of the following is a major burner to achieve TB control?","options":[{"id":"A","text":"Health care workers are at high risk due to direct patient contact"},{"id":"B","text":"Insufficient case detection and disease notification for disease"},{"id":"C","text":"There are specific ethnic groups which have high incidence of disease"},{"id":"D","text":"High prevalence of disease mainly in older persons in developing countries"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Insufficient case detection and disease notification for disease. Insufficient case detection and notification allow infectious tuberculosis to remain untreated in the community and are major barriers to control.","sourceLocations":[{"assessment":"Midterm","batch":"431","questionNumber":41,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":69041},{"id":"community-mid-prevention-and-control-of-infectious-85b9ec11","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"431","sourceLabel":"Community Medicine Gift","stem":"What is the epidemiological characteristic pattern of an influenza pandemic?","options":[{"id":"A","text":"Single wave globally"},{"id":"B","text":"Increase attack rate among all age groups"},{"id":"C","text":"Starts from multiple geographic areas"},{"id":"D","text":"Case fatality is increase considerably"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Increase attack rate among all age groups. For each food, compare the attack rate among those who ate it with the attack rate among those who did not. The highest risk ratio points to the most likely vehicle; the lowest argues against it.","sourceLocations":[{"assessment":"Midterm","batch":"431","questionNumber":42,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":69042},{"id":"community-mid-disparities-in-health-82a89fae","subjectId":"community","lecture":"Disparities in Health","assessment":"Midterm","sourceBatch":"431","sourceLabel":"Community Medicine Gift","stem":"In a particular month in a community, \" the total number of influenza cases was 1000, out of whom 30 people died\". Which of the following conclusion could be made on the basis of this information?","options":[{"id":"A","text":"Influenza Mortality rate is 3%."},{"id":"B","text":"Influenza Morbidity rate is 3%."},{"id":"C","text":"Influenza Incidence is 3%."},{"id":"D","text":"Influenza Case fatality rate is 3%"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Influenza Case fatality rate is 3%. Case fatality is deaths among diagnosed cases divided by all cases of that disease; it describes severity rather than population risk.","sourceLocations":[{"assessment":"Midterm","batch":"431","questionNumber":43,"sourceType":"Gift"}],"references":[{"title":"WHO — Health inequities and their causes","url":"https://www.who.int/news-room/facts-in-pictures/detail/health-inequities-and-their-causes"}],"lectureOrder":8,"referenceOrder":69043},{"id":"community-mid-prevention-and-control-of-infectious-f9371361","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"431","sourceLabel":"Community Medicine Gift","stem":"During 2009, a large number of cases of influenza A H1N1 occurred in several countries and across continents at the same time. What is this pattern of occurrence known as ?","options":[{"id":"A","text":"Outbreak."},{"id":"B","text":"Endemic."},{"id":"C","text":"Pandemic."},{"id":"D","text":"Epidemic."}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Pandemic.. A pandemic is an epidemic with sustained spread across multiple countries or continents, affecting a large number of people.","sourceLocations":[{"assessment":"Midterm","batch":"431","questionNumber":46,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":69046},{"id":"community-mid-prevention-and-control-of-infectious-b0971c66","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"431","sourceLabel":"Community Medicine Gift","stem":"What is the most acceptable method for prevention of sexual transmission of HIV/AIDS in the eastern Mediterranean region?","options":[{"id":"A","text":"Promoting condom use."},{"id":"B","text":"Following religious teachings."},{"id":"C","text":"Screening measures in blood banks."},{"id":"D","text":"Offering premarital counseling."}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B (according to the slides)","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Following religious teachings.. The recorded answer follows the course's culturally framed prevention hierarchy; medically, comprehensive HIV prevention combines effective barrier protection, testing, treatment and risk-reduction counselling.","sourceLocations":[{"assessment":"Midterm","batch":"431","questionNumber":47,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":69047},{"id":"community-mid-prevention-and-control-of-infectious-3bdcda3f","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"431","sourceLabel":"Community Medicine Gift","stem":"What's currently the most important mode of transmission of HIV/AIDS in Eastern Mediterranean region?","options":[{"id":"A","text":"Heterosexual"},{"id":"B","text":"Homosexual"},{"id":"C","text":"Blood transfusion"},{"id":"D","text":"Intravenous drug use"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Heterosexual. Measures aimed at the transmission route include sanitation, disinfection, ventilation, vector control and safe food, water or injection practices, depending on the agent.","sourceLocations":[{"assessment":"Midterm","batch":"431","questionNumber":48,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":69048},{"id":"community-mid-prevention-and-control-of-infectious-bb1a4756","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"431","sourceLabel":"Community Medicine Gift","stem":"Why Eastern Mediterranean region need to be on high alert with regards to potential HIV/AIDS transmission?","options":[{"id":"A","text":"The region is protected by its traditions and Beliefs."},{"id":"B","text":"The region shares borders with highly infected nations"},{"id":"C","text":"HIV/AIDS risk factors are highly prevalent within the region."},{"id":"D","text":"The region has high rates of sexually transmitted infections among its inhabitants."}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is The region shares borders with highly infected nations. HIV transmission patterns vary by population and period; the keyed answer reflects the course epidemiology, while prevention targets sexual, blood-borne and vertical routes.","sourceLocations":[{"assessment":"Midterm","batch":"431","questionNumber":49,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":69049},{"id":"community-mid-prevention-and-control-of-infectious-d7348b83","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"431","sourceLabel":"Community Medicine Gift","stem":"What's the goal of the malaria control program?","options":[{"id":"A","text":"Interruption of transmission"},{"id":"B","text":"Global eradication of malaria"},{"id":"C","text":"Global elimination if malaria"},{"id":"D","text":"Elimination of Mosquitoes breeding"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Interruption of transmission. Malaria-control programmes aim to reduce transmission, illness and death through vector control, prevention, surveillance, prompt diagnosis and effective treatment.","sourceLocations":[{"assessment":"Midterm","batch":"431","questionNumber":50,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":69050},{"id":"community-mid-prevention-and-control-of-infectious-364e739d","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"431","sourceLabel":"Community Medicine Gift","stem":"Which of the following preventive measures is included in the malaria control program ?","options":[{"id":"A","text":"Isolation of cases"},{"id":"B","text":"Immunoglobulin"},{"id":"C","text":"Mass vaccination"},{"id":"D","text":"Case management"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D (book)","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Case management. Malaria-control programmes aim to reduce transmission, illness and death through vector control, prevention, surveillance, prompt diagnosis and effective treatment.","sourceLocations":[{"assessment":"Midterm","batch":"431","questionNumber":51,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":69051},{"id":"community-mid-prevention-and-control-of-infectious-e3722335","subjectId":"community","lecture":"Prevention and Control of Infectious Disease Pandemics","assessment":"Midterm","sourceBatch":"431","sourceLabel":"Community Medicine Gift","stem":"Which of the following factors could explain the high prevalence of H pylori in some communities ?","options":[{"id":"A","text":"Poor vaccination coverage"},{"id":"B","text":"Poor socioeconomic state"},{"id":"C","text":"High prevalence of overweight and obesity"},{"id":"D","text":"Large number of children in the community"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Poor socioeconomic state. Prevalence includes all existing cases at a point or during a period. It is influenced by both incidence and disease duration.","sourceLocations":[{"assessment":"Midterm","batch":"431","questionNumber":52,"sourceType":"Gift"}],"references":[{"title":"CDC Principles of Epidemiology — Chain of Infection","url":"https://archive.cdc.gov/www_cdc_gov/csels/dsepd/ss1978/lesson1/section10.html"}],"lectureOrder":6,"referenceOrder":69052},{"id":"community-mid-surveillance-and-screening-264660c9","subjectId":"community","lecture":"Surveillance and Screening","assessment":"Midterm","sourceBatch":"431","sourceLabel":"Community Medicine Gift","stem":"What is the most efficient test to estimate the prevalence of H pylori in the community ?","options":[{"id":"A","text":"Serologic assay"},{"id":"B","text":"Stool antigen test"},{"id":"C","text":"Microbiological culture"},{"id":"D","text":"Histological examination"}],"images":[],"incompleteSource":false,"sourceAnswer":"A","sourceAnswerNote":"A","aiAnswer":"A","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Serologic assay. Prevalence includes all existing cases at a point or during a period. It is influenced by both incidence and disease duration.","sourceLocations":[{"assessment":"Midterm","batch":"431","questionNumber":53,"sourceType":"Gift"}],"references":[{"title":"WHO — Screening programmes: a short guide","url":"https://www.who.int/publications/i/item/9789289054782"}],"lectureOrder":5,"referenceOrder":69053},{"id":"community-mid-global-demography-concepts-and-popul-039d93ff","subjectId":"community","lecture":"Global Demography Concepts and Population Pyramid","assessment":"Midterm","sourceBatch":"431","sourceLabel":"Community Medicine Gift","stem":"What are the elements of demography?","options":[{"id":"A","text":"Person, place and time distribution of diseases"},{"id":"B","text":"Population size, composition and distribution"},{"id":"C","text":"Fertility, mortality and case fatality"},{"id":"D","text":"Education, occupation and residence"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Population size, composition and distribution. Population size and structure change through fertility, mortality and migration; these are the core demographic components.","sourceLocations":[{"assessment":"Midterm","batch":"431","questionNumber":54,"sourceType":"Gift"}],"references":[{"title":"United Nations World Population Prospects","url":"https://www.un.org/development/desa/pd/content/world-population-prospects-2024"}],"lectureOrder":2,"referenceOrder":69054},{"id":"community-mid-global-demography-concepts-and-popul-3f10f283","subjectId":"community","lecture":"Global Demography Concepts and Population Pyramid","assessment":"Midterm","sourceBatch":"431","sourceLabel":"Community Medicine Gift","stem":"Which one of the following is a characteristic of the population pyramid in Saudi Arabia in recent years?","options":[{"id":"A","text":"The base of the pyramid is narrow"},{"id":"B","text":"The sides of the pyramid are steep"},{"id":"C","text":"The young dependency ratio is high"},{"id":"D","text":"The median age of the population is high"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is The young dependency ratio is high. The dependency ratio compares younger and older dependants with the working-age population, usually expressed per 100 working-age people.","sourceLocations":[{"assessment":"Midterm","batch":"431","questionNumber":55,"sourceType":"Gift"}],"references":[{"title":"United Nations World Population Prospects","url":"https://www.un.org/development/desa/pd/content/world-population-prospects-2024"}],"lectureOrder":2,"referenceOrder":69055},{"id":"community-mid-global-demography-concepts-and-popul-4710c8fd","subjectId":"community","lecture":"Global Demography Concepts and Population Pyramid","assessment":"Midterm","sourceBatch":"431","sourceLabel":"Community Medicine Gift","stem":"Which one of the following population parameters poses a major problem in developing countries ?","options":[{"id":"A","text":"High median age"},{"id":"B","text":"Long life expectancy"},{"id":"C","text":"High old dependency ratio"},{"id":"D","text":"High young dependency ratio"}],"images":[],"incompleteSource":false,"sourceAnswer":"D","sourceAnswerNote":"D","aiAnswer":"D","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is High young dependency ratio. The dependency ratio compares younger and older dependants with the working-age population, usually expressed per 100 working-age people.","sourceLocations":[{"assessment":"Midterm","batch":"431","questionNumber":56,"sourceType":"Gift"}],"references":[{"title":"United Nations World Population Prospects","url":"https://www.un.org/development/desa/pd/content/world-population-prospects-2024"}],"lectureOrder":2,"referenceOrder":69056},{"id":"community-mid-global-demography-concepts-and-popul-03e2f1f8","subjectId":"community","lecture":"Global Demography Concepts and Population Pyramid","assessment":"Midterm","sourceBatch":"431","sourceLabel":"Community Medicine Gift","stem":"The 2011 data from MOH, KSA indicates that the crude birth rate is 22.9\\1000 population and the crude death rate is 3.9\\1000 population. Considering the above scenario, Which ONE of the following is the \" Rate of natural increase\" for KSA ?","options":[{"id":"A","text":"0.19%"},{"id":"B","text":"1.9%"},{"id":"C","text":"2.0%"},{"id":"D","text":"19%"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B (22.9 - 3.9) / 10 = 1.9%","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is 1.9%. The crude death rate is all deaths during the period divided by the mid-year population, usually expressed per 1,000 population.","sourceLocations":[{"assessment":"Midterm","batch":"431","questionNumber":57,"sourceType":"Gift"}],"references":[{"title":"United Nations World Population Prospects","url":"https://www.un.org/development/desa/pd/content/world-population-prospects-2024"}],"lectureOrder":2,"referenceOrder":69057},{"id":"community-mid-maternal-health-5c8cab93","subjectId":"community","lecture":"Maternal Health","assessment":"Midterm","sourceBatch":"431","sourceLabel":"Community Medicine Gift","stem":"The 2011 data from MOH, KSA indicates that the estimated mid-year population was 28,376,355, while the number of live births was 650,000 and the number of maternal deaths was 95 Considering the above data, Which ONE of the following is the \" Maternal mortality ratio\" for KSA?","options":[{"id":"A","text":"3.34"},{"id":"B","text":"14.6"},{"id":"C","text":"18.8"},{"id":"D","text":"22.9 The following diagram points to the natural history of disease from the stage of susceptibility to recovery\\ disability \\ death. The following question (59) is about this diagram."}],"images":["question-media/community/community-431-q58.png"],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B (95*100,000)/650,000 = 14.6","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is 14.6. The maternal mortality ratio is maternal deaths during a period divided by live births in the same period, conventionally multiplied by 100,000.","sourceLocations":[{"assessment":"Midterm","batch":"431","questionNumber":58,"sourceType":"Gift"}],"references":[{"title":"WHO — Maternal health","url":"https://www.who.int/health-topics/maternal-health"}],"lectureOrder":11,"referenceOrder":69058},{"id":"community-mid-surveillance-and-screening-49fd650c","subjectId":"community","lecture":"Surveillance and Screening","assessment":"Midterm","sourceBatch":"431","sourceLabel":"Community Medicine Gift","stem":"At which stage in the natural history of disease, public health concept of screening is applied? Number 1 Number 2","options":[{"id":"A","text":"Number 3"},{"id":"B","text":"Number 4"},{"id":"C","text":"The following diagram presents result of a screening test:"},{"id":"D","text":"Table: Screening test | True disease | True disease | Total / Screening test | Present | Absent | Total / Positive | a | b | a+b / Negative | c | d | c+d / Total | a+c | b+d | N"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Number 4. Secondary prevention detects disease early in apparently healthy people so timely treatment can reduce progression or complications.","sourceLocations":[{"assessment":"Midterm","batch":"431","questionNumber":59,"sourceType":"Gift"}],"references":[{"title":"WHO — Screening programmes: a short guide","url":"https://www.who.int/publications/i/item/9789289054782"}],"lectureOrder":5,"referenceOrder":69059},{"id":"community-mid-surveillance-and-screening-d54c5c62","subjectId":"community","lecture":"Surveillance and Screening","assessment":"Midterm","sourceBatch":"431","sourceLabel":"Community Medicine Gift","stem":"Which equation is used to calculate the specificity of a screening test ?","options":[{"id":"A","text":"b\\(a+b)"},{"id":"B","text":"b\\ (b+d)"},{"id":"C","text":"d\\(b+d)"},{"id":"D","text":"d\\(c+d)"}],"images":[],"incompleteSource":false,"sourceAnswer":"C","sourceAnswerNote":"C","aiAnswer":"C","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is d\\(b+d). Specificity is the proportion of people without the condition who test negative: TN/(TN+FP). A highly specific test therefore minimizes false positives.","sourceLocations":[{"assessment":"Midterm","batch":"431","questionNumber":60,"sourceType":"Gift"}],"references":[{"title":"WHO — Screening programmes: a short guide","url":"https://www.who.int/publications/i/item/9789289054782"}],"lectureOrder":5,"referenceOrder":69060},{"id":"community-mid-surveillance-and-screening-51e9d0bc","subjectId":"community","lecture":"Surveillance and Screening","assessment":"Midterm","sourceBatch":"431","sourceLabel":"Community Medicine Gift","stem":"What are the drawbacks of a screening program with high false positive results ?","options":[{"id":"A","text":"False reassurance"},{"id":"B","text":"Emotional distress"},{"id":"C","text":"Delays in diagnosis"},{"id":"D","text":"Missed chances of treatment"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is Emotional distress. Secondary prevention detects disease early in apparently healthy people so timely treatment can reduce progression or complications.","sourceLocations":[{"assessment":"Midterm","batch":"431","questionNumber":61,"sourceType":"Gift"}],"references":[{"title":"WHO — Screening programmes: a short guide","url":"https://www.who.int/publications/i/item/9789289054782"}],"lectureOrder":5,"referenceOrder":69061},{"id":"community-mid-surveillance-and-screening-4e3cade8","subjectId":"community","lecture":"Surveillance and Screening","assessment":"Midterm","sourceBatch":"431","sourceLabel":"Community Medicine Gift","stem":"What is the factor increasing the positive predictive value of a screening test ? Screening the general population Screening among high risk groups Screening among healthy volunteers Screening among low prevalence populations","options":[{"id":"A","text":"تم بحمد الله"},{"id":"B","text":"نهاية الأسئلة"},{"id":"C","text":"لاتنسونا من خالص دعائكم"},{"id":"D","text":"بالتوفيق لكم جميعاً"}],"images":[],"incompleteSource":false,"sourceAnswer":"B","sourceAnswerNote":"B","aiAnswer":"B","aiSuggestion":null,"verification":"supported","explanation":"The recorded answer is نهاية الأسئلة. Positive predictive value is TP/(TP+FP) and rises as disease prevalence rises, assuming the test characteristics stay the same.","sourceLocations":[{"assessment":"Midterm","batch":"431","questionNumber":62,"sourceType":"Gift"}],"references":[{"title":"WHO — Screening programmes: a short guide","url":"https://www.who.int/publications/i/item/9789289054782"}],"lectureOrder":5,"referenceOrder":69062}];
